@import url("https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&family=Raleway:wght@500;600;700&display=swap");

@property --progress {
  syntax: "<percentage>";
  inherits: false;
  initial-value: 0%;
}

:root {
  color-scheme: light;
  --font-body: "Poppins", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-heading: "Raleway", "Poppins", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
    sans-serif;
  --bg: #f5f7f9;
  --surface: #ffffff;
  --surface-2: #f5f7f9;
  --surface-3: #e9eef2;
  --stroke: #dbe3e8;
  --stroke-strong: #c9d4db;
  --text: #1f2933;
  --muted: #6b7280;
  --muted-2: #9ca3af;
  --accent: #03a8c0;
  --accent-hover: #0289a0;
  --accent-light: #5ed3d0;
  --accent-mint: #6ee7b7;
  --accent-soft: rgba(3, 168, 192, 0.1);
  --accent-strong: rgba(3, 168, 192, 0.18);
  --brand-gradient: linear-gradient(135deg, #03a8c0, #5ed3d0);
  --brand-gradient-alt: linear-gradient(135deg, #03a8c0, #6ee7b7);
  --good: #22c55e;
  --positive: var(--good);
  --warn: #f59e0b;
  --bad: #ef4444;
  --negative: var(--bad);
  --shadow: 0 14px 30px rgba(31, 41, 51, 0.08);
  --shadow-soft: 0 6px 14px rgba(31, 41, 51, 0.05);
  --radius: 24px;
  --radius-sm: 16px;
  --focus-ring: 0 0 0 4px rgba(3, 168, 192, 0.18);
  --page-shell: rgba(255, 255, 255, 0.84);
  --action-button-height: 32px;
  --action-button-padding-inline: 10px;
  --action-button-font-size: 0.78rem;
  --action-button-font-size-compact: 0.72rem;
  --action-button-font-weight: 600;
}

/* Mobile Settings is a focused detail view: labels stay left and controls stay right. */
.settings-session-item__identity {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.settings-session-device-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  flex: none;
  border-radius: 15px;
  color: #079eb5;
  background: linear-gradient(145deg, rgba(175, 241, 231, 0.72), rgba(216, 247, 251, 0.9));
  box-shadow: inset 0 0 0 1px rgba(3, 168, 192, 0.13);
}

.settings-session-device-icon svg {
  width: 34px;
  height: 34px;
  fill: rgba(255, 255, 255, 0.7);
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.settings-category-table--plain {
  overflow: visible;
  border: 0;
  border-radius: 0;
  background: transparent;
}

.settings-category-table--plain .settings-category-table__row--compact {
  grid-template-columns: minmax(0, 1fr) auto;
  padding-inline: 0;
}

.settings-category-icon-button,
.settings-category-icon-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: pointer;
}

.settings-category-icon-button {
  border-radius: 12px;
}

.settings-category-icon-action {
  width: 28px;
  height: 28px;
  color: var(--accent);
}

.settings-category-icon-action--delete {
  color: #dc2626;
}

.settings-category-icon-action svg {
  width: 20px;
  height: 20px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.settings-category-icon-action:disabled {
  opacity: 0.25;
  cursor: default;
}

.settings-category-table--plain .settings-category-table__name-copy {
  width: 100%;
}

.settings-category-table--plain .settings-category-table__name-copy input {
  width: 100%;
  min-height: 32px;
  padding: 2px 0;
  border: 0;
  border-bottom: 1px solid transparent;
  border-radius: 0;
  background: transparent;
  font-weight: 500;
}

.settings-category-table--plain .settings-category-table__name-copy input:focus {
  border-bottom-color: var(--accent);
  box-shadow: none;
}

.settings-category-section--custom .settings-category-section__head h5 {
  font-size: 12px;
  font-weight: 500;
}

.settings-category-creator {
  padding: 0;
  border: 0;
  background: transparent;
}

.settings-plan-card--pro .settings-plan-card__band {
  background: linear-gradient(135deg, #09abc0 0%, #78e6bf 100%);
}

.settings-plan-card--pro .settings-plan-card__band-title,
.settings-plan-card--pro .settings-plan-card__band-price {
  color: #ffffff;
}

.settings-plan-card--pro .settings-plan-card__icon {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.18);
}

.settings-plan-card__icon svg {
  width: 20px;
  height: 20px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.settings-plan-interval {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 3px;
  width: fit-content;
  padding: 3px;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.14);
}

.settings-plan-interval button {
  min-height: 30px;
  padding: 0 12px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--muted);
  font-size: 12px;
  font-weight: 500;
}

.settings-plan-interval button.is-selected {
  color: #083d2f;
  background: #83e8c4;
}

.settings-plan-usage {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0;
  border-block: 1px solid var(--stroke);
}

.settings-plan-usage__row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(100px, 34%);
  align-items: center;
  gap: 16px;
  min-height: 54px;
  padding: 8px 2px;
  border-bottom: 1px solid var(--stroke);
}

.settings-plan-usage__row:last-child {
  border-bottom: 0;
}

.settings-plan-usage__row--current {
  grid-template-columns: minmax(0, 1fr) auto;
}

.settings-plan-usage__row strong,
.settings-plan-usage__row > span {
  color: #1f2937;
  font-size: 13px;
  font-weight: 500;
}

.settings-plan-usage__copy {
  display: grid;
  gap: 3px;
}

.settings-plan-usage__copy span {
  color: var(--muted);
  font-size: 12px;
}

.settings-plan-unsubscribe {
  display: flex;
  justify-content: flex-start;
}

@media (max-width: 1100px) {
  .settings-hub--mobile-panel .settings-section__intro {
    display: none;
  }

  .settings-hub--mobile-panel .settings-section {
    gap: 12px;
  }

  .settings-hub--mobile-panel .settings-hub__panel {
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
  }

  .settings-hub--mobile-panel .button,
  .settings-hub--mobile-panel button,
  .settings-hub--mobile-panel select {
    font-weight: 500;
  }

  .settings-toggle-row {
    grid-template-columns: minmax(0, 1fr) auto;
    min-height: 32px;
    padding: 3px 0;
    gap: 10px;
  }

  .settings-toggle-row__copy strong {
    font-weight: 500;
  }

  .settings-section--data .settings-data-shell {
    padding: 0;
    border: 0;
    background: transparent;
    box-shadow: none;
  }

  .settings-section--data .settings-data-shell__grid {
    grid-template-columns: 1fr;
    gap: 14px;
  }

  .settings-section--data .settings-data-zone {
    gap: 10px;
    padding: 14px;
    border-radius: 18px;
  }

  .settings-section--data .settings-data-zone__header h6 {
    font-size: 18px;
    font-weight: 500;
  }

  .settings-section--data .settings-data-export-actions,
  .settings-section--data .settings-data-danger-list {
    gap: 0;
  }

  .settings-section--data .settings-data-export-card,
  .settings-section--data .settings-data-danger-item,
  .settings-section--data .settings-data-danger-item--history {
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: 10px;
    min-height: 56px;
    padding: 10px 4px;
    border: 0;
    border-bottom: 1px solid var(--stroke);
    border-radius: 0;
    background: transparent;
    text-align: left;
  }

  .settings-section--data .settings-data-export-card:last-child,
  .settings-section--data .settings-data-danger-item:last-child {
    border-bottom: 0;
  }

  .settings-section--data .settings-data-export-card strong,
  .settings-section--data .settings-data-danger-copy strong {
    font-size: 14px;
    font-weight: 500;
    text-align: left;
  }

  .settings-section--data .settings-data-danger-copy {
    justify-self: start;
    text-align: left;
  }

  .settings-section--data .settings-data-danger-controls {
    width: auto;
    justify-content: flex-end;
  }

  .settings-section--data .settings-data-export-card .button,
  .settings-section--data .settings-data-danger-item .button-danger,
  .settings-section--data .settings-data-danger-item .button-danger--history {
    justify-self: end;
    width: auto;
    min-width: 76px;
    padding-inline: 12px;
  }

  .settings-section--data .settings-inline-field--history {
    min-width: 0;
  }

  .settings-section--data .settings-data-privacy {
    padding: 14px;
  }

  .settings-section--regional .settings-preference-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .settings-section--regional .settings-preference-card {
    gap: 0;
    padding: 0 14px;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
  }

  .settings-section--regional .settings-inline-field {
    grid-template-columns: minmax(90px, 0.7fr) minmax(170px, 1.3fr);
    align-items: center;
    gap: 12px;
    width: 100%;
    min-width: 0;
    min-height: 58px;
    border-bottom: 1px solid var(--stroke);
  }

  .settings-section--regional .settings-inline-field span {
    color: var(--text);
    font-weight: 400;
  }

  .settings-section--regional .settings-inline-field select {
    min-width: 0;
    width: 100%;
    justify-self: end;
  }

  .settings-section--security .settings-security-card {
    padding: 0;
    border: 0;
    background: transparent;
    box-shadow: none;
  }

  .settings-section--security .settings-preference-card__head {
    padding-inline: 2px;
  }

  .settings-session-item {
    grid-template-columns: minmax(0, 1fr) auto;
    min-height: 66px;
    padding: 8px 2px;
  }

  .settings-session-device-icon {
    width: 44px;
    height: 44px;
    border-radius: 14px;
  }

  .settings-session-device-icon svg {
    width: 30px;
    height: 30px;
  }

  .settings-category-manager > .settings-section__intro {
    display: none;
  }

  .settings-category-manager {
    gap: 12px;
  }

  .settings-category-table--plain .settings-category-table__row--compact {
    grid-template-columns: minmax(0, 1fr) auto;
    min-height: 46px;
    padding-block: 5px;
  }

  .settings-category-table__name {
    gap: 8px;
  }

  .settings-category-table__icon {
    width: 32px;
    height: 32px;
  }

  .settings-category-creator__fields {
    grid-template-columns: 1fr;
    gap: 8px;
  }

  .settings-category-section--custom .settings-category-section__head {
    padding-top: 4px;
  }

  .settings-plan-grid {
    display: grid;
    grid-auto-flow: column;
    grid-auto-columns: minmax(84%, 1fr);
    grid-template-columns: none;
    gap: 12px;
    width: calc(100% + 20px);
    margin-right: -20px;
    padding: 2px 20px 10px 0;
    overflow-x: auto;
    overscroll-behavior-inline: contain;
    scroll-snap-type: x mandatory;
    scrollbar-width: none;
  }

  .settings-plan-grid::-webkit-scrollbar {
    display: none;
  }

  .settings-plan-card {
    min-width: 0;
    scroll-snap-align: start;
    overflow: hidden;
  }

  .settings-plan-card__band {
    padding: 14px;
  }

  .settings-plan-card__body {
    padding: 14px;
  }

  .settings-plan-card__features {
    gap: 8px;
  }

  .settings-plan-card__feature-row .plan-feature-item__info {
    display: none;
  }

  .settings-plan-card__feature-row .plan-feature-item__info-wrap {
    display: none;
  }

  .settings-plan-grid--current-pro .settings-plan-card--pro {
    order: -1;
  }
}

html[data-theme="dark"] .settings-session-device-icon {
  color: #64dfed;
  background: linear-gradient(145deg, rgba(17, 94, 108, 0.72), rgba(17, 49, 65, 0.9));
}

html[data-theme="dark"] .settings-category-table--plain,
html[data-theme="dark"] .settings-category-creator,
html[data-theme="dark"] .settings-section--data .settings-data-shell,
html[data-theme="dark"] .settings-section--data .settings-data-export-card,
html[data-theme="dark"] .settings-section--data .settings-data-danger-item {
  background: transparent;
}

/* Compact pricing cards and a responsive iOS-style billing toggle. */
.pricing-page__comparison { align-items: stretch; }
.pricing-page .pricing-card {
  height: 100%;
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  align-content: stretch;
}
.pricing-page .pricing-card__top { min-height: 52px; }
.pricing-page .pricing-card__icon,
.pricing-page .pricing-card__icon--featured { width: 52px; height: 52px; flex: 0 0 52px; }
.pricing-page .pricing-card--featured .pricing-card__icon--featured { background: #fff; border-color: #fff; color: #008ea5; }
.pricing-page .pricing-card__summary { min-height: 38px; margin: 4px 0 8px; }
.pricing-page .pricing-card__list { margin: 0; }
.pricing-page .pricing-pro-selector__billing { display: inline-grid; grid-template-columns: repeat(2, minmax(0, 1fr)); width: min(184px, 100%); padding: 3px; gap: 3px; overflow: hidden; }
.pricing-page .pricing-pro-selector__billing-thumb { display: none; }
.pricing-page .pricing-card--featured .pricing-pro-selector__billing { background: rgb(255 255 255 / 30%); border-color: rgb(255 255 255 / 46%); }
.pricing-page .pricing-pro-selector__billing button { width: 100%; min-width: 0; min-height: 34px; padding: 0 10px; transition: color 180ms ease, background-color 180ms ease, box-shadow 180ms ease; }
.pricing-page .pricing-pro-selector__billing button.is-selected,
.pricing-page .pricing-card--featured .pricing-pro-selector__billing button.is-selected { color: #073844; background: #fff; box-shadow: 0 2px 8px rgb(0 55 71 / 16%); }
.pricing-page .pricing-card--featured .pricing-pro-selector__billing button { color: #fff; }
.pricing-page .pricing-card--featured .pricing-pro-selector__billing button:focus-visible { outline: 2px solid #fff; outline-offset: 1px; }
.pricing-page .pricing-card--featured .pricing-pro-selector__price span,
.pricing-page .pricing-card--featured .pricing-pro-selector__saving,
.pricing-page .pricing-card--featured .pricing-pro-selector__saving s { color: rgb(255 255 255 / 88%); }
.pricing-page .pricing-card--featured .pricing-pro-selector__signup { color: #fff; }
.pricing-page .pricing-pro-selector--active { min-height: 36px; color: #fff; font-size: .82rem; }
.pricing-page .pricing-pro-selector--active p { margin: 0; }
.onboarding-upgrade__interval { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; margin: 18px 0; }
.onboarding-upgrade__interval button { min-height: 44px; border: 1px solid rgb(0 157 178 / 24%); border-radius: 999px; background: #fff; color: var(--text); cursor: pointer; font: inherit; }
.onboarding-upgrade__interval button.is-selected { border-color: var(--accent); background: var(--accent); color: #fff; }
.onboarding-upgrade__actions { display: grid; gap: 12px; }
.onboarding-upgrade__paypal { min-height: 42px; }
.settings-plan-card.is-preferred { outline: 2px solid var(--accent); outline-offset: 3px; }

@media (max-width: 1100px) {
  .pricing-page__comparison { grid-template-rows: repeat(2, minmax(0, 1fr)); }
  .pricing-page .pricing-card--featured { order: -1; }
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
  background:
    radial-gradient(circle at top left, rgba(3, 168, 192, 0.08), transparent 28%),
    radial-gradient(circle at right 14%, rgba(110, 231, 183, 0.08), transparent 30%),
    var(--bg);
}

body {
  margin: 0;
  min-height: 100vh;
  overflow-x: clip;
  overflow-y: auto;
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.5;
  background:
    radial-gradient(circle at top left, rgba(3, 168, 192, 0.08), transparent 34%),
    radial-gradient(circle at 20% 0%, rgba(110, 231, 183, 0.08), transparent 22%),
    linear-gradient(180deg, #ffffff 0%, #f5f8fa 100%);
  color: var(--text);
  accent-color: var(--accent);
}

/* Public landing content scrolls with the document, not inside the body. */
html:has(.landing-page--snap) {
  overflow-x: clip;
  overflow-y: auto;
}

body:has(.landing-page--snap) {
  overflow: visible !important;
}

h1,
h2,
h3,
h4,
h5,
h6 {
  font-family: var(--font-heading);
  color: var(--text);
}

h1 {
  margin: 0;
  font-size: 30px;
  line-height: 1.25;
  font-weight: 600;
  letter-spacing: -0.04em;
}

h2 {
  margin: 0;
  font-size: 22px;
  line-height: 1.25;
  font-weight: 600;
  letter-spacing: -0.035em;
}

h3 {
  margin: 0;
  font-size: 18px;
  line-height: 1.3;
  font-weight: 500;
  letter-spacing: -0.03em;
}

h4 {
  margin: 0;
  font-size: 16px;
  line-height: 1.3;
  font-weight: 500;
  letter-spacing: -0.025em;
}

h5,
h6 {
  margin: 0;
  font-size: 15px;
  line-height: 1.35;
  font-weight: 500;
  letter-spacing: -0.02em;
}

p {
  margin: 0;
  font-size: 16px;
  line-height: 1.5;
}

small,
.caption {
  font-size: 12px;
  line-height: 1.4;
}

a {
  color: inherit;
  text-decoration: none;
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

button,
input,
select,
textarea {
  font-family: inherit;
}

button {
  cursor: pointer;
  font-size: 15px;
  font-weight: 500;
  line-height: 1.2;
}

input,
select,
textarea {
  border-radius: 14px;
  border: 1px solid var(--stroke);
  background: rgba(255, 255, 255, 0.94);
  color: var(--text);
  min-height: 44px;
  padding: 0 14px;
  font-size: 16px;
}

textarea {
  min-height: 120px;
  padding: 12px 14px;
}

label {
  display: grid;
  gap: 8px;
  color: var(--muted);
  font-size: 14px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.app-shell {
  position: relative;
  display: grid;
  grid-template-columns: 236px minmax(0, 1fr);
  gap: 0;
  min-height: 100dvh;
  height: auto;
  overflow-x: clip;
  overflow-y: visible;
  background:
    radial-gradient(circle at 12% 8%, rgba(3, 168, 192, 0.05), transparent 20%),
    linear-gradient(180deg, #ffffff 0%, #f5f8fa 100%);
}

.route-loading-fallback {
  position: fixed;
  z-index: 120;
  top: 0;
  left: 0;
  width: 100%;
  height: 2px;
  overflow: hidden;
  color: transparent;
  pointer-events: none;
  opacity: 0;
  background: linear-gradient(90deg, transparent, var(--accent), var(--mint), transparent);
  background-size: 220% 100%;
  animation: route-loading-reveal 0.01s 0.3s forwards, route-loading-progress 1s linear 0.3s infinite;
}

@keyframes route-loading-reveal {
  to { opacity: 1; }
}

@keyframes route-loading-progress {
  to { background-position: -220% 0; }
}

body[data-clover-page-modal] .app-shell {
  grid-template-columns: 236px minmax(0, 1fr);
}

body.dashboard-modal-open .app-shell {
  grid-template-columns: 236px minmax(0, 1fr);
}

.sidebar-backdrop {
  display: none;
}

.glass {
  background: rgba(255, 255, 255, 0.88);
  border: 1px solid var(--stroke);
  box-shadow: var(--shadow);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}

.auth-page {
  position: relative;
  min-height: 100dvh;
  display: grid;
  place-items: center;
  padding: 32px 20px;
  overflow-x: hidden;
  overflow-y: auto;
}

.auth-page::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 18% 18%, rgba(3, 168, 192, 0.08), transparent 26%),
    radial-gradient(circle at 80% 20%, rgba(110, 231, 183, 0.08), transparent 24%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.92), rgba(245, 248, 250, 0.98));
  pointer-events: none;
}

.auth-page::after {
  content: "";
  position: absolute;
  inset: auto auto 12% 8%;
  width: 220px;
  height: 220px;
  border-radius: 999px;
  background: radial-gradient(circle, rgba(94, 211, 208, 0.12), transparent 72%);
  filter: blur(6px);
  pointer-events: none;
}

.auth-page > * {
  position: relative;
  z-index: 1;
}

.clover-auth-card {
  width: min(100%, 520px);
  margin: 0 auto;
  padding: 14px 18px 0;
  border: 1px solid var(--stroke);
  border-radius: 24px;
  background: rgba(255, 255, 255, 0.98);
  box-shadow: var(--shadow);
  overflow: hidden;
  display: grid;
  gap: 12px;
}

.clover-auth-card__brand {
