  color: var(--text);
  border-radius: 50%;
  width: 44px;
  height: 44px;
  align-items: center;
  justify-content: center;
  flex: none;
  box-shadow: var(--shadow-soft);
}

.shell-back-button--mobile-only {
  display: none;
}

.shell-back-button:hover,
.shell-back-button:focus-visible {
  background: rgba(3, 168, 192, 0.08);
  border-color: rgba(3, 168, 192, 0.18);
}

.shell-back-button svg {
  width: 18px;
  height: 18px;
}

.content-mobile-bar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.topbar {
  padding: 0 0 10px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
}

.topbar.glass,
.shell-compact-bar.glass {
  background: transparent;
  border: 0;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

.topbar__title-wrap {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 12px;
  min-width: 0;
  justify-self: start;
  justify-items: start;
  text-align: left;
}

.topbar__title-row {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 14px;
  min-width: 0;
  white-space: nowrap;
}

.topbar__title-row h1,
.shell-compact-bar__copy h1 {
  margin: 0;
  font-size: 15px;
  line-height: 1.15;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.topbar__title-addon {
  display: flex;
  align-items: baseline;
  min-width: 0;
}

.contextual-ask-clover {
  position: relative;
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
}

.contextual-ask-clover__trigger {
  position: relative;
  display: inline-grid;
  width: 48px;
  height: 48px;
  place-items: center;
  border: 0;
  padding: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
}

.contextual-ask-clover__icon {
  width: 48px;
  height: 48px;
  object-fit: contain;
  transition: transform 160ms ease, filter 160ms ease;
}

.contextual-ask-clover__trigger:hover .contextual-ask-clover__icon,
.contextual-ask-clover__trigger:focus-visible .contextual-ask-clover__icon,
.contextual-ask-clover__trigger[aria-expanded="true"] .contextual-ask-clover__icon {
  transform: translateY(-1px) scale(1.06);
  filter: drop-shadow(0 5px 8px rgba(3, 168, 192, 0.2));
}

.contextual-ask-clover__trigger:focus-visible {
  outline: 2px solid rgba(3, 168, 192, 0.42);
  outline-offset: 3px;
  border-radius: 7px;
}

.contextual-ask-clover__tooltip {
  position: absolute;
  top: calc(100% + 9px);
  left: 50%;
  z-index: 120;
  width: max-content;
  max-width: min(260px, calc(100vw - 24px));
  transform: translate(-50%, -3px);
  border-radius: 9px;
  padding: 7px 10px;
  background: #172033;
  color: #ffffff;
  font-size: 0.72rem;
  font-weight: 600;
  line-height: 1.25;
  white-space: nowrap;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 140ms ease, transform 140ms ease, visibility 140ms ease;
}

.contextual-ask-clover__trigger:hover .contextual-ask-clover__tooltip,
.contextual-ask-clover__trigger:focus-visible .contextual-ask-clover__tooltip {
  transform: translate(-50%, 0);
  opacity: 1;
  visibility: visible;
}

.contextual-ask-clover__dismiss-layer {
  position: fixed;
  inset: 0;
  z-index: 1090;
  border: 0;
  padding: 0;
  background: transparent;
  cursor: default;
}

.contextual-ask-clover__panel {
  position: fixed;
  top: 70px;
  right: 24px;
  z-index: 1100;
  display: flex;
  width: min(460px, calc(100vw - 32px));
  max-height: min(700px, calc(100dvh - 94px));
  flex-direction: column;
  overflow: hidden;
  border: 1px solid rgba(11, 27, 43, 0.1);
  border-radius: 22px;
  background: var(--surface);
  color: var(--foreground);
  box-shadow: 0 24px 70px rgba(15, 23, 42, 0.2);
  animation: contextual-ask-clover-in 180ms ease-out both;
}

@keyframes contextual-ask-clover-in {
  from {
    opacity: 0;
    transform: translateY(-6px) scale(0.985);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.contextual-ask-clover__panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  border-bottom: 1px solid rgba(11, 27, 43, 0.08);
  padding: 15px 17px;
}

.contextual-ask-clover__panel-title {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.contextual-ask-clover__panel-title > img {
  width: 31px;
  height: 31px;
  flex: 0 0 auto;
  object-fit: contain;
}

.contextual-ask-clover__panel-title .eyebrow {
  margin: 0 0 2px;
}

.contextual-ask-clover__panel-title h2 {
  margin: 0;
  font-size: 1rem;
  line-height: 1.2;
}

.contextual-ask-clover__close {
  display: grid;
  width: 30px;
  height: 30px;
  flex: 0 0 auto;
  place-items: center;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: var(--muted);
  font: inherit;
  font-size: 1.25rem;
  cursor: pointer;
}

.contextual-ask-clover__close:hover,
.contextual-ask-clover__close:focus-visible {
  background: rgba(11, 27, 43, 0.06);
  color: var(--foreground);
}

.contextual-ask-clover__chat {
  min-height: 210px;
  overflow: auto;
  padding: 17px;
}

.contextual-ask-clover__chat .adviser-chat__ask-label {
  display: none;
}

.contextual-ask-clover__chat .adviser-chat__thread {
  max-height: min(390px, calc(100dvh - 325px));
}

.contextual-ask-clover__chat .adviser-chat__prompt-row {
  max-height: 142px;
  overflow-y: auto;
}

.contextual-ask-clover__chat .adviser-chat--locked {
  align-items: flex-start;
  flex-direction: column;
}

.contextual-ask-clover__chat .adviser-chat__locked-preview {
  width: 100%;
}

.contextual-ask-clover__loading {
  margin: 0;
  color: var(--muted);
  font-size: 0.86rem;
}

html[data-theme="dark"] .contextual-ask-clover__panel {
  border-color: rgba(148, 163, 184, 0.18);
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.44);
}

html[data-theme="dark"] .contextual-ask-clover__panel-header {
  border-bottom-color: rgba(148, 163, 184, 0.14);
}

html[data-theme="dark"] .contextual-ask-clover__close:hover,
html[data-theme="dark"] .contextual-ask-clover__close:focus-visible {
  background: rgba(148, 163, 184, 0.12);
}

@media (max-width: 1100px) {
  .contextual-ask-clover__tooltip {
    display: none;
  }

  .contextual-ask-clover__panel {
    top: auto;
    right: 10px;
    bottom: 10px;
    left: 10px;
    width: auto;
    max-height: min(680px, calc(100dvh - 20px));
    border-radius: 20px;
  }

  .contextual-ask-clover__chat {
    min-height: 190px;
    padding: 15px;
  }

  .contextual-ask-clover__chat .adviser-chat__thread {
    max-height: calc(100dvh - 350px);
  }
}

.topbar-subtitle {
  margin: 0;
  color: var(--muted);
  line-height: 1.5;
  max-width: 54ch;
}

.topbar-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
  justify-self: end;
}

.transactions-page .topbar-actions {
  flex-wrap: nowrap;
  margin-left: auto;
}

.transactions-page .topbar__title-wrap {
  flex: 0 1 auto;
  margin-right: auto;
}

.content-body {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
  min-height: 0;
  overflow: visible;
  padding-top: 2px;
  padding-right: 2px;
  padding-bottom: 12px;
}

.content-body > * {
  min-width: 0;
}

.content-body > :first-child {
  margin-top: 0;
}

.mobile-nav {
  display: none;
}

.mobile-nav__item {
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-decoration: none;
  display: grid;
  justify-items: center;
  gap: 4px;
  padding: 10px 4px 9px;
  border-radius: 18px;
  min-width: 0;
  transition:
    transform 160ms ease,
    background-color 160ms ease,
    color 160ms ease;
}

.mobile-nav__item:hover,
.mobile-nav__item:focus-visible,
.mobile-nav__item.is-active {
  background: rgba(3, 168, 192, 0.12);
  color: var(--accent);
  outline: none;
}

.mobile-nav__item:hover,
.mobile-nav__item:focus-visible {
  transform: translateY(-1px);
}

.mobile-nav__item--button {
  cursor: pointer;
  width: 100%;
}

.mobile-nav__icon {
  width: 20px;
  height: 20px;
  display: grid;
  place-items: center;
}

.mobile-nav__label {
  font-size: 11px;
  line-height: 1.1;
  letter-spacing: 0.02em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.settings-layout {
  display: grid;
  grid-template-columns: minmax(280px, 320px) minmax(0, 1fr);
  gap: 16px;
  align-items: start;
}

.settings-sidebar {
  position: sticky;
  top: 0;
  display: grid;
  gap: 14px;
  padding: 18px;
  border-radius: 28px;
  max-height: calc(100dvh - 110px);
  overflow: auto;
}

.settings-search {
  display: grid;
  gap: 8px;
}

.settings-search span,
.settings-jump__label,
.settings-submenu__title {
  color: var(--muted-2);
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: capitalize;
}

.settings-search input {
  width: 100%;
}

.settings-submenu {
  display: grid;
  gap: 10px;
}

.settings-submenu__link {
  display: grid;
  gap: 3px;
  padding: 12px 14px;
  border-radius: 16px;
  border: 1px solid transparent;
  background: rgba(247, 249, 250, 0.72);
  color: var(--muted);
  transition: background 160ms ease, border-color 160ms ease, color 160ms ease, transform 160ms ease;
}

.settings-submenu__link-title {
  font-size: 14px;
  line-height: 1.25;
  color: var(--text);
}

.settings-submenu__link-summary {
  font-size: 12px;
  line-height: 1.4;
  color: var(--muted);
}

.settings-submenu__link:hover {
  border-color: rgba(3, 168, 192, 0.12);
  background: rgba(3, 168, 192, 0.08);
  color: var(--text);
  transform: translateX(1px);
}

.settings-main {
  display: grid;
  gap: 16px;
  min-width: 0;
}

.settings-card {
  display: grid;
  gap: 18px;
  padding: 24px;
  border-radius: 28px;
  scroll-margin-top: 20px;
}

.settings-card__head {
  display: grid;
  gap: 8px;
}

.settings-card__summary {
  max-width: 58ch;
  color: var(--muted);
  line-height: 1.55;
}

.settings-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.settings-section-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 14px;
}

.settings-section-grid__item {
  min-width: 0;
}

.settings-advanced {
  display: grid;
  gap: 14px;
  padding: 12px 14px 14px;
  border-radius: 18px;
  border: 1px solid rgba(15, 23, 42, 0.08);
  background: rgba(247, 249, 250, 0.72);
}

.settings-advanced summary {
  list-style: none;
  cursor: pointer;
  display: grid;
  gap: 2px;
  color: var(--text);
}

.settings-advanced summary::-webkit-details-marker {
  display: none;
}

.settings-advanced summary span {
  font-size: 13px;
  font-weight: 500;
}

.settings-advanced summary small {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}

.settings-advanced__grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 14px;
}

.settings-choice {
  display: grid;
  gap: 10px;
  margin: 0;
  padding: 0;
  border: 0;
}

.settings-choice legend {
  display: grid;
  gap: 6px;
  padding: 0;
  color: var(--muted);
  font-size: 14px;
}

.settings-choice legend span {
  color: var(--text);
  font-weight: 500;
  font-size: 14px;
}

.settings-choice legend small {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}

.settings-choice__options {
  display: grid;
  gap: 8px;
}

.settings-choice__option {
  display: grid;
  gap: 4px;
  padding: 12px 14px;
  border-radius: 18px;
  border: 1px solid rgba(15, 23, 42, 0.08);
  background: rgba(247, 249, 250, 0.82);
  cursor: pointer;
  transition: background 160ms ease, border-color 160ms ease, transform 160ms ease, box-shadow 160ms ease;
}

.settings-choice__option input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.settings-choice__option.is-selected {
  background: rgba(3, 168, 192, 0.08);
  border-color: rgba(3, 168, 192, 0.16);
  box-shadow: 0 8px 18px rgba(3, 168, 192, 0.08);
}

.settings-choice__option:hover {
  transform: translateY(-1px);
}

.settings-choice__label {
  font-size: 14px;
  line-height: 1.3;
  color: var(--text);
}

.settings-choice__helper {
  font-size: 12px;
  line-height: 1.45;
  color: var(--muted);
}

.settings-field {
  display: grid;
  gap: 8px;
  color: var(--text);
  font-size: 14px;
}

.settings-field span {
  color: var(--muted);
}

.settings-field input {
  min-height: 42px;
  background: rgba(247, 249, 250, 0.92);
}

.settings-field textarea,
.settings-field select {
  min-height: 42px;
  background: rgba(247, 249, 250, 0.92);
  border-radius: 14px;
}

.settings-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  min-height: 64px;
  padding: 15px 16px;
  border-radius: 18px;
  border: 1px solid rgba(15, 23, 42, 0.08);
  background: rgba(247, 249, 250, 0.86);
}

.settings-toggle__copy {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.settings-toggle__copy strong {
  font-size: 14px;
  letter-spacing: -0.02em;
}

.settings-toggle__copy span {
  color: var(--muted);
  font-size: 13px;
  line-height: 1.45;
}

.settings-switch {
  position: relative;
  width: 46px;
  height: 28px;
  flex: none;
}

.settings-switch input {
  position: absolute;
  inset: 0;
  margin: 0;
  opacity: 0;
}

.settings-switch span {
  position: absolute;
  inset: 0;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.4);
  border: 1px solid rgba(148, 163, 184, 0.18);
  transition: background 160ms ease, border-color 160ms ease;
}

.settings-switch span::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: white;
  box-shadow: 0 4px 10px rgba(15, 23, 42, 0.14);
  transition: transform 160ms ease;
}

.settings-switch input:checked + span {
  background: rgba(3, 168, 192, 0.95);
  border-color: rgba(3, 168, 192, 0.24);
}

.settings-switch input:checked + span::after {
  transform: translateX(18px);
}

.account-actions-panel {
  display: grid;
  gap: 18px;
  margin-top: 20px;
}

.account-actions-panel__head {
  display: grid;
  gap: 8px;
}

.account-actions-panel__grid {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.account-actions-panel__note {
  font-size: 13px;
  color: var(--muted);
}

.account-actions-modal {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(15, 23, 42, 0.5);
  backdrop-filter: blur(10px);
}

.account-actions-modal__card {
  width: min(620px, 100%);
  margin: 0;
  box-shadow: 0 32px 80px rgba(15, 23, 42, 0.2);
}

.account-actions-modal__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 16px;
}

.account-actions-modal__copy {
  margin: 0 0 18px;
  color: var(--muted);
  line-height: 1.65;
}

.account-actions-modal__field {
  display: grid;
  gap: 10px;
}

.account-actions-modal__field span {
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--text-strong);
}

.account-actions-modal__field input {
  width: 100%;
  border-radius: 18px;
  border: 1px solid var(--stroke);
  background: rgba(255, 255, 255, 0.95);
  padding: 16px 18px;
  font-size: 1rem;
  color: var(--text-strong);
  outline: none;
  transition:
    border-color 0.2s ease,
    box-shadow 0.2s ease,
    transform 0.2s ease;
}

.account-actions-modal__field input:focus {
  border-color: rgba(3, 168, 192, 0.5);
  box-shadow: 0 0 0 4px rgba(3, 168, 192, 0.12);
}

.account-actions-modal__helper {
  margin: 12px 0 0;
  color: var(--muted);
  font-size: 0.92rem;
  line-height: 1.55;
}

.account-actions-modal__actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  margin-top: 22px;
}

.settings-empty {
  display: grid;
  gap: 8px;
  padding: 28px;
  border-radius: 28px;
}

.settings-empty p {
  color: var(--muted);
  max-width: 52ch;
}

@media (max-width: 1100px) {
  .app-shell {
    grid-template-columns: 1fr;
    min-height: 100dvh;
    height: auto;
    overflow-x: clip;
    overflow-y: visible;
  }

  .sidebar {
    position: fixed;
    inset: 12px auto 12px 12px;
    width: min(330px, calc(100vw - 24px));
    height: auto;
    max-height: calc(100dvh - 24px);
    min-height: 0;
    border-right: 0;
    border-bottom: 0;
    border: 1px solid var(--stroke);
    border-radius: 28px;
    box-shadow: var(--shadow);
    transform: translateX(calc(-100% - 20px));
    transition: transform 180ms ease, visibility 180ms ease;
    z-index: 90;
    visibility: hidden;
  }

  .app-shell.is-sidebar-open .sidebar {
    transform: translateX(0);
    visibility: visible;
  }

  .sidebar-backdrop {
    display: block;
    position: fixed;
    inset: 0;
    z-index: 80;
    background: rgba(15, 23, 42, 0.22);
  }

  .app-shell:not(.is-sidebar-open) .sidebar-backdrop {
    pointer-events: none;
    opacity: 0;
  }

  .settings-layout {
    grid-template-columns: 1fr;
  }

  .settings-sidebar {
    position: relative;
    top: auto;
    max-height: none;
  }

  .content {
    padding: 18px 18px calc(220px + env(safe-area-inset-bottom));
    scroll-padding-bottom: calc(220px + env(safe-area-inset-bottom));
    min-height: 0;
    overflow: visible;
  }

  .transactions-page .content {
    height: 100dvh;
    overflow: hidden;
  }

  .topbar {
    border-radius: 24px;
  }

  .settings-layout,
  .settings-form,
  .settings-section-grid {
    grid-template-columns: 1fr;
  }

  .settings-advanced__grid {
    grid-template-columns: 1fr;
  }

  .shell-quick-add-button {
    display: none !important;
  }

  .shell-menu-button {
    display: none !important;
  }

  .shell-bottom-nav {
    position: fixed;
    left: 12px;
    right: 12px;
    bottom: calc(10px + env(safe-area-inset-bottom));
    z-index: 111;
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    align-items: center;
    gap: 4px;
    padding: 8px;
    border-radius: 24px;
    border: 1px solid rgba(255, 255, 255, 0.46);
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.88), rgba(246, 248, 250, 0.82));
    box-shadow:
      0 16px 30px rgba(15, 23, 42, 0.16),
      inset 0 1px 0 rgba(255, 255, 255, 0.66);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
  }

  .shell-bottom-nav__item,
  .shell-bottom-nav__add {
    appearance: none;
    border: 0;
    background: transparent;
    color: var(--muted);
    display: grid;
    justify-items: center;
    gap: 2px;
    min-width: 0;
    padding: 5px 2px 4px;
    border-radius: 16px;
    text-align: center;
  }

  .shell-bottom-nav__item {
    min-height: 56px;
    transition: background 160ms ease, color 160ms ease, transform 160ms ease;
  }

  .shell-bottom-nav__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    color: var(--muted-2);
  }

  .shell-bottom-nav__icon .menu-icon-3d {
    width: 34px;
    height: 34px;
  }

  .shell-bottom-nav__icon .menu-icon-3d--home {
    width: 36px;
    height: 36px;
  }

  .shell-bottom-nav__icon .menu-icon-3d--adviser {
    width: 36px;
    height: 36px;
  }

  .shell-bottom-nav__label {
    font-size: 11px;
    line-height: 1.1;
    letter-spacing: -0.01em;
  }

  .shell-bottom-nav__item.is-active {
    color: var(--text);
  }

  .shell-bottom-nav__item.is-active .shell-bottom-nav__icon {
    color: var(--accent);
  }

  .shell-bottom-nav__add {
    width: 54px;
    height: 54px;
    margin: 0 auto;
    border-radius: 999px;
    grid-column: 3;
    align-self: center;
    background: var(--brand-gradient);
    color: #fff;
    box-shadow: 0 16px 30px rgba(3, 168, 192, 0.24);
    justify-self: center;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    transition: background 160ms ease, transform 160ms ease, box-shadow 160ms ease;
  }

  .shell-bottom-nav__add:hover,
  .shell-bottom-nav__add:focus-visible {
    background: var(--brand-gradient-alt);
    transform: translateY(-1px);
  }

  .shell-bottom-nav__add svg {
    width: 18px;
    height: 18px;
  }

  .shell-quick-add-popover {
    left: 12px;
    right: 12px;
    bottom: calc(86px + env(safe-area-inset-bottom));
    min-width: 0;
  }

  .shell-quick-add-popover__item--mobile-only {
    display: grid;
  }

  .content--more > .topbar {
    min-height: 44px;
    padding-block: 0;
    margin-bottom: 2px;
  }

  .content--more > .topbar .shell-back-button {
    align-self: center;
  }

  .content--more > .topbar .topbar__title-wrap {
    top: 50%;
  }

  .more-page {
    gap: 0;
  }

  .more-page__sections {
    grid-template-columns: 1fr;
    gap: 4px;
  }

  .more-page__section {
    gap: 4px;
    padding-top: 4px;
  }

  .more-page__section-label {
    font-size: 12px;
    font-weight: 400;
    line-height: 1.1;
    letter-spacing: 0;
    text-transform: none;
  }

  .more-page__links {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 2px;
  }

  .more-page__link {
    min-height: 0;
    padding: 1px 0 3px;
    gap: 1px;
    border-radius: 0;
    border: 0;
    background: transparent;
    box-shadow: none;
  }

  .more-page__link:hover,
  .more-page__link:focus-visible {
    border-color: transparent;
    background: transparent;
    transform: none;
  }

  .more-page__link-icon {
    width: auto;
    height: auto;
    border-radius: 0;
    background: transparent;
    color: var(--accent);
  }

  .more-page__link-icon-image {
    width: 54px;
    height: 54px;
  }

  .more-page__link-label {
    font-size: 12px;
    font-weight: 400;
    line-height: 1.05;
  }
}

.hero {
  display: grid;
  grid-template-columns: minmax(0, 1.22fr) minmax(300px, 0.78fr);
  gap: 18px;
  align-items: center;
}

.hero-copy,
.hero-metrics,
.feature-card,
.overview-panel {
  border-radius: 28px;
}

.hero-copy {
  padding: 22px 16px 22px 6px;
}

.hero-copy h3 {
  margin: 10px 0 14px;
  font-size: 32px;
  line-height: 1.22;
  font-weight: 600;
  letter-spacing: -0.04em;
  max-width: 18ch;
}

.hero-copy p {
  margin: 0;
  max-width: 58ch;
  color: var(--muted);
  line-height: 1.5;
  font-size: 16px;
}

.hero-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 18px;
}

.hero-metrics {
  padding: 14px;
  border: 1px solid var(--stroke);
  background: rgba(255, 255, 255, 0.8);
  box-shadow: var(--shadow);
  display: grid;
  gap: 10px;
}

.metric {
  background: rgba(245, 249, 251, 0.9);
  border: 1px solid var(--stroke);
  border-radius: 22px;
  padding: 14px 15px 13px;
  box-shadow: var(--shadow-soft);
}

.metric span {
  display: block;
  color: var(--muted);
  margin-bottom: 6px;
  font-size: 12px;
}

.metric strong {
  display: block;
  font-size: 24px;
  line-height: 1.15;
  font-weight: 600;
  letter-spacing: -0.04em;
}

.metric small {
  display: block;
  margin-top: 4px;
  color: var(--muted);
  line-height: 1.45;
  font-size: 14px;
}

.metric.compact {
  padding: 12px 14px;
  border-radius: 18px;
}

.metric.compact strong {
  font-size: 20px;
}

.metric--highlight {
  display: grid;
  gap: 8px;
  padding: 16px 18px 17px;
}

.metric--highlight span {
  margin-bottom: 0;
  font-size: 12px;
  text-transform: capitalize;
  letter-spacing: 0.1em;
}

.metric--highlight strong {
  font-size: 30px;
  line-height: 1.08;
}

.metric--highlight small {
  display: none;
}

.feature-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.dashboard-visual-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(320px, 0.85fr);
  gap: 14px;
}

.dashboard-visual-card {
  display: grid;
  gap: 14px;
  padding: 20px;
  border: 1px solid var(--stroke);
  background:
    radial-gradient(circle at top left, rgba(3, 168, 192, 0.12), transparent 34%),
    rgba(255, 255, 255, 0.92);
  box-shadow: var(--shadow);
}

.dashboard-visual-card__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.dashboard-visual-card__head h4 {
  margin: 6px 0 0;
  font-size: 22px;
  line-height: 1.2;
  letter-spacing: -0.04em;
}

.dashboard-visual-pill {
  display: inline-flex;
  align-items: center;
  min-height: 32px;
  padding: 0 12px;
  border-radius: 999px;
  border: 1px solid rgba(15, 23, 42, 0.08);
  background: rgba(255, 255, 255, 0.82);
  color: var(--text);
  font-size: 0.82rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.dashboard-visual-pill.positive {
  border-color: rgba(34, 197, 94, 0.18);
  background: rgba(34, 197, 94, 0.1);
  color: #15803d;
}

.dashboard-visual-pill.negative {
  border-color: rgba(245, 158, 11, 0.2);
  background: rgba(245, 158, 11, 0.1);
  color: #a16207;
}

.dashboard-line-chart {
  display: grid;
  gap: 12px;
}

.dashboard-line-chart svg {
  width: 100%;
  height: auto;
  display: block;
}

.dashboard-line-chart__labels {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 8px;
}

.dashboard-line-chart__label {
  display: grid;
  gap: 4px;
  padding: 10px 10px 9px;
  border-radius: 16px;
  background: rgba(247, 249, 250, 0.85);
  border: 1px solid rgba(15, 23, 42, 0.05);
}

.dashboard-line-chart__label strong {
  font-size: 12px;
  font-weight: 600;
  color: var(--muted);
}

.dashboard-line-chart__label span {
  font-size: 14px;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.dashboard-category-bars {
  display: grid;
  gap: 12px;
}

.dashboard-category-bars__item {
  display: grid;
  gap: 8px;
}

.dashboard-category-bars__meta {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.dashboard-category-bars__meta strong {
  font-size: 14px;
  letter-spacing: -0.02em;
}

.dashboard-category-bars__meta span {
  color: var(--muted);
  font-size: 13px;
  white-space: nowrap;
}

.dashboard-category-bars__track {
  height: 12px;
  border-radius: 999px;
  background: rgba(3, 168, 192, 0.08);
  overflow: hidden;
}

.dashboard-category-bars__fill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, rgba(3, 168, 192, 0.55), rgba(3, 168, 192, 0.95));
}

.dashboard-category-bars__fill--1 {
  background: linear-gradient(90deg, rgba(14, 165, 233, 0.55), rgba(14, 165, 233, 0.95));
}

.dashboard-category-bars__fill--2 {
  background: linear-gradient(90deg, rgba(139, 92, 246, 0.5), rgba(139, 92, 246, 0.95));
}

.dashboard-category-bars__fill--3 {
  background: linear-gradient(90deg, rgba(20, 184, 166, 0.5), rgba(20, 184, 166, 0.95));
}

.dashboard-empty-visual {
  display: grid;
  gap: 6px;
  padding: 16px;
  border-radius: 16px;
  border: 1px dashed rgba(3, 168, 192, 0.18);
  background: rgba(255, 255, 255, 0.84);
  color: var(--muted);
}

.dashboard-loading {
  display: grid;
  gap: 14px;
}

.dashboard-loading__hero {
  display: grid;
  gap: 12px;
}

.dashboard-loading__priority {
  min-width: 0;
}

.dashboard-loading__metrics {
  gap: 12px;
}

.dashboard-loading__metric {
  display: grid;
  gap: 10px;
}

.dashboard-loading__eyebrow {
  width: 96px;
  height: 12px;
}

.dashboard-loading__title {
  width: min(18ch, 100%);
  height: 34px;
}

.dashboard-loading__priority-title {
  width: min(28ch, 100%);
  height: 24px;
}

.dashboard-loading__copy {
  width: min(48ch, 100%);
  height: 18px;
}

.dashboard-loading__priority-copy {
  width: min(42ch, 100%);
  height: 18px;
}

.dashboard-loading__value {
  width: 120px;
  height: 28px;
}

.dashboard-loading__actions {
  margin-top: 10px;
}

.dashboard-loading__button {
  width: 118px;
  height: 40px;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(233, 238, 242, 0.8) 25%, rgba(244, 247, 249, 0.98) 50%, rgba(233, 238, 242, 0.8) 75%);
  background-size: 200% 100%;
  animation: skeleton-shimmer 1.4s ease-in-out infinite;
}

.dashboard-loading__position-card {
  gap: 8px;
  min-height: 100px;
}

.dashboard-visual-skeleton {
  min-height: 310px;
}

.dashboard-visual-skeleton__stack {
  display: grid;
  gap: 8px;
  min-width: 160px;
}

.dashboard-visual-skeleton__pill {
  width: 86px;
  height: 32px;
  border-radius: 999px;
}

.dashboard-visual-skeleton__chart {
  display: grid;
  gap: 14px;
}

.dashboard-visual-skeleton__spark {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  align-items: end;
  gap: 10px;
  min-height: 150px;
  padding: 14px 2px 2px;
}

.dashboard-visual-skeleton__dot {
  height: 10px;
  border-radius: 999px;
}

.dashboard-visual-skeleton__labels {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 8px;
}

.dashboard-visual-skeleton__label {
  height: 52px;
  border-radius: 16px;
}

.dashboard-visual-skeleton__bars {
  display: grid;
  gap: 14px;
}

.dashboard-visual-skeleton__bar {
  display: grid;
  gap: 8px;
}

.dashboard-visual-skeleton__bar-fill {
  height: 12px;
  border-radius: 999px;
}

.dashboard-home {
  display: grid;
  gap: 14px;
}

.dashboard-home__priority-strip {
  display: flex;
