  box-shadow: var(--shadow-soft);
}

.dashboard-home__priority-copy {
  display: grid;
  gap: 10px;
  min-width: 0;
}

.dashboard-home__priority-copy h4 {
  margin: 0;
  font-size: 22px;
  line-height: 1.15;
  letter-spacing: -0.04em;
}

.dashboard-home__priority-copy p {
  margin: 0;
  color: var(--muted);
  line-height: 1.5;
  font-size: 14px;
  max-width: 68ch;
}

.dashboard-home__priority-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  flex: none;
