.dashboard-home__hero-main-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.dashboard-home__hero-main .eyebrow {
  color: rgba(255, 255, 255, 0.82);
}

.dashboard-home__hero-main strong {
