  white-space: nowrap;
}

.dashboard-home__hero-mini-label {
  margin: 0;
  color: rgba(82, 89, 112, 0.74);
  font-size: 12px;
  line-height: 1.2;
  letter-spacing: 0.1em;
  text-transform: capitalize;
  white-space: nowrap;
}

.dashboard-home__hero-mini-trend--unavailable {
  color: var(--muted-2);
