  align-items: start;
  padding-top: 72px;
}

.dashboard-manual-modal__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.dashboard-manual-modal__head h4 {
  margin: 6px 0 0;
  font-size: 24px;
  line-height: 1.1;
  letter-spacing: -0.05em;
}

.dashboard-manual-modal__copy {
  margin: 0;
