.dashboard-home__report-card--positive {
  background: rgba(255, 255, 255, 0.9);
}

.dashboard-home__report-card--warning {
  background: rgba(255, 255, 255, 0.9);
}

.dashboard-home__report-card-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: flex-start;
}

.dashboard-home__report-card h4 {
  margin: 4px 0 0;
  color: var(--text-strong);
  font-size: clamp(1.4rem, 2.6vw, 2rem);
  line-height: 1.05;
  letter-spacing: -0.055em;
}

.dashboard-home__report-card p {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.45;
}

.dashboard-home__report-card .dashboard-home__report-note {
  margin-top: 6px;
  color: var(--muted-2);
  font-size: 12px;
}

.dashboard-home__report-card .eyebrow,
.dashboard-home__goal-card-head .eyebrow,
.dashboard-home__insight-strip > .eyebrow {
  margin: 0 0 6px;
  color: var(--muted-2);
  font-size: 12px;
  font-weight: 400;
  line-height: 1.45;
  letter-spacing: 0.14em;
}

.dashboard-home__report-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.dashboard-home__report-metrics span {
  display: grid;
  gap: 3px;
  min-width: 0;
  padding: 9px 10px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid rgba(3, 168, 192, 0.12);
}

.dashboard-home__report-metrics small {
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: capitalize;
}

.dashboard-home__report-metrics strong {
  min-width: 0;
  overflow: hidden;
  color: var(--text-strong);
  font-size: 13px;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dashboard-home__report-metric-value--income {
  color: var(--good) !important;
}

.dashboard-home__report-metric-value--expense {
  color: var(--bad) !important;
}

.dashboard-home__report-flow {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.dashboard-home__report-flow-bars {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  align-items: end;
  gap: 5px;
  height: 74px;
  padding-top: 6px;
  border-top: 1px solid rgba(3, 168, 192, 0.12);
}

.dashboard-home__report-flow--monthly .dashboard-home__report-flow-bars {
  grid-template-columns: repeat(31, minmax(0, 1fr));
  gap: 2px;
  height: 64px;
}

.dashboard-home__report-flow-bar {
  position: relative;
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
  gap: 4px;
  min-width: 0;
  height: 100%;
}

.dashboard-home__report-flow-track {
  display: flex;
  flex-direction: column-reverse;
  justify-content: flex-start;
  min-height: 0;
  height: 100%;
  overflow: hidden;
  border-radius: 4px;
  background: transparent;
}

.dashboard-home__report-flow-segment {
  display: block;
  width: 100%;
  min-height: 0;
  overflow: hidden;
  border-radius: 0;
  transition: height 180ms ease;
}

.dashboard-home__report-flow-segment[data-edge="only"] {
  border-radius: 4px;
}

.dashboard-home__report-flow-segment[data-edge="bottom"] {
  border-radius: 0 0 4px 4px;
}

.dashboard-home__report-flow-segment[data-edge="top"] {
  border-radius: 4px 4px 0 0;
}

.dashboard-home__report-flow-segment[data-active="true"] {
  min-height: 3px;
}

.dashboard-home__report-flow-segment--income {
  background: #22c55e;
}

.dashboard-home__report-flow-segment--expense {
  background: #ef4444;
}

.dashboard-home__report-flow-label {
  overflow: hidden;
  color: var(--muted-2);
  font-size: 9px;
  line-height: 1;
  text-align: center;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dashboard-home__report-flow-tooltip {
  position: absolute;
  z-index: 8;
  bottom: calc(100% + 7px);
  left: 50%;
  display: grid;
  width: max-content;
  max-width: 210px;
  gap: 2px;
  padding: 8px 10px;
  border: 1px solid var(--stroke);
  border-radius: 12px;
  color: var(--text-strong);
  background: rgba(255, 255, 255, 0.98);
  box-shadow: var(--shadow-soft);
  font-size: 10px;
  line-height: 1.35;
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, 4px);
  transition: opacity 120ms ease, transform 120ms ease;
}

.dashboard-home__report-flow-timeline {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  color: var(--muted-2);
  font-size: 9px;
  line-height: 1;
}

.dashboard-home__report-flow-timeline span {
  text-align: center;
}

.dashboard-home__report-flow-timeline span:first-child {
  text-align: left;
}

.dashboard-home__report-flow-timeline span:last-child {
  text-align: right;
}

.dashboard-home__report-flow-tooltip strong {
  font-size: 10px;
}

.dashboard-home__report-flow-tooltip span {
  color: var(--muted);
}

.dashboard-home__report-flow-bar:first-child .dashboard-home__report-flow-tooltip {
  left: 0;
  transform: translate(0, 4px);
}

.dashboard-home__report-flow-bar:last-child .dashboard-home__report-flow-tooltip {
  right: 0;
  left: auto;
  transform: translate(0, 4px);
}

.dashboard-home__report-flow-bar:hover .dashboard-home__report-flow-tooltip,
.dashboard-home__report-flow-bar:focus-visible .dashboard-home__report-flow-tooltip {
  opacity: 1;
  transform: translate(-50%, 0);
}

.dashboard-home__report-flow-bar:first-child:hover .dashboard-home__report-flow-tooltip,
.dashboard-home__report-flow-bar:first-child:focus-visible .dashboard-home__report-flow-tooltip,
.dashboard-home__report-flow-bar:last-child:hover .dashboard-home__report-flow-tooltip,
.dashboard-home__report-flow-bar:last-child:focus-visible .dashboard-home__report-flow-tooltip {
  transform: translate(0, 0);
}

.dashboard-home__report-flow-legend {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--muted-2);
  font-size: 9px;
}

.dashboard-home__report-flow-legend span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.dashboard-home__report-flow-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
}

.dashboard-home__report-flow-dot--income {
  background: #22c55e;
}

.dashboard-home__report-flow-dot--expense {
  background: #ef4444;
}

.dashboard-home__report-flow--loading .dashboard-home__report-flow-bars {
  border-top-color: transparent;
}

.dashboard-home__report-flow-loading-bar {
  display: flex;
  align-items: flex-end;
  height: 100%;
  overflow: hidden;
  border-radius: 6px;
  background: rgba(233, 238, 242, 0.58);
}

.dashboard-home__report-flow-loading-bar .skeleton-block {
  width: 100%;
  height: 56%;
  border-radius: 6px;
}

.dashboard-home__report-link {
  width: fit-content;
  color: var(--accent);
  font-size: 13px;
  font-weight: 800;
  text-decoration: none;
}

.dashboard-home__report-link:hover {
  text-decoration: underline;
}

.dashboard-home__insight-strip {
  display: grid;
  gap: 10px;
  padding: 14px 16px;
  border: 1px solid var(--stroke);
  border-radius: 24px;
  background: rgba(255, 255, 255, 0.9);
  box-shadow: var(--shadow-soft);
}

.dashboard-home__insight-strip-list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.dashboard-home__insight-strip-empty {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 42px;
  color: var(--muted);
  font-size: 13px;
  font-weight: 400;
}

.dashboard-home__insight-strip-item {
  min-width: 0;
  display: grid;
  gap: 4px;
  padding: 10px 12px;
  border-radius: 18px;
  background: rgba(3, 168, 192, 0.06);
  align-content: start;
}

.dashboard-home__insight-strip-item--positive {
  background: linear-gradient(135deg, rgba(220, 252, 231, 0.88), rgba(236, 253, 245, 0.72));
}

.dashboard-home__insight-strip-item--warning {
  background: linear-gradient(135deg, rgba(255, 237, 237, 0.9), rgba(255, 247, 237, 0.72));
}

.dashboard-home__insight-strip-label {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 6px;
}

.dashboard-home__insight-strip-label span:not(.dashboard-home__insight-strip-emoji) {
  color: var(--muted);
  font-size: 11px;
  font-weight: 400;
  letter-spacing: 0.12em;
  text-transform: capitalize;
}

.dashboard-home__insight-strip-emoji {
  font-size: 15px;
  line-height: 1;
}

.dashboard-home__insight-strip-copy {
  color: var(--text-strong);
  font-size: 13px;
  font-weight: 400;
  line-height: 1.35;
}

.dashboard-home__insight-strip-action {
  width: fit-content;
  margin-top: 4px;
  color: var(--accent);
  font-size: 12px;
  font-weight: 800;
  text-decoration: none;
}

.dashboard-home__insight-strip-action:hover {
  text-decoration: underline;
}

.dashboard-home__hero-side {
  display: grid;
  gap: 12px;
  align-self: stretch;
  height: 100%;
}

.dashboard-home__hero-side > * {
  height: 100%;
}

.dashboard-home__goal-card,
.dashboard-home__starter-card {
  display: grid;
  gap: 14px;
  padding: 16px;
  border-radius: 28px;
  border: 1px solid var(--stroke);
  background: rgba(255, 255, 255, 0.9);
  box-shadow: var(--shadow);
  height: 100%;
}

.dashboard-home__goal-card {
  align-content: start;
}

.dashboard-home__goal-card--empty {
  grid-template-columns: 1fr;
  align-items: start;
}

.dashboard-home__goal-card-head {
  display: flex;
  justify-content: flex-start;
  align-items: flex-start;
}

.dashboard-home__goal-card-body {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 14px;
  align-items: center;
}

.dashboard-home__goal-card-copy {
  display: grid;
  gap: 8px;
}

.dashboard-home__goal-card-copy strong,
.dashboard-home__starter-card strong {
  font-size: 18px;
  line-height: 1.15;
  letter-spacing: -0.03em;
}

.dashboard-home__goal-card-copy p,
.dashboard-home__starter-card p {
  margin: 0;
  color: var(--muted);
  line-height: 1.5;
  font-size: 14px;
}

.dashboard-home__goal-card-copy small {
  color: var(--muted);
  line-height: 1.45;
  font-size: 12px;
}

.dashboard-home__action-card-heading {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.dashboard-home__action-card-heading > div {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.dashboard-home__action-card-heading strong {
  color: var(--text-strong);
  font-size: 15px;
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

.dashboard-home__action-card-heading small {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.35;
}

.dashboard-home__status-check {
  display: inline-grid;
  flex: 0 0 auto;
  width: 30px;
  height: 30px;
  place-items: center;
  border-radius: 50%;
  background: rgba(34, 197, 94, 0.12);
  color: #16a34a;
  font-size: 16px;
  font-weight: 900;
  line-height: 1;
}

.dashboard-home__status-check--calendar {
  border-radius: 9px;
  background: rgba(3, 168, 192, 0.1);
  color: var(--accent);
}

.dashboard-home__status-check--attention {
  background: rgba(239, 68, 68, 0.1);
  color: var(--bad);
}

.dashboard-home__action-list {
  display: grid;
  min-width: 0;
  border-top: 1px solid rgba(148, 163, 184, 0.2);
}

.dashboard-home__action-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 9px;
  align-items: center;
  min-width: 0;
  padding: 8px 0;
  border-bottom: 1px solid rgba(148, 163, 184, 0.16);
}

.dashboard-home__action-row:last-child {
  border-bottom: 0;
}

.dashboard-home__action-row[data-completed="true"] .dashboard-home__action-row-copy strong {
  color: var(--muted);
  text-decoration: line-through;
}

.dashboard-home__action-row-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.dashboard-home__action-row-copy strong {
  overflow: hidden;
  color: var(--text-strong);
  font-size: 12px;
  font-weight: 750;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dashboard-home__action-row-copy small {
  overflow: hidden;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.3;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dashboard-home__payment-check {
  display: inline-grid;
  width: 22px;
  height: 22px;
  padding: 0;
  place-items: center;
  border: 1px solid rgba(3, 168, 192, 0.4);
  border-radius: 7px;
  background: transparent;
  color: #ffffff;
  font-size: 12px;
  font-weight: 900;
  line-height: 1;
  cursor: pointer;
}

.dashboard-home__payment-check[aria-checked="true"] {
  border-color: var(--accent);
  background: var(--accent);
}

.dashboard-home__payment-check:disabled {
  cursor: wait;
  opacity: 0.58;
}

.dashboard-home__payment-check--suggestion {
  border-color: rgba(148, 163, 184, 0.35);
  color: var(--muted);
  cursor: default;
}

.dashboard-home__review-dot {
  width: 7px;
  height: 7px;
  margin-inline: 7px 8px;
  border-radius: 50%;
  background: var(--bad);
}

.dashboard-home__mini-action {
  display: inline-flex;
  min-height: 25px;
  align-items: center;
  justify-content: center;
  padding: 4px 9px;
  border: 1px solid rgba(3, 168, 192, 0.28);
  border-radius: 999px;
  color: var(--accent);
  font-size: 10px;
  font-weight: 800;
  line-height: 1;
  text-decoration: none;
}

.dashboard-home__mini-action:hover {
  border-color: var(--accent);
  background: rgba(3, 168, 192, 0.06);
}

.dashboard-home__action-error {
  margin: 0;
  color: var(--bad);
  font-size: 10px;
  line-height: 1.35;
}

.dashboard-home__starter-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.dashboard-home__activity-card {
  display: grid;
  gap: 14px;
  padding: 16px;
  border: 1px solid var(--stroke);
  border-radius: 28px;
  background: rgba(255, 255, 255, 0.9);
  box-shadow: var(--shadow);
}

.dashboard-home__activity-chart {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 10px;
  align-items: end;
  min-height: 178px;
}

.dashboard-home__activity-bar {
  display: grid;
  gap: 8px;
  justify-items: center;
  align-content: end;
  min-width: 0;
}

.dashboard-home__activity-bar-count {
  min-height: 16px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1;
}

.dashboard-home__activity-bar-track {
  width: 100%;
  height: 126px;
  padding: 8px 7px 7px;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  border-radius: 18px;
  border: 1px solid rgba(15, 23, 42, 0.06);
  background:
    linear-gradient(180deg, rgba(3, 168, 192, 0.08), rgba(255, 255, 255, 0.9)),
    rgba(255, 255, 255, 0.76);
}

.dashboard-home__activity-bar-fill {
  width: 100%;
  max-width: 26px;
  min-height: 6px;
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(3, 168, 192, 0.9), rgba(3, 168, 192, 0.4));
  box-shadow: 0 10px 20px rgba(3, 168, 192, 0.18);
}

.dashboard-home__activity-bar-label {
  color: var(--muted);
  font-size: 11px;
  text-transform: capitalize;
  letter-spacing: 0.11em;
}

.dashboard-home__activity-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.dashboard-home__copy {
  display: grid;
  gap: 14px;
  align-content: start;
}

.dashboard-home__kicker-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.dashboard-home__copy h3 {
  margin: 0;
  max-width: 16ch;
  font-size: clamp(1.55rem, 3vw, 2.45rem);
  line-height: 1.03;
  letter-spacing: -0.055em;
}

.dashboard-home__copy p {
  margin: 0;
  max-width: 58ch;
  color: var(--muted);
  line-height: 1.55;
  font-size: 15px;
}

.dashboard-home__decision-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.dashboard-home__decision-card {
  display: grid;
  gap: 5px;
  padding: 14px 15px;
  border-radius: 22px;
  border: 1px solid rgba(15, 23, 42, 0.06);
  background: rgba(255, 255, 255, 0.82);
  box-shadow: var(--shadow-soft);
}

.dashboard-home__decision-card--strong {
  grid-column: 1 / -1;
  padding: 18px;
}

.dashboard-home__decision-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.dashboard-home__decision-head h4 {
  font-size: 16px;
  line-height: 1.15;
  letter-spacing: -0.03em;
}

.dashboard-home__decision-card span {
  color: var(--muted);
  font-size: 12px;
  text-transform: capitalize;
  letter-spacing: 0.12em;
}

.dashboard-home__decision-card strong {
  font-size: 15px;
  line-height: 1.15;
  letter-spacing: -0.04em;
}

.dashboard-home__decision-card small {
  color: var(--muted);
  line-height: 1.45;
  font-size: 13px;
}

.dashboard-home__change-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.dashboard-home__change-grid .dashboard-home__item {
  min-height: 100%;
}

.dashboard-home__rail {
  display: grid;
  gap: 10px;
  align-content: start;
}

.dashboard-home__rail-card {
  display: grid;
  gap: 12px;
  padding: 14px;
  border-radius: 24px;
  border: 1px solid rgba(15, 23, 42, 0.06);
  background: rgba(255, 255, 255, 0.74);
  box-shadow: var(--shadow-soft);
}

.dashboard-home__rail-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: flex-start;
}

.dashboard-home__rail-head h4 {
  font-size: 16px;
  line-height: 1.15;
  letter-spacing: -0.03em;
}

.dashboard-home__rail-card p {
  margin: 0;
  color: var(--muted);
  line-height: 1.5;
  font-size: 14px;
}

.dashboard-home__list,
.dashboard-home__activity {
  display: grid;
  gap: 8px;
}

.dashboard-home__item {
  display: grid;
  gap: 3px;
  padding: 11px 12px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.68);
  border: 1px solid rgba(15, 23, 42, 0.06);
}

.dashboard-home__item-link {
