.dashboard-home__item-link:hover {
  transform: translateY(-1px);
  border-color: rgba(3, 168, 192, 0.18);
  background: rgba(255, 255, 255, 0.9);
  box-shadow: var(--shadow-soft);
}

.dashboard-home__item strong {
  font-size: 14px;
  letter-spacing: -0.02em;
}

.dashboard-home__item span {
  color: var(--muted);
  line-height: 1.5;
  font-size: 13px;
}

.dashboard-home__item--empty {
  min-height: 92px;
  place-items: center;
  text-align: center;
}

.dashboard-home__mini-metric {
  display: grid;
  gap: 2px;
  padding: 10px 12px;
  border-radius: 16px;
  background: rgba(3, 168, 192, 0.08);
  border: 1px solid rgba(3, 168, 192, 0.12);
}

.dashboard-home__mini-metric strong {
  font-size: 18px;
  line-height: 1.1;
  letter-spacing: -0.04em;
