  margin: 24px auto 0;
  max-width: 72ch;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.55;
  text-align: center;
}

.insight-pattern-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.insight-pattern-grid--triple {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.insight-pattern-card {
  padding: 14px 15px;
  border-radius: 18px;
  border: 1px solid rgba(15, 23, 42, 0.06);
  background: rgba(255, 255, 255, 0.58);
  display: grid;
  gap: 10px;
}

.insight-action-list {
  display: grid;
  gap: 10px;
}

.insight-action {
  padding: 14px 15px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.58);
  border: 1px solid rgba(15, 23, 42, 0.06);
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.insight-action strong {
  display: block;
  font-size: 14px;
  letter-spacing: -0.02em;
  margin-bottom: 4px;
}

.insight-action span {
  color: var(--muted);
  line-height: 1.45;
  font-size: 13px;
}

.insights-footer {
  margin-top: 12px;
  padding: 18px;
  border: 1px solid var(--stroke);
  background: rgba(255, 255, 255, 0.88);
  box-shadow: var(--shadow);
  display: grid;
  gap: 12px;
}

.insights-footer__list {
  display: grid;
  gap: 10px;
}

.insights-footer__item {
  padding: 13px 14px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.58);
  border: 1px solid rgba(15, 23, 42, 0.06);
  display: grid;
  gap: 4px;
}

.insights-footer__item strong {
  font-size: 14px;
  letter-spacing: -0.02em;
}

.insights-footer__item span {
  color: var(--muted);
  line-height: 1.5;
  font-size: 13px;
}

.adviser-page {
  display: flex;
  flex-direction: column;
  gap: 24px;
  padding-bottom: 32px;
}

.adviser-summary,
.adviser-hero,
.adviser-footnote {
  padding: 24px;
}

.adviser-summary {
  position: sticky;
  top: 0;
  z-index: 30;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 8px 0 12px;
  border: 0;
  border-bottom: 1px solid rgba(216, 226, 232, 0.88);
  background: #ffffff;
  box-shadow: none;
  isolation: isolate;
}

html[data-theme="dark"] .adviser-summary {
  border-bottom-color: rgba(148, 163, 184, 0.16);
  background: #0e1725;
}

.adviser-summary__grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.adviser-summary .adviser-summary-card {
  background: #ffffff;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  text-align: center;
}

html[data-theme="dark"] .adviser-summary .adviser-summary-card {
  background: #0e1725;
}

.adviser-summary-card__info {
  top: 10px;
  right: 10px;
}

.adviser-summary-card .eyebrow {
  margin: 0;
}

.adviser-summary-card p:last-child {
  margin: 0;
  color: var(--muted);
  line-height: 1.45;
  font-size: 0.88rem;
}

.adviser-hero {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.adviser-hero__copy {
  max-width: 72ch;
}

.adviser-hero__copy h1 {
  margin: 6px 0 10px;
  font-size: clamp(2rem, 4vw, 3.6rem);
  line-height: 0.98;
  letter-spacing: -0.04em;
}

.adviser-hero__copy p {
  margin: 0;
  color: var(--muted);
  font-size: 1rem;
  line-height: 1.65;
}

.adviser-hero__stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.adviser-stat {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 16px;
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.55);
  border: 1px solid rgba(11, 27, 43, 0.08);
}

html[data-theme="dark"] .adviser-stat {
  background: rgba(12, 18, 29, 0.72);
  border-color: rgba(148, 163, 184, 0.18);
}

.adviser-stat span {
  color: var(--muted);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: capitalize;
}

.adviser-stat strong {
  font-size: 1.35rem;
  line-height: 1.1;
}

.adviser-hero__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.adviser-section {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 22px;
  border: 1px solid rgba(148, 163, 184, 0.14);
  border-radius: 28px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.78), rgba(255, 255, 255, 0.58));
  box-shadow: 0 20px 44px rgba(15, 23, 42, 0.05);
}

html[data-theme="dark"] .adviser-section {
  border-color: rgba(148, 163, 184, 0.16);
  background: linear-gradient(180deg, rgba(12, 18, 29, 0.8), rgba(12, 18, 29, 0.62));
  box-shadow: 0 20px 44px rgba(2, 6, 23, 0.24);
}

.adviser-section--chat {
  padding-bottom: 20px;
}

.adviser-section__head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 18px;
}

.adviser-section__head h2 {
  margin: 6px 0 0;
  font-size: clamp(1.25rem, 2vw, 1.7rem);
  letter-spacing: -0.03em;
}

.adviser-section__lead {
  max-width: 44ch;
  margin: 0;
  color: var(--muted);
  font-size: 0.96rem;
  line-height: 1.55;
}

.adviser-section-empty {
  display: grid;
  gap: 6px;
  max-width: 520px;
  padding: 8px 0 4px;
  color: var(--muted);
}

.adviser-section-empty strong {
  color: var(--ink);
  font-size: 1rem;
  letter-spacing: -0.01em;
}

.adviser-section-empty p {
  margin: 0;
  line-height: 1.55;
}

.adviser-card-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
}

.adviser-card-grid--desktop {
  display: grid;
}

.adviser-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 100%;
  padding: 20px;
  border-radius: 24px;
  text-decoration: none;
  color: inherit;
}

.adviser-card__title-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.adviser-card:hover,
.adviser-card:focus-visible {
  transform: translateY(-1px);
}

.adviser-card strong {
  font-size: 1.06rem;
  letter-spacing: -0.02em;
}

.adviser-card p {
  margin: 0;
  color: var(--foreground);
  font-size: 0.96rem;
  line-height: 1.55;
}

.adviser-card small {
  color: var(--muted);
  font-size: 0.86rem;
  line-height: 1.45;
}

.adviser-card__cta {
  align-self: flex-start;
  margin-top: auto;
  width: min(100%, 180px);
  justify-content: center;
}

.adviser-card__button {
  align-self: flex-start;
  margin-top: auto;
}

.adviser-card__emoji {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.6rem;
  height: 1.6rem;
  font-size: 1.15rem;
  line-height: 1;
  transform: translateY(1px);
  flex: 0 0 auto;
}

.adviser-carousel {
  display: none;
  width: 100%;
  max-width: 100%;
}

.adviser-carousel__viewport {
  position: relative;
  width: 100%;
  max-width: 100%;
}

.adviser-carousel__rail {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  overscroll-behavior-x: contain;
  scrollbar-width: none;
}

.adviser-carousel__rail::-webkit-scrollbar {
  display: none;
}

.adviser-carousel__slide {
  flex: 0 0 100%;
  padding: 0 18px;
  scroll-snap-align: center;
}

.adviser-carousel__card {
  width: 100%;
  min-height: 100%;
}

.adviser-carousel__button {
  width: 40px;
  height: 40px;
  padding: 0;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.5);
  background: rgba(255, 255, 255, 0.78);
  color: var(--text);
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.12);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.adviser-carousel__button span {
  font-size: 26px;
  line-height: 1;
  margin-top: -2px;
}

.adviser-carousel__button--prev {
}

.adviser-carousel__button--next {
}

.adviser-carousel__button--footer {
  justify-self: center;
  flex: 0 0 40px;
}

.adviser-carousel__button:disabled {
  opacity: 0.35;
  cursor: default;
}

.adviser-carousel__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 18px 0;
  width: 100%;
  max-width: 100%;
  box-sizing: border-box;
}

.adviser-carousel__status {
  flex: 1;
  min-width: 0;
  display: grid;
  gap: 6px;
  justify-items: center;
}

.adviser-carousel__dots {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.adviser-carousel__dot {
  width: 7px;
  height: 7px;
  border: 0;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.16);
  padding: 0;
  cursor: pointer;
}

.adviser-carousel__dot.is-active {
  width: 18px;
  background: var(--accent);
}

.adviser-chat {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.adviser-chat__ask-label {
  margin: 2px 0 0;
}

.adviser-chat__heading-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.adviser-chat__reset {
  border: 0;
  padding: 0;
  background: transparent;
  color: var(--muted);
  font: inherit;
  font-size: 0.82rem;
  cursor: pointer;
}

.adviser-chat__reset:hover,
.adviser-chat__reset:focus-visible {
  color: var(--accent);
  text-decoration: underline;
}

.adviser-chat__question-lead {
  margin: 0;
  color: var(--muted);
  font-size: 0.92rem;
  line-height: 1.5;
}

.adviser-chat--locked {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.adviser-chat__locked-preview {
  min-width: 0;
  flex: 1 1 auto;
  opacity: 0.48;
  filter: grayscale(0.35);
  pointer-events: none;
  user-select: none;
}

.adviser-chat__locked-preview .adviser-chat__composer-bar {
  margin-bottom: 10px;
}

.adviser-chat__locked-preview .adviser-chat__prompt-row {
  overflow: hidden;
  flex-wrap: nowrap;
}

.adviser-chat__locked-preview .adviser-chat__prompt {
  flex: 0 0 auto;
}

.adviser-chat__locked-copy {
  max-width: 68ch;
}

.adviser-chat__locked-copy h3 {
  margin: 6px 0 8px;
  font-size: 1.3rem;
}

.adviser-chat__locked-copy p {
  margin: 0;
  color: var(--muted);
  line-height: 1.55;
}

.adviser-chat__locked-copy .button {
  margin-top: 14px;
}

.adviser-chat__prompt-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.adviser-chat__prompt {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 1px solid rgba(11, 27, 43, 0.08);
  background: rgba(255, 255, 255, 0.72);
  color: inherit;
  border-radius: 999px;
  padding: 10px 14px;
  font-weight: 400;
  letter-spacing: 0;
  cursor: pointer;
}

.adviser-chat__prompt-emoji {
  font-size: 1rem;
  line-height: 1;
}

html[data-theme="dark"] .adviser-chat__prompt {
  background: rgba(12, 18, 29, 0.78);
  border-color: rgba(148, 163, 184, 0.16);
}

.adviser-chat__thread {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 260px;
  max-height: 440px;
  overflow: auto;
  padding-right: 4px;
}

.adviser-chat__empty {
  padding: 18px;
  border-radius: 20px;
  border: 1px dashed rgba(11, 27, 43, 0.12);
  color: var(--muted);
}

.adviser-chat__empty strong {
  display: block;
  margin-bottom: 6px;
  color: var(--foreground);
}

.adviser-chat__empty p {
  margin: 0;
  line-height: 1.55;
}

.adviser-chat__message {
  max-width: min(720px, 88%);
  padding: 14px 16px;
  border-radius: 20px;
}

.adviser-chat__message span {
  display: block;
  margin-bottom: 8px;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: capitalize;
  color: var(--muted);
}

.adviser-chat__message p {
  margin: 0;
  line-height: 1.6;
}

.adviser-chat__feedback {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 12px;
  color: var(--muted);
  font-size: 0.78rem;
}

.adviser-chat__feedback button {
  border: 1px solid rgba(11, 27, 43, 0.1);
  border-radius: 999px;
  padding: 5px 9px;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.adviser-chat__feedback button:hover,
.adviser-chat__feedback button:focus-visible,
.adviser-chat__feedback button.is-selected {
  border-color: rgba(3, 168, 192, 0.38);
  background: rgba(3, 168, 192, 0.1);
  color: var(--foreground);
}

.adviser-chat__message--user {
  align-self: flex-end;
  background: rgba(3, 168, 192, 0.12);
  border: 1px solid rgba(3, 168, 192, 0.2);
}

.adviser-chat__message--assistant {
  align-self: flex-start;
  background: rgba(255, 255, 255, 0.65);
  border: 1px solid rgba(11, 27, 43, 0.08);
}

html[data-theme="dark"] .adviser-chat__message--assistant {
  background: rgba(12, 18, 29, 0.8);
  border-color: rgba(148, 163, 184, 0.16);
}

.adviser-chat__composer {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.adviser-chat__composer-bar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px 12px;
  align-items: center;
}

.adviser-chat__composer-bar input {
  width: 100%;
  min-width: 0;
  min-height: 46px;
  border-radius: 16px;
  border: 1px solid rgba(11, 27, 43, 0.12);
  background: rgba(255, 255, 255, 0.72);
  padding: 0 16px;
  font: inherit;
  color: inherit;
}

html[data-theme="dark"] .adviser-chat__composer-bar input {
  background: rgba(12, 18, 29, 0.78);
  border-color: rgba(148, 163, 184, 0.16);
}

.adviser-chat__status {
  grid-column: 1 / 2;
  color: var(--muted);
  font-size: 0.84rem;
}

.adviser-chat__composer-bar .button {
  grid-column: 2 / 3;
  grid-row: 1 / span 2;
  align-self: start;
}

.adviser-footnote {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
}

.adviser-footnote p {
  margin: 0;
  max-width: 62ch;
  color: var(--muted);
  line-height: 1.6;
}

.adviser-footnote__metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  min-width: min(100%, 520px);
}

.adviser-footnote__metrics div {
  padding: 14px 16px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.55);
  border: 1px solid rgba(11, 27, 43, 0.08);
}

html[data-theme="dark"] .adviser-footnote__metrics div {
  background: rgba(12, 18, 29, 0.72);
  border-color: rgba(148, 163, 184, 0.16);
}

.adviser-footnote__metrics span {
  display: block;
  margin-bottom: 6px;
  color: var(--muted);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: capitalize;
}

.adviser-footnote__metrics strong {
  font-size: 1rem;
}

@media (max-width: 1100px) {
  .adviser-summary__grid,
  .adviser-card-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 1100px) {
  .reports-top-tabs .animated-tabs__badge {
    display: none;
  }

  .adviser-summary,
  .adviser-hero,
  .adviser-footnote {
    padding: 18px;
  }

  .adviser-summary__grid,
  .adviser-hero__stats,
  .adviser-footnote__metrics {
    grid-template-columns: minmax(0, 1fr);
  }

  .adviser-summary__grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 6px;
  }

  .adviser-summary-card {
    padding: 8px 10px;
    min-height: 86px;
  }

  .adviser-summary-card .eyebrow {
    font-size: 0.56rem;
  }

  .adviser-summary-card__info {
    top: 6px;
    right: 6px;
  }

  .adviser-summary-card__info-tooltip {
    width: min(190px, calc(100vw - 24px));
  }

  .accounts-overview-card__amount {
    font-size: 1.02rem;
  }

  .adviser-card-grid--desktop {
    display: none;
  }

  .adviser-carousel {
    display: flex;
    flex-direction: column;
    gap: 8px;
  }

  .adviser-carousel__slide {
    padding: 0;
  }

  .adviser-carousel__card {
    min-height: auto;
    padding: 10px 0 2px;
    background: transparent;
    border: 0;
    box-shadow: none;
    border-radius: 0;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    text-align: left;
  }

  .adviser-carousel__footer {
    gap: 8px;
  }

  .adviser-carousel__button--footer {
    width: 40px;
    height: 40px;
  }

  .adviser-section__head {
    flex-direction: column;
    align-items: flex-start;
  }

  .adviser-carousel__card .adviser-card__title-row {
    justify-content: flex-start;
  }

  .adviser-carousel__card .adviser-card__cta {
    align-self: center;
    width: min(100%, 220px);
    margin-top: 12px;
  }

  .adviser-chat--locked {
    align-items: flex-start;
    flex-direction: column;
  }

  .adviser-chat__locked-preview,
  .adviser-chat__locked-copy {
    width: 100%;
  }

  .adviser-chat__composer-bar {
    grid-template-columns: minmax(0, 1fr);
  }

  .adviser-chat__composer-bar .button,
  .adviser-chat__status {
    grid-column: 1 / -1;
  }

  .adviser-chat__composer-bar .button {
    width: 100%;
    justify-content: center;
    grid-row: auto;
  }

  .adviser-chat__message {
    max-width: 100%;
  }
}

.goals-story {
  display: grid;
  gap: 12px;
}

.goals-story--beginner .goals-hero__copy h3 {
  max-width: 18ch;
  font-size: clamp(1.55rem, 3vw, 2.6rem);
}

.goals-story--beginner .goals-hero__copy p,
.goals-story--beginner .goals-progress p,
.goals-story--beginner .goals-hero__setup-note {
  font-size: 12px;
}

.goals-section {
  display: grid;
  gap: 14px;
}

.goals-overview__cards {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.goals-overview__card {
  padding: 14px 15px;
  border-radius: 20px;
  border: 1px solid rgba(15, 23, 42, 0.06);
  background: rgba(255, 255, 255, 0.76);
  display: grid;
  gap: 6px;
}

.goals-overview__card span {
  color: var(--muted);
  font-size: 12px;
  text-transform: capitalize;
  letter-spacing: 0.12em;
}

.goals-overview__card strong {
  font-size: 18px;
  line-height: 1.15;
  letter-spacing: -0.03em;
}

.goals-overview__card small {
  color: var(--muted);
  line-height: 1.45;
  font-size: 13px;
}

.goals-overview__card:last-child strong {
  font-size: 15px;
  line-height: 1.35;
}

.goals-page {
  display: grid;
  gap: 14px;
}

.goals-overview__card--current {
  position: relative;
}

.goals-blank-state {
  display: grid;
  justify-items: center;
  gap: 10px;
  padding: 46px 24px;
  text-align: center;
  min-height: min(620px, calc(100vh - 170px));
  align-content: center;
  border: 1px solid var(--stroke);
  border-radius: 30px;
  box-shadow: var(--shadow);
  background: radial-gradient(circle at 50% 0%, rgba(3, 168, 192, 0.14), transparent 42%), var(--surface);
}

.goal-inline-setup {
  width: min(760px, 100%);
  display: grid;
  gap: 16px;
