.goals-action {
  padding: 12px 13px;
  border-radius: 18px;
  border: 1px solid rgba(15, 23, 42, 0.06);
  background: rgba(255, 255, 255, 0.68);
  display: grid;
  gap: 10px;
  align-content: start;
  transition: transform 180ms ease, border-color 180ms ease, box-shadow 180ms ease;
}

.goals-action:hover {
  transform: translateY(-1px);
  border-color: rgba(3, 168, 192, 0.16);
  box-shadow: var(--shadow-soft);
}

.goals-editor {
  padding: 18px;
  border-radius: 28px;
  border: 1px solid var(--stroke);
  background: rgba(255, 255, 255, 0.9);
  box-shadow: var(--shadow);
  display: grid;
  gap: 14px;
}

.goals-editor-shell {
  margin-top: 2px;
}

.goals-editor__summary {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
}

.goals-editor__summary-copy {
  display: grid;
  gap: 4px;
}

.goals-editor__summary-copy h4 {
  font-size: 22px;
  line-height: 1.15;
}

.goals-editor__summary-copy p {
  color: var(--muted);
  line-height: 1.45;
  font-size: 13px;
}

.goals-editor__summary-actions {
  text-align: right;
  display: grid;
  gap: 2px;
}

.goals-editor__chip {
  justify-self: end;
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 0 10px;
  border-radius: 999px;
  border: 1px solid rgba(15, 23, 42, 0.08);
  background: rgba(255, 255, 255, 0.72);
  color: var(--muted);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: capitalize;
}

.goals-editor__chip.is-saved {
  border-color: rgba(3, 168, 192, 0.16);
  color: var(--accent);
}

.goals-editor__launch {
  justify-self: end;
}

.goals-editor__modal {
  display: grid;
  gap: 14px;
  max-height: calc(100dvh - 40px);
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
}

.goals-editor__modal-copy {
  color: var(--muted);
  font-size: 13px;
  line-height: 1.45;
  margin-top: 4px;
}

.goals-editor__insights {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.goals-editor__insight {
  display: grid;
  gap: 4px;
  padding: 12px 14px;
  border-radius: 18px;
  border: 1px solid rgba(3, 168, 192, 0.14);
  background: rgba(3, 168, 192, 0.06);
}

.goals-editor__insight span {
  color: var(--muted);
  font-size: 11px;
  text-transform: capitalize;
  letter-spacing: 0.12em;
}

.goals-editor__insight strong {
  color: var(--text);
  font-size: 13px;
  line-height: 1.45;
}

.goals-editor__grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.goals-editor__card {
  padding: 12px 13px;
  border-radius: 20px;
  border: 1px solid rgba(15, 23, 42, 0.06);
  background: rgba(255, 255, 255, 0.72);
  display: grid;
  gap: 6px;
  text-align: left;
  color: var(--text);
  transition: transform 180ms ease, border-color 180ms ease, box-shadow 180ms ease, background 180ms ease;
}

.goals-editor__card:hover {
  transform: translateY(-1px);
  border-color: rgba(3, 168, 192, 0.16);
  box-shadow: var(--shadow-soft);
}

.goals-editor__card.is-selected {
  border-color: rgba(3, 168, 192, 0.26);
  background:
    radial-gradient(circle at top left, rgba(34, 197, 94, 0.12), transparent 36%),
    rgba(255, 255, 255, 0.92);
  box-shadow: 0 18px 34px rgba(3, 168, 192, 0.08);
}

.goals-editor__card strong {
  font-size: 18px;
  letter-spacing: -0.03em;
}

.goals-editor__card span {
  color: var(--muted);
  line-height: 1.45;
  font-size: 13px;
}

.goals-editor__card-pill {
  justify-self: start;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  border-radius: 999px;
  background: rgba(3, 168, 192, 0.1);
  color: var(--accent);
  font-size: 11px;
  text-transform: capitalize;
  letter-spacing: 0.12em;
}

.goals-editor__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: flex-end;
}

.goals-editor__amount {
  display: grid;
  gap: 8px;
  padding: 16px 17px;
  border-radius: 22px;
  border: 1px solid rgba(15, 23, 42, 0.06);
  background:
    radial-gradient(circle at top left, rgba(3, 168, 192, 0.08), transparent 36%),
    rgba(255, 255, 255, 0.76);
}

.goals-editor__amount span {
  font-size: 12px;
  text-transform: capitalize;
  letter-spacing: 0.12em;
  color: var(--muted);
}

.goals-editor__amount input {
  width: 100%;
  min-height: 52px;
  border-radius: 16px;
  border: 1px solid rgba(15, 23, 42, 0.12);
  background: white;
  padding: 0 16px;
  font-size: 16px;
  color: var(--text);
  outline: none;
}

.goals-editor__amount input:focus {
  border-color: rgba(3, 168, 192, 0.32);
  box-shadow: 0 0 0 4px rgba(3, 168, 192, 0.1);
}

.goals-editor__amount small {
  color: var(--muted);
  line-height: 1.5;
  font-size: 13px;
}

.goals-editor__mode-grid,
.goals-editor__purpose-chips {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.goals-editor__mode,
.goals-editor__purpose,
.goals-editor__intent {
  display: grid;
  gap: 8px;
}

.goals-editor__mode span,
.goals-editor__purpose span,
.goals-editor__intent span {
  color: var(--muted);
  font-size: 12px;
  text-transform: capitalize;
  letter-spacing: 0.12em;
}

.goals-editor__mode select,
.goals-editor__purpose input,
.goals-editor__intent input {
  width: 100%;
  min-height: 52px;
  border-radius: 16px;
  border: 1px solid rgba(15, 23, 42, 0.12);
  background: white;
  padding: 0 16px;
  font-size: 16px;
  color: var(--text);
  outline: none;
}

.goals-editor__mode select:focus,
.goals-editor__purpose input:focus,
.goals-editor__intent input:focus {
  border-color: rgba(3, 168, 192, 0.32);
  box-shadow: 0 0 0 4px rgba(3, 168, 192, 0.1);
}

.goals-editor__purpose small,
.goals-editor__intent small {
  color: var(--muted);
  line-height: 1.45;
  font-size: 13px;
}

.goals-editor__purpose-chips {
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
}

.goals-editor__purpose-chip {
  min-height: 40px;
  padding: 0 14px;
  border-radius: 999px;
  border: 1px solid rgba(15, 23, 42, 0.08);
  background: rgba(255, 255, 255, 0.72);
  color: var(--text);
  text-align: left;
  font-size: 13px;
  transition: transform 180ms ease, border-color 180ms ease, box-shadow 180ms ease, background 180ms ease;
}

.goals-editor__purpose-chip:hover {
  transform: translateY(-1px);
  border-color: rgba(3, 168, 192, 0.16);
  box-shadow: var(--shadow-soft);
}

.goals-editor__purpose-chip.is-selected {
  border-color: rgba(3, 168, 192, 0.24);
  background: rgba(3, 168, 192, 0.08);
  color: var(--accent);
}

.goals-editor__helper {
  color: var(--muted);
  font-size: 13px;
}

.goals-editor__advanced-toggle {
  display: grid;
  gap: 8px;
  align-items: start;
}

.goals-editor__advanced-toggle small {
  color: var(--muted);
  font-size: 13px;
  line-height: 1.45;
}

@media (max-width: 1100px) {
  .goals-editor__summary {
    grid-template-columns: 1fr;
  }

  .goals-editor__summary-actions {
    justify-content: flex-start;
    text-align: left;
  }

  .goals-editor__chip,
  .goals-editor__launch {
    justify-self: start;
  }

  .goals-editor__insights {
    grid-template-columns: 1fr;
  }
}

/* Investments information hierarchy: growth hero, four metrics, and labeled pie charts. */
.content--investments .investments-growth-hero {
  display: grid;
  gap: 12px;
  min-height: 300px;
  padding: 18px 20px;
  border: 1px solid var(--stroke);
  border-radius: 22px;
  background:
    radial-gradient(circle at 82% 12%, rgba(80, 220, 202, 0.16), transparent 34%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.96), rgba(242, 251, 251, 0.88));
  box-shadow: var(--shadow-soft);
}

.content--investments .investments-growth-hero .investments-growth-chart svg {
  height: min(31vh, 250px);
}

.investments-growth-hero__change {
  display: grid;
  justify-items: end;
  gap: 2px;
  color: var(--muted);
  font-size: 11px;
}

.investments-growth-hero__change strong {
  color: var(--text);
  font-size: 16px;
}

.content--investments .investments-overview-metrics {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.content--investments .investments-overview-metrics__card {
  min-height: 96px;
  padding: 12px 14px;
}

.content--investments .investments-overview-metrics__card .accounts-overview-card__amount {
  font-size: clamp(1rem, 1.55vw, 1.3rem);
}

.investments-risk-level--low {
  color: var(--good);
}

.investments-risk-level--medium {
  color: #d97706;
}

.investments-risk-level--high {
  color: var(--bad);
}

.content--investments .report-donut,
.content--investments .investments-overview-mix-panel .report-donut,
.content--investments .investments-insights-grid .investments-analysis-donut {
  grid-template-columns: minmax(0, 1fr);
  gap: 5px;
  justify-items: center;
}

.content--investments .report-donut__chart,
.content--investments .investments-overview-mix-panel .report-donut__chart,
.content--investments .investments-insights-grid .investments-analysis-donut .report-donut__chart {
  width: min(100%, 430px);
  min-height: 260px;
  align-self: start;
}

.content--investments .report-donut__chart svg {
  transform: none;
  overflow: visible;
}

.content--investments .report-donut__segment {
  stroke: rgba(255, 255, 255, 0.94);
  stroke-width: 1.5px;
  transform-box: fill-box;
  transform-origin: center;
  transition: opacity 150ms ease, filter 150ms ease, transform 150ms ease;
}

.content--investments .report-donut__segment.is-clickable,
.content--investments .report-donut__callout {
  cursor: pointer;
  pointer-events: auto;
}

.content--investments .report-donut__segment.is-active {
  stroke-width: 1.5px;
  filter: saturate(1.12) drop-shadow(0 5px 8px rgba(15, 23, 42, 0.16));
  transform: scale(1.025);
}

.content--investments .report-donut__segment.is-muted,
.content--investments .report-donut__callout.is-muted {
  opacity: 0.28;
}

.content--investments .report-donut__callout {
  transition: opacity 150ms ease;
}

.content--investments .report-donut__callout path {
  stroke-width: 1;
}

.content--investments .report-donut__callout text {
  fill: var(--text);
  font-family: inherit;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.content--investments .report-donut__callout .report-donut__callout-percent {
  fill: var(--muted);
  font-size: 8px;
  font-weight: 600;
}

.content--investments .report-donut__total {
  display: grid;
  justify-items: center;
  gap: 1px;
  max-width: 100%;
  text-align: center;
}

.content--investments .report-donut__total span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: capitalize;
}

.content--investments .report-donut__total strong {
  max-width: 100%;
  color: var(--text);
  font-size: 15px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.content--investments .report-donut__center,
.content--investments .report-donut__legend,
.content--investments .report-donut__track,
.content--investments .report-donut__chart::after {
  display: none;
}

.content--investments .report-donut__tooltip {
  top: 8px;
}

.investments-market-insights {
  display: grid;
  gap: 12px;
  padding: 15px;
  border: 1px solid rgba(3, 168, 192, 0.16);
  border-radius: 20px;
  background:
    radial-gradient(circle at 92% 0%, rgba(80, 220, 202, 0.13), transparent 38%),
    rgba(248, 252, 252, 0.9);
}

.investments-market-insights__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
}

.investments-market-insights__head p,
.investments-market-insights__head h3 {
  margin: 0;
}

.investments-market-insights__head h3 {
  margin-top: 3px;
  font-size: 16px;
}

.investments-market-insights__links {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.investments-market-insights__links a,
.investments-market-insights__links button {
  min-height: 30px;
  padding: 0 10px;
  border: 1px solid rgba(3, 168, 192, 0.22);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.78);
  color: var(--accent);
  font: inherit;
  font-size: 10px;
  font-weight: 700;
  text-decoration: none;
  cursor: pointer;
}

.investments-market-insights__grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.investments-market-insights__grid article {
  display: grid;
  align-content: start;
  gap: 5px;
  min-width: 0;
  padding: 11px 12px;
  border: 1px solid rgba(148, 163, 184, 0.16);
  border-radius: 15px;
  background: rgba(255, 255, 255, 0.74);
}

.investments-market-insights__grid span,
.investments-market-insights__grid small {
  color: var(--muted);
  font-size: 10px;
}

.investments-market-insights__grid strong {
  overflow: hidden;
  color: var(--text);
  font-size: 12px;
  line-height: 1.25;
  text-overflow: ellipsis;
}

@media (max-width: 1100px) {
  .content--investments .investments-overview-metrics,
  .investments-market-insights__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 1100px) {
  .content--investments .investments-growth-hero {
    min-height: 250px;
    padding: 14px;
  }

  .content--investments .investments-growth-hero .investments-growth-chart svg {
    height: 190px;
  }

  .content--investments .investments-overview-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
  }

  .content--investments .investments-overview-metrics__card {
    min-height: 88px;
    padding: 10px;
  }

  .content--investments .report-donut__chart,
  .content--investments .investments-overview-mix-panel .report-donut__chart,
  .content--investments .investments-insights-grid .investments-analysis-donut .report-donut__chart {
    width: min(100%, 370px);
    min-height: 230px;
  }

  .investments-market-insights__head {
    align-items: stretch;
    flex-direction: column;
  }

  .investments-market-insights__links {
    justify-content: flex-start;
  }
}

.goals-plan-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.1fr);
  gap: 12px;
}

.goals-plan,
.goals-investments {
  padding: 18px;
  border-radius: 28px;
  border: 1px solid var(--stroke);
  background: rgba(255, 255, 255, 0.92);
  box-shadow: var(--shadow);
  display: grid;
  gap: 14px;
  align-content: start;
}

.goals-plan__body {
  display: flex;
  gap: 14px;
  align-items: flex-start;
}

.goals-plan__body svg {
  width: 42px;
  height: 42px;
  flex: none;
}

.goals-plan__body p {
  margin: 0 0 6px;
  color: var(--text);
  line-height: 1.5;
}

.goals-plan__body small {
  color: var(--muted);
  line-height: 1.45;
}

.goals-investments__metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.goals-investments__metrics > div,
.goals-investments__item,
.goals-investments__empty {
  padding: 12px 13px;
  border-radius: 18px;
  border: 1px solid rgba(15, 23, 42, 0.06);
  background: rgba(255, 255, 255, 0.72);
  display: grid;
  gap: 4px;
}

.goals-investments__metrics span,
.goals-investments__item span {
  color: var(--muted);
  font-size: 12px;
  text-transform: capitalize;
  letter-spacing: 0.12em;
}

.goals-investments__metrics strong,
.goals-investments__item strong {
  font-size: 18px;
  line-height: 1.15;
  letter-spacing: -0.03em;
}

.goals-investments__metrics small,
.goals-investments__item small {
  color: var(--muted);
  line-height: 1.45;
  font-size: 13px;
}

.goals-investments__list {
  display: grid;
  gap: 10px;
}

.goals-investments__item {
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
}

.goals-investments__item strong {
  text-align: right;
}

.goals-investments__empty {
  display: grid;
  gap: 12px;
}

.goals-investments__empty p {
  color: var(--muted);
  line-height: 1.5;
}

@keyframes goals-float {
  0%,
  100% {
    transform: translateY(0px) scale(1);
  }
  50% {
    transform: translateY(-8px) scale(1.04);
  }
}

.goals-action strong {
  display: block;
  font-size: 15px;
  letter-spacing: -0.02em;
  margin-bottom: 4px;
}

.goals-action span {
  color: var(--muted);
  line-height: 1.45;
  font-size: 13px;
}

.goals-intel-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.goals-history,
.goals-milestones,
.goals-weekly,
.goals-checklist,
.goals-alerts {
  padding: 18px;
  border-radius: 28px;
  border: 1px solid var(--stroke);
  background: rgba(255, 255, 255, 0.9);
  box-shadow: var(--shadow);
  display: grid;
  gap: 14px;
  align-content: start;
}

.goals-history__timeline,
.goals-milestones__list,
.goals-alerts__list {
  display: grid;
  gap: 10px;
}

.goals-history__item {
  padding: 14px 15px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.68);
  border: 1px solid rgba(15, 23, 42, 0.06);
  display: grid;
  gap: 4px;
}

.goals-history__label,
.goals-weekly__card span {
  color: var(--muted);
  font-size: 12px;
  text-transform: capitalize;
  letter-spacing: 0.12em;
}

.goals-history__item strong {
  font-size: 14px;
  line-height: 1.5;
  letter-spacing: -0.02em;
}

.goals-milestone {
  padding: 14px 15px;
  border-radius: 18px;
  border: 1px solid rgba(15, 23, 42, 0.06);
  background: rgba(255, 255, 255, 0.68);
  display: grid;
  gap: 10px;
}

.goals-milestone.is-reached {
  border-color: rgba(34, 197, 94, 0.18);
  background:
    radial-gradient(circle at top left, rgba(34, 197, 94, 0.12), transparent 34%),
    rgba(255, 255, 255, 0.84);
}

.goals-milestone__head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
}

.goals-milestone__head strong {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 15px;
  letter-spacing: -0.02em;
}

.goals-milestone__icon {
  width: 30px;
  height: 30px;
  border-radius: 12px;
  display: inline-grid;
  place-items: center;
  background: rgba(3, 168, 192, 0.12);
  color: var(--accent);
  flex: none;
}

.goals-milestone__head span {
  color: var(--muted);
  font-size: 13px;
}

.goals-milestone p,
.goals-alerts__item p {
  color: var(--muted);
  line-height: 1.5;
  font-size: 13px;
}

.goals-milestone__bar {
  width: 100%;
  height: 10px;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.08);
  overflow: hidden;
}

.goals-milestone__fill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, rgba(34, 197, 94, 0.9), rgba(3, 168, 192, 0.95));
}

.goals-weekly__grid,
.goals-checklist__grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.goals-weekly__card {
  padding: 14px 15px;
  border-radius: 18px;
  border: 1px solid rgba(15, 23, 42, 0.06);
  background: rgba(255, 255, 255, 0.68);
  display: grid;
  gap: 4px;
}

.goals-weekly__card.positive {
  border-color: rgba(34, 197, 94, 0.16);
}

.goals-weekly__card.negative {
  border-color: rgba(239, 68, 68, 0.16);
}

.goals-weekly__card.neutral {
  border-color: rgba(3, 168, 192, 0.14);
}

.goals-weekly__card strong {
  font-size: 22px;
  letter-spacing: -0.04em;
}

.goals-weekly__card small {
  color: var(--muted);
  line-height: 1.4;
}

.goals-checklist__item {
  padding: 14px 15px;
  border-radius: 18px;
  border: 1px solid rgba(15, 23, 42, 0.06);
  background: rgba(255, 255, 255, 0.68);
  display: grid;
  gap: 10px;
}

.goals-checklist__item.is-done {
  border-color: rgba(34, 197, 94, 0.18);
  background:
    radial-gradient(circle at top left, rgba(34, 197, 94, 0.12), transparent 34%),
    rgba(255, 255, 255, 0.84);
}

.goals-checklist__toggle {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  border: 0;
  background: transparent;
  padding: 0;
  color: inherit;
  text-align: left;
  width: 100%;
}

.goals-checklist__checkbox {
  width: 22px;
  height: 22px;
  border-radius: 8px;
  border: 1px solid rgba(3, 168, 192, 0.24);
  display: grid;
  place-items: center;
  flex: none;
  color: var(--accent);
  background: rgba(3, 168, 192, 0.08);
  font-size: 13px;
  font-weight: 700;
  margin-top: 2px;
}

.goals-checklist__checkbox svg {
  width: 12px;
  height: 12px;
}

.goals-checklist__copy {
  display: grid;
  gap: 4px;
}

.goals-checklist__copy strong {
  font-size: 15px;
  letter-spacing: -0.02em;
}

.goals-checklist__copy span {
  color: var(--muted);
  line-height: 1.5;
  font-size: 13px;
}

.goals-alerts__item {
  padding: 14px 15px;
  border-radius: 18px;
  border: 1px solid rgba(15, 23, 42, 0.06);
  background: rgba(255, 255, 255, 0.68);
  display: grid;
  grid-template-columns: 12px minmax(0, 1fr);
  gap: 10px;
  align-items: flex-start;
}

.goals-alerts__dot {
  width: 10px;
  height: 10px;
  border-radius: 999px;
  margin-top: 5px;
  background: linear-gradient(135deg, rgba(34, 197, 94, 0.95), rgba(3, 168, 192, 0.95));
  display: grid;
  place-items: center;
  color: white;
}

.goals-alerts__dot svg {
  width: 12px;
  height: 12px;
}

.actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  align-items: center;
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 42px;
  padding: 0 18px;
  border-radius: 999px;
  border: 1px solid transparent;
  cursor: pointer;
  background: transparent;
}

.button-primary {
  color: white;
  background: var(--brand-gradient);
  border-color: transparent;
}

.button-secondary {
  background: rgba(255, 255, 255, 0.92);
  border-color: rgba(3, 168, 192, 0.22);
  color: var(--accent);
}

.button-danger {
  background: rgba(239, 68, 68, 0.08);
  border-color: rgba(239, 68, 68, 0.24);
  color: #b91c1c;
}

.button-danger:hover:not(:disabled),
.button-danger:focus:not(:disabled) {
  background: rgba(239, 68, 68, 0.12);
  border-color: rgba(239, 68, 68, 0.3);
  color: #991b1b;
}

.button:disabled {
  cursor: not-allowed;
  background: #e7edf1;
  border-color: #d4dde3;
  color: #94a3af;
  box-shadow: none;
  transform: none;
  opacity: 1;
}

.button-small {
  min-height: var(--action-button-height);
  padding: 0 var(--action-button-padding-inline);
  border-radius: 999px;
  font-size: var(--action-button-font-size);
  font-weight: var(--action-button-font-weight);
}

/* Modal and form footer actions follow the same compact CTA rhythm as page headers. */
:is(.modal-actions, .form-actions) > .button {
  min-height: var(--action-button-height);
  padding-inline: var(--action-button-padding-inline);
  font-size: var(--action-button-font-size);
  font-weight: var(--action-button-font-weight);
}

.button-pill {
  border-radius: 999px;
}

.page {
  width: min(1160px, calc(100% - 32px));
  margin: 0 auto;
}

.onboarding-page {
  min-height: 100dvh;
  padding: 28px 20px;
  display: grid;
  place-items: center;
}

.onboarding-page__shell {
  width: min(680px, 100%);
  display: grid;
  gap: 22px;
}

.onboarding-card {
  display: grid;
  gap: 14px;
  padding: 24px 26px;
  border-radius: 30px;
}

.onboarding-icon-preload {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
}

.onboarding-card__brand {
  display: flex;
  justify-content: center;
  margin-bottom: 4px;
}

.onboarding-card__mark {
  width: 40px;
  height: 40px;
}

.onboarding-card h3 {
  font-size: 28px;
  line-height: 1.15;
  font-weight: 600;
  letter-spacing: -0.04em;
  max-width: none;
  width: 100%;
}

.onboarding-card__copy {
  max-width: none;
  width: 100%;
  color: var(--muted);
  font-size: 15px;
}

.onboarding-card__copy--subtle {
  margin-top: -4px;
  color: var(--muted-2);
  font-size: 13px;
}

.onboarding-card__message {
  margin-top: 2px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.5;
}

.onboarding-upload {
  width: 100%;
  display: grid;
  gap: 14px;
  padding: 16px;
  border-radius: 24px;
  border: 1px solid rgba(3, 168, 192, 0.14);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.82), rgba(247, 249, 250, 0.92)),
    linear-gradient(135deg, rgba(3, 168, 192, 0.08), rgba(255, 255, 255, 0));
  box-shadow: 0 18px 38px rgba(15, 23, 42, 0.06);
  cursor: pointer;
}

.onboarding-upload:focus-within {
  border-color: rgba(3, 168, 192, 0.3);
  box-shadow:
    0 18px 38px rgba(15, 23, 42, 0.06),
    0 0 0 4px rgba(3, 168, 192, 0.1);
}

.onboarding-upload__visual {
  min-height: 178px;
  border-radius: 22px;
  border: 1px dashed rgba(3, 168, 192, 0.28);
  background:
    radial-gradient(circle at top, rgba(3, 168, 192, 0.14), transparent 58%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(247, 249, 250, 0.82));
  display: grid;
  place-items: center;
  position: relative;
  overflow: hidden;
}

.onboarding-upload__visual::after {
  content: "";
  position: absolute;
  inset: auto -12% -22% -12%;
  height: 80px;
  border-radius: 999px;
  background: rgba(3, 168, 192, 0.08);
  filter: blur(12px);
  pointer-events: none;
}

.onboarding-upload__icon {
  width: 84px;
  height: 84px;
  border-radius: 28px;
  border: 1px solid rgba(3, 168, 192, 0.14);
  background: rgba(255, 255, 255, 0.96);
  color: var(--accent);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 16px 32px rgba(15, 23, 42, 0.08);
  position: relative;
  z-index: 1;
}

.onboarding-upload__icon svg {
  width: 34px;
  height: 34px;
  stroke: currentColor;
  stroke-width: 1.8;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.onboarding-upload__copy {
  display: grid;
  gap: 4px;
  text-align: center;
}

.onboarding-upload__copy strong {
  font-size: 16px;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text);
}

.onboarding-upload__copy span {
  color: var(--muted);
  font-size: 14px;
  line-height: 1.45;
}

.onboarding-upload__actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.onboarding-goal-target {
  display: grid;
  gap: 10px;
  width: 100%;
  padding: 16px 18px;
  border-radius: 22px;
  border: 1px solid rgba(3, 168, 192, 0.16);
  background: rgba(3, 168, 192, 0.06);
}

.onboarding-goal-target__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.onboarding-goal-target__label {
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
}

.onboarding-goal-target__pill {
  padding: 4px 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.8);
  border: 1px solid rgba(3, 168, 192, 0.16);
  color: var(--accent);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: capitalize;
}

.onboarding-goal-target__prompt {
  color: var(--muted);
  font-size: 14px;
  line-height: 1.45;
}

.onboarding-goal-target__input-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
}

.onboarding-goal-target__currency,
.onboarding-goal-target__suffix {
  color: var(--muted);
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
}

.onboarding-goal-target input {
  min-width: 0;
  width: 100%;
  min-height: 48px;
  border-radius: 16px;
  border: 1px solid rgba(15, 23, 42, 0.1);
  background: rgba(255, 255, 255, 0.96);
  padding: 12px 14px;
  font-size: 15px;
  color: var(--text);
}

.onboarding-goal-target input:focus {
  outline: none;
  border-color: rgba(3, 168, 192, 0.4);
  box-shadow: 0 0 0 4px rgba(3, 168, 192, 0.12);
}

.onboarding-goal-target small {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.4;
}

.onboarding-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.onboarding-grid--experience {
  grid-template-columns: 1fr;
}

.onboarding-grid--start {
  grid-template-columns: 1fr;
}

.onboarding-option {
  width: 100%;
  min-height: 76px;
  padding: 16px 18px;
  border-radius: 22px;
  border: 1px solid rgba(15, 23, 42, 0.08);
  background: rgba(247, 249, 250, 0.9);
  display: flex;
  align-items: center;
  gap: 14px;
  text-align: left;
  transition:
    background 180ms ease,
    border-color 180ms ease,
    transform 180ms ease,
    box-shadow 180ms ease;
}

.onboarding-option:hover {
  border-color: rgba(3, 168, 192, 0.28);
  transform: translateY(-1px);
  box-shadow: var(--shadow-soft);
}

.onboarding-option.is-selected {
  background: linear-gradient(135deg, rgba(3, 168, 192, 0.16), rgba(3, 168, 192, 0.08));
  border-color: rgba(3, 168, 192, 0.34);
}

.onboarding-option--start {
  min-height: 88px;
  align-items: flex-start;
  padding: 18px;
}

.onboarding-option--featured {
  min-height: 118px;
  border-color: rgba(3, 168, 192, 0.28);
  background: linear-gradient(135deg, rgba(3, 168, 192, 0.14), rgba(255, 255, 255, 0.96));
  box-shadow: 0 12px 30px rgba(3, 168, 192, 0.08);
}

.onboarding-option--featured .onboarding-option__icon {
  background: var(--accent);
  color: white;
  border-color: rgba(3, 168, 192, 0.28);
}

.onboarding-option__content {
  display: grid;
  gap: 4px;
  min-width: 0;
  padding-top: 1px;
}

.onboarding-option__title-row {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.onboarding-option__badge {
  display: inline-flex;
  align-items: center;
  min-height: 20px;
  padding: 0 8px;
  border-radius: 999px;
  background: rgba(3, 168, 192, 0.12);
  color: var(--accent-hover);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: capitalize;
}

.onboarding-option--start .onboarding-option__copy {
  color: var(--muted);
  font-size: 13px;
  line-height: 1.45;
}

.onboarding-option--experience .onboarding-option__copy {
  color: var(--muted);
  font-size: 13px;
  line-height: 1.35;
  font-weight: 600;
}

.onboarding-option__icon {
  width: 42px;
  height: 42px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid rgba(3, 168, 192, 0.14);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  flex: none;
  box-shadow: var(--shadow-soft);
  transform-origin: center;
}

.onboarding-option__icon svg {
  width: 20px;
  height: 20px;
  stroke: currentColor;
  stroke-width: 1.9;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.onboarding-option__icon img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
  filter: grayscale(0.45);
  opacity: 0.64;
  transition: filter 180ms ease, opacity 180ms ease, transform 180ms ease;
}

.onboarding-option--experience-beginner .onboarding-option__icon img {
  width: 100%;
  height: 100%;
}

.onboarding-option--experience-comfortable .onboarding-option__icon img,
.onboarding-option--experience-advanced .onboarding-option__icon img,
.onboarding-option--start-account .onboarding-option__icon img {
  width: 100%;
  height: 100%;
}

.onboarding-option--goal .onboarding-option__icon img {
  width: 70%;
  height: 70%;
}

.onboarding-option--start-account .onboarding-option__icon img {
  width: 54%;
  height: 54%;
}

.onboarding-option.is-selected .onboarding-option__icon {
  background: var(--accent);
  border-color: rgba(3, 168, 192, 0.28);
  color: white;
  animation: onboarding-icon-pop 260ms ease;
}

.onboarding-option.is-selected .onboarding-option__icon img {
  filter: none !important;
  opacity: 1;
  transform: scale(1.03);
}

.onboarding-option__title {
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--text);
}

.onboarding-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
}

.onboarding-actions__group {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.onboarding-actions__group--secondary {
  justify-content: flex-start;
}

.onboarding-actions__group--primary {
  justify-content: flex-end;
  margin-left: auto;
}

.onboarding-actions .button {
  min-width: 152px;
}

.onboarding-status {
  width: 100%;
  color: var(--muted);
  min-height: 24px;
}

@keyframes onboarding-icon-pop {
  0% {
    transform: scale(0.92);
  }
  55% {
    transform: scale(1.08);
  }
  100% {
    transform: scale(1);
  }
}

.landing-page {
  position: relative;
  width: min(1240px, calc(100% - 32px));
  margin: 0 auto;
  padding: 28px 0 40px;
}

.landing-page::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 12% 14%, rgba(3, 168, 192, 0.18), transparent 22%),
    radial-gradient(circle at 88% 12%, rgba(110, 231, 183, 0.12), transparent 24%),
    radial-gradient(circle at 50% 100%, rgba(9, 30, 42, 0.06), transparent 22%);
  opacity: 0.8;
  z-index: -1;
}

.reveal {
  opacity: 0;
  transform: translateY(24px) scale(0.985);
  filter: blur(10px);
  transition:
    opacity 700ms ease,
    transform 700ms cubic-bezier(0.22, 1, 0.36, 1),
    filter 700ms ease;
  transition-delay: var(--reveal-delay, 0ms);
  will-change: opacity, transform, filter;
}

.reveal.is-visible {
  opacity: 1;
  transform: translateY(0) scale(1);
  filter: blur(0);
}

.landing-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 6px 0 12px;
}

.landing-brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  letter-spacing: -0.03em;
  font-size: 16px;
}

.landing-brand__logo {
  width: min(138px, 100%);
  height: auto;
  border-radius: 0;
  box-shadow: none;
  background: transparent;
}

.landing-nav__links {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.landing-nav__link {
  color: var(--muted);
  font-weight: 500;
  transition: color 160ms ease;
}

.landing-nav__link:hover,
.landing-nav__link:focus-visible {
  color: var(--text);
}

.landing-nav__button {
  min-height: 40px;
  padding-inline: 14px;
}

.landing-hero {
  display: grid;
  grid-template-columns: minmax(0, 0.98fr) minmax(300px, 1.02fr);
  gap: 24px;
  align-items: center;
  padding: 22px 0 14px;
}

.landing-hero__copy {
  display: grid;
  gap: 18px;
  padding-right: 12px;
}

.landing-hero__copy h1 {
  max-width: 12ch;
  font-size: clamp(2.35rem, 5.4vw, 4.2rem);
  line-height: 0.96;
  letter-spacing: -0.08em;
}

.landing-hero__lede {
  max-width: 60ch;
  color: var(--muted);
  font-size: 18px;
  line-height: 1.7;
}

.landing-hero__actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  align-items: center;
}

.landing-hero__trust {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.landing-hero__trust > div {
  padding: 16px 16px 15px;
  border-radius: 22px;
  border: 1px solid rgba(15, 23, 42, 0.06);
  background: rgba(255, 255, 255, 0.7);
  box-shadow: var(--shadow-soft);
  display: grid;
  gap: 4px;
}

.landing-hero__trust strong,
.landing-stat strong,
.landing-mini-card strong {
  font-size: 15px;
  letter-spacing: -0.02em;
}

.landing-hero__trust span,
.landing-stat span,
.landing-mini-card span {
  color: var(--muted);
  font-size: 14px;
  line-height: 1.45;
}

.landing-scene {
  position: relative;
  min-height: 680px;
}

.landing-scene__frame,
.landing-scene__glow--left,
.landing-scene__glow--right {
  animation: landing-breathe 9s ease-in-out infinite;
}

.landing-scene__glow--right {
  animation-delay: 1.3s;
}

.landing-scene__frame {
  animation-delay: 0.4s;
}

.landing-scene__glow {
  position: absolute;
  inset: auto;
  border-radius: 50%;
  filter: blur(8px);
}

.landing-scene__glow--left {
  top: 82px;
  left: 2px;
  width: 220px;
  height: 220px;
  background: rgba(3, 168, 192, 0.16);
}

.landing-scene__glow--right {
  right: 12px;
  bottom: 48px;
  width: 190px;
  height: 190px;
  background: rgba(94, 211, 208, 0.12);
}

.landing-scene__frame {
  position: relative;
  height: 100%;
  border-radius: 40px;
  background:
    radial-gradient(circle at 22% 12%, rgba(255, 255, 255, 0.95), rgba(255, 255, 255, 0.62) 22%, transparent 58%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.86), rgba(246, 250, 251, 0.8));
  border: 1px solid rgba(15, 23, 42, 0.06);
  box-shadow:
    0 40px 90px rgba(15, 23, 42, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.85);
  overflow: hidden;
}

.landing-scene__frame::before {
  content: "";
  position: absolute;
  inset: 16px;
  border-radius: 30px;
  border: 1px solid rgba(3, 168, 192, 0.1);
  pointer-events: none;
}

.landing-scene__art {
  display: block;
  width: 100%;
  height: 100%;
  min-height: 680px;
}

.landing-benefits {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
  margin-top: 14px;
}

.landing-card,
.landing-showcase__copy,
.landing-showcase__panel,
.landing-cta {
  border-radius: 30px;
}

.landing-card {
  padding: 22px;
  background: rgba(255, 255, 255, 0.82);
  border: 1px solid var(--stroke);
}

.landing-card h2,
.landing-showcase__copy h2,
.landing-cta h2 {
  font-size: 28px;
  line-height: 1.08;
  letter-spacing: -0.05em;
}

.landing-card p,
.landing-showcase__copy p,
.landing-cta p {
  color: var(--muted);
  line-height: 1.65;
}

.landing-showcase {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(320px, 1.05fr);
  gap: 14px;
  margin-top: 14px;
  align-items: stretch;
}

.landing-showcase__copy,
.landing-showcase__panel,
.landing-cta {
  padding: 24px;
  border: 1px solid var(--stroke);
  background: rgba(255, 255, 255, 0.84);
  box-shadow: var(--shadow);
}

.landing-stat-row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-top: 10px;
}

.landing-stat {
  padding: 16px;
  border-radius: 22px;
  background: rgba(246, 250, 251, 0.95);
  border: 1px solid rgba(15, 23, 42, 0.06);
  display: grid;
  gap: 4px;
}

.landing-stat strong {
  font-size: 24px;
  line-height: 1;
  color: var(--accent);
}

.landing-mini-screen {
  border-radius: 26px;
  background:
    linear-gradient(180deg, rgba(7, 30, 38, 0.98), rgba(13, 61, 72, 0.95)),
    var(--surface);
  color: white;
  padding: 16px;
  min-height: 100%;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    0 20px 60px rgba(15, 23, 42, 0.16);
}

.landing-mini-screen__top {
  display: flex;
  gap: 7px;
  margin-bottom: 16px;
}

.landing-mini-screen__top span {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.24);
}

.landing-mini-screen__body {
  display: grid;
  gap: 12px;
}

.landing-mini-card {
  border-radius: 22px;
  padding: 18px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  display: grid;
  gap: 6px;
}

.landing-mini-card--large {
  min-height: 120px;
}

.landing-mini-card--accent {
  background: linear-gradient(135deg, rgba(94, 211, 208, 0.36), rgba(3, 168, 192, 0.18));
}

.landing-mini-card--chart {
  min-height: 150px;
  background:
    radial-gradient(circle at top right, rgba(94, 211, 208, 0.22), transparent 34%),
    rgba(255, 255, 255, 0.07);
}

.landing-mini-bars {
  display: flex;
  align-items: flex-end;
  gap: 14px;
  height: 100%;
  padding-top: 14px;
}

.landing-mini-bars span {
  width: 18%;
  border-radius: 999px 999px 12px 12px;
  background: linear-gradient(180deg, rgba(110, 231, 183, 0.95), rgba(3, 168, 192, 0.45));
  box-shadow: 0 12px 24px rgba(3, 168, 192, 0.18);
}

.landing-mini-bars span:nth-child(1) {
  height: 58%;
}

.landing-mini-bars span:nth-child(2) {
  height: 76%;
}

.landing-mini-bars span:nth-child(3) {
  height: 42%;
}

.landing-mini-bars span:nth-child(4) {
  height: 90%;
}

.landing-mini-bars span:nth-child(5) {
  height: 68%;
}

.landing-scene__art g {
  transform-origin: center;
}

.landing-scene__art g:nth-of-type(1) {
  animation: float-layer-a 10s ease-in-out infinite;
}

.landing-scene__art g:nth-of-type(2) {
  animation: float-layer-b 11s ease-in-out infinite;
}

.landing-scene__art g:nth-of-type(3) {
  animation: float-layer-c 12s ease-in-out infinite;
}

.landing-scene__art g:nth-of-type(4) {
  animation: float-layer-d 10.5s ease-in-out infinite;
}

.landing-scene__art g:nth-of-type(5) {
  animation: float-layer-e 11.5s ease-in-out infinite;
}

.landing-cta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-top: 14px;
}

.landing-cta__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

@keyframes landing-breathe {
  0%,
  100% {
    transform: translateY(0) scale(1);
  }
  50% {
    transform: translateY(-6px) scale(1.01);
  }
}

@keyframes float-layer-a {
  0%,
  100% {
    transform: translate3d(0, 0, 0) rotate(-7deg);
  }
  50% {
    transform: translate3d(0, -8px, 0) rotate(-6.2deg);
  }
}

@keyframes float-layer-b {
  0%,
  100% {
    transform: translate3d(0, 0, 0) rotate(9deg);
  }
  50% {
    transform: translate3d(0, -10px, 0) rotate(9.7deg);
  }
}

@keyframes float-layer-c {
  0%,
  100% {
    transform: translate3d(0, 0, 0) rotate(-11deg);
  }
  50% {
    transform: translate3d(0, -7px, 0) rotate(-10.2deg);
  }
}

@keyframes float-layer-d {
  0%,
  100% {
    transform: translate3d(0, 0, 0) rotate(-7deg);
  }
  50% {
    transform: translate3d(0, -6px, 0) rotate(-6.5deg);
  }
}

@keyframes float-layer-e {
  0%,
  100% {
    transform: translate3d(0, 0, 0) rotate(-11deg);
  }
  50% {
    transform: translate3d(0, -8px, 0) rotate(-10.4deg);
  }
}

.nav {
