  text-overflow: ellipsis;
}

.transaction-amount-cell {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 1px;
  text-align: right;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.transaction-amount-type-select {
  flex: 0 0 auto;
  width: 18px;
  height: 24px;
  min-height: 24px;
  border: 0;
  border-radius: 5px;
  padding: 0;
  background: transparent;
  color: currentColor;
  font-size: 0.78rem;
  font-weight: 800;
  line-height: 1;
  text-align: center;
  text-align-last: center;
  cursor: pointer;
  overflow: hidden;
  appearance: none;
  -webkit-appearance: none;
  -moz-appearance: none;
}

.transaction-amount-type-select:hover,
.transaction-amount-type-select:focus-visible {
  outline: none;
  background: rgba(3, 168, 192, 0.08);
  box-shadow: inset 0 0 0 1px rgba(3, 168, 192, 0.16);
}

.transaction-amount-type-select option {
  color: var(--text);
  background: #fff;
}

.transaction-amount-cell .transaction-inline-edit--amount {
  min-width: 0;
  width: auto;
  flex: 1 1 auto;
}

.transaction-amount-cell.positive {
  color: var(--good);
}

.transaction-amount-cell.negative {
  color: var(--bad);
}

.transaction-note-meta strong.positive {
  color: var(--good);
}

.transaction-note-meta strong.negative {
  color: var(--bad);
}

.transaction-notes-cell,
.transaction-warning-cell {
  display: flex;
  justify-content: center;
}

.transaction-warning-cell {
  justify-content: flex-end;
}

.transactions-context-strip {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  align-items: flex-start;
  padding: 4px 2px 0;
  flex-wrap: wrap;
}

.transactions-context-strip__filters {
  display: grid;
  gap: 5px;
  min-width: 0;
  flex: 1 1 auto;
}

.transactions-context-strip__label {
  color: var(--muted-2);
  font-size: 0.6rem;
  letter-spacing: 0.16em;
  text-transform: capitalize;
}

.transactions-context-strip__chips {
  display: flex;
  flex-wrap: nowrap;
  gap: 6px;
  overflow-x: auto;
  scrollbar-width: none;
  padding-bottom: 2px;
}

.transactions-context-strip__chips::-webkit-scrollbar {
  display: none;
}

.transactions-context-strip__chip {
  min-height: 24px;
  padding-inline: 8px;
  gap: 4px;
  font-size: 0.72rem;
}

.transactions-page .pill {
  min-height: 28px;
  padding: 5px 9px;
  font-size: 0.72rem;
}

.transactions-context-strip__clear {
  border: 0;
  background: transparent;
  color: var(--accent);
  font: inherit;
  font-size: 0.72rem;
  font-weight: 600;
  padding: 0 4px;
  flex: 0 0 auto;
}

.transactions-filter-count-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 999px;
  background: rgba(3, 168, 192, 0.14);
  color: var(--accent);
  font-size: 0.68rem;
  font-weight: 700;
}

.transactions-inline-filters {
  margin-top: 10px;
  padding: 12px;
  border-radius: 18px;
  border: 1px solid rgba(219, 227, 232, 0.9);
  background: rgba(255, 255, 255, 0.96);
  box-shadow: var(--shadow-soft);
  display: grid;
  gap: 12px;
}

.transactions-inline-filters__head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: flex-start;
}

.transactions-inline-filters__copy {
  margin: 2px 0 0;
  color: var(--muted);
  font-size: 0.78rem;
}

.transaction-note-button {
  width: auto;
  min-width: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--accent);
  box-shadow: none;
  justify-content: center;
}

.transaction-note-button:hover,
.transaction-note-button:focus-visible {
  background: transparent;
  box-shadow: none;
  border: 0;
  outline: none;
}

.transaction-note-button svg {
  width: 14px;
  height: 14px;
}

.transaction-note-button--plain {
  padding: 2px;
}

.warning-chip,
.warning-summary-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border: 1px solid rgba(208, 139, 0, 0.22);
  border-radius: 999px;
  background: rgba(208, 139, 0, 0.12);
  color: var(--warn);
  padding: 0;
  box-shadow: none;
}

.warning-chip {
  cursor: pointer;
}

.warning-summary-button {
  position: relative;
  width: 28px;
  height: 28px;
  border: 0;
  background: transparent;
  color: var(--warn);
  overflow: visible;
  cursor: pointer;
}

.warning-summary-button::after {
  content: attr(data-tooltip);
  position: absolute;
  left: 50%;
  bottom: calc(100% + 8px);
  transform: translateX(-50%) translateY(4px);
  padding: 5px 9px;
  border: 1px solid rgba(208, 139, 0, 0.22);
  border-radius: 999px;
  background: rgba(255, 252, 244, 0.96);
  box-shadow: 0 10px 24px rgba(136, 93, 8, 0.12);
  color: #9a6500;
  font-size: 0.72rem;
  font-weight: 800;
  line-height: 1;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity 160ms ease, transform 160ms ease;
  z-index: 10;
}

.warning-summary-button:hover::after,
.warning-summary-button:focus-visible::after {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

.warning-summary-button__count {
  position: absolute;
  right: 1px;
  bottom: 1px;
  min-width: 13px;
  height: 13px;
  padding: 0 3px;
  border: 1px solid #ffffff;
  border-radius: 999px;
  background: #f6a400;
  color: #ffffff;
  font-size: 0.62rem;
  font-weight: 900;
  line-height: 12px;
  box-shadow: 0 2px 6px rgba(208, 139, 0, 0.24);
}

.warning-mark {
  width: 0;
  height: 0;
  border-left: 10px solid transparent;
  border-right: 10px solid transparent;
  border-bottom: 18px solid var(--warn);
  position: relative;
  flex: 0 0 auto;
}

.warning-mark::after {
  content: "!";
  position: absolute;
  left: 0;
  top: 4px;
  transform: translateX(-50%);
  font-size: 0.72rem;
  font-weight: 800;
  line-height: 1;
  color: #ffffff;
}

.warning-mark--small {
  transform: scale(0.72);
  transform-origin: center;
}

.transactions-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-top: 6px;
  padding-bottom: 2px;
  margin-top: 2px;
  border-top: 1px solid rgba(219, 227, 232, 0.72);
  position: sticky;
  bottom: 0;
  z-index: 5;
  background: transparent;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  box-shadow: none;
}

.transactions-pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  flex-wrap: nowrap;
  white-space: nowrap;
}

.transactions-pagination__nav {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-wrap: nowrap;
  justify-content: center;
  white-space: nowrap;
}

.transactions-pagination__nav .transactions-action-button,
.transactions-selection-menu--footer .transactions-selection-menu__toggle {
  height: 32px;
  min-height: 32px;
}

.transactions-footer__showing {
  color: var(--muted);
  font-size: 0.7rem;
  line-height: 1.2;
  white-space: nowrap;
}

.transactions-pagination__nav .transactions-action-button {
  font-size: 0.68rem;
}

.transactions-pagination__nav .transactions-pagination__page {
  min-width: 20px;
  height: auto;
  min-height: 0;
  padding: 2px 3px;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  color: var(--muted);
}

.transactions-pagination__nav .transactions-pagination__page:hover {
  border: 0;
  background: transparent;
  color: var(--accent-hover);
  box-shadow: none;
}

.transactions-pagination__page.is-active {
  background: transparent;
  border-color: transparent;
  color: var(--accent-hover);
  font-weight: 700;
}

.transactions-pagination__ellipsis {
  color: var(--muted-2);
  font-size: 0.8rem;
  padding: 0 4px;
}

.transactions-pagination__size {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--muted-2);
  font-size: 0.62rem;
  letter-spacing: 0.12em;
  text-transform: capitalize;
  white-space: nowrap;
}

.transactions-pagination__size select {
  height: 32px;
  min-height: 32px;
  padding: 0 10px;
  border-radius: 999px;
  border: 1px solid var(--stroke);
  background: rgba(255, 255, 255, 0.94);
  color: var(--text);
  font-size: 0.7rem;
}

.transaction-drawer-audit {
  grid-column: 1 / -1;
  border: 1px solid var(--stroke);
  border-radius: 16px;
  background: rgba(248, 250, 252, 0.82);
  padding: 10px 12px;
}

.transaction-drawer-audit summary {
  color: var(--muted);
  cursor: pointer;
  font-size: 0.76rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: capitalize;
}

.transaction-drawer-audit__grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-top: 10px;
}

.transaction-drawer-audit__grid div {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.transaction-drawer-audit__grid span {
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 700;
}

.transaction-drawer-audit__grid strong {
  overflow: hidden;
  color: var(--text);
  font-size: 0.86rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.transaction-drawer-audit pre {
  max-height: 180px;
  overflow: auto;
  margin: 10px 0 0;
  border-radius: 12px;
  background: rgba(15, 23, 42, 0.05);
  color: var(--muted);
  font-size: 0.72rem;
  line-height: 1.45;
  padding: 10px;
  white-space: pre-wrap;
}

.table-footer__summary {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 32px;
  flex-wrap: nowrap;
  white-space: nowrap;
}

.transactions-selected-count {
  flex: 0 0 auto;
}

.transactions-footer-snapshot {
  display: grid;
  gap: 4px;
  justify-items: end;
  min-width: min(100%, 260px);
  margin-right: 104px;
  flex: 0 0 auto;
}

.transactions-footer-snapshot__metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
  width: 100%;
}

.transactions-footer-snapshot__metric {
  display: grid;
  gap: 2px;
  padding: 5px 8px;
  border: 1px solid var(--stroke);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.94);
  box-shadow: var(--shadow-soft);
}

.transactions-footer-snapshot__metric--net {
  border-color: var(--stroke);
  background: rgba(255, 255, 255, 0.94);
}

.transactions-footer-snapshot__metric-label {
  color: var(--muted);
  font-size: 0.58rem;
  letter-spacing: 0.12em;
  text-transform: capitalize;
}

.transactions-footer-snapshot__metric-value {
  font-size: 0.8rem;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.transactions-footer-snapshot__metric-value.positive {
  color: var(--good);
}

.transactions-footer-snapshot__metric-value.negative {
  color: var(--bad);
}

.transactions-summary-panel {
  display: grid;
  gap: 10px;
  align-content: start;
  padding: 14px;
  border-radius: 22px;
  border: 1px solid var(--stroke);
  background: rgba(255, 255, 255, 0.92);
  box-shadow: var(--shadow-soft);
  position: sticky;
  top: 14px;
  min-height: 0;
}

.transactions-summary-panel.is-hidden {
  display: none;
}

.transactions-summary-panel__head h4 {
  margin: 4px 0 0;
  font-size: 1rem;
  letter-spacing: -0.03em;
}

.transactions-summary-list {
  display: grid;
  gap: 8px;
  margin: 0;
}

.transactions-summary-list div {
  display: grid;
  gap: 3px;
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(217, 231, 235, 0.7);
}

.transactions-summary-list div:last-child {
  padding-bottom: 0;
  border-bottom: 0;
}

.transactions-summary-list dt {
  color: var(--muted);
  font-size: 0.72rem;
}

.transactions-summary-list dd {
  margin: 0;
  font-size: 0.86rem;
  font-weight: 800;
  letter-spacing: -0.01em;
}

.transactions-summary-list dd.positive {
  color: var(--good);
}

.transactions-summary-list dd.negative {
  color: var(--bad);
}

.transactions-summary-panel__download {
  border: 0;
  color: var(--accent);
  font-weight: 800;
  padding: 0;
  background: transparent;
  text-align: left;
  justify-self: start;
  align-self: end;
  min-height: 22px;
  font-size: 0.78rem;
}

.transactions-popover-card {
  width: min(860px, 100%);
}

.transaction-drawer {
  width: min(980px, 100%);
  max-height: calc(100dvh - 24px);
  overflow-y: auto;
}

.transaction-detail-page {
  width: min(920px, calc(100% - 32px));
  margin: 0 auto;
  padding: 20px 0 96px;
}

.transaction-detail-page__header {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 18px;
  margin-bottom: 18px;
}

.transaction-detail-page__header h1 {
  margin: 3px 0 0;
  font-size: clamp(1.15rem, 2vw, 1.6rem);
  line-height: 1.2;
}

.transaction-detail-page__back {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 34px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--accent);
  font: inherit;
  font-size: 0.8rem;
  font-weight: 800;
  cursor: pointer;
}

.transaction-detail-page__back > span:first-child {
  font-size: 1.6rem;
  font-weight: 500;
  line-height: 1;
}

.transaction-detail-page__form,
.transaction-detail-page__state {
  border: 1px solid var(--stroke);
  border-radius: 24px;
  background: rgba(255, 255, 255, 0.94);
  box-shadow: 0 18px 44px rgba(31, 41, 51, 0.08);
}

.transaction-detail-page__state {
  display: grid;
  place-items: center;
  gap: 10px;
  min-height: 300px;
  padding: 28px;
  text-align: center;
}

.transaction-detail-page__state h2,
.transaction-detail-page__state p {
  margin: 0;
}

.transaction-detail-page__state p {
  color: var(--muted);
}

.transaction-detail-page__spinner {
  width: 28px;
  height: 28px;
  border: 3px solid rgba(3, 168, 192, 0.16);
  border-top-color: var(--accent);
  border-radius: 999px;
  animation: spin 0.8s linear infinite;
}

.transaction-detail-page__summary {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  padding: 22px 24px;
  border-bottom: 1px solid var(--stroke);
  background: linear-gradient(115deg, rgba(3, 168, 192, 0.07), rgba(100, 220, 202, 0.04));
  border-radius: 24px 24px 0 0;
}

.transaction-detail-page__summary > div {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.transaction-detail-page__summary > div strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.transaction-detail-page__summary > div span {
  color: var(--muted);
  font-size: 0.78rem;
}

.transaction-detail-page__amount {
  color: var(--danger);
  font-size: 1.05rem;
  white-space: nowrap;
}

.transaction-detail-page__amount.is-credit {
  color: var(--positive);
}

.transaction-detail-page__amount.is-transfer {
  color: var(--text);
}

.transaction-detail-page__fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  padding: 24px;
}

.transaction-detail-page__fields > label {
  display: grid;
  gap: 7px;
  min-width: 0;
  color: var(--muted);
  font-size: 0.82rem;
}

.transaction-detail-page__fields input,
.transaction-detail-page__fields select,
.transaction-detail-page__fields textarea {
  width: 100%;
}

.transaction-detail-page__type-control,
.transaction-detail-page__money-control {
  display: grid;
  align-items: stretch;
  gap: 8px;
}

.transaction-detail-page__type-control {
  grid-template-columns: 38px minmax(0, 1fr);
}

.transaction-detail-page__type-control > span {
  display: grid;
  place-items: center;
  border: 1px solid var(--stroke);
  border-radius: 12px;
  background: var(--surface-2);
  color: var(--accent);
  font-weight: 900;
}

.transaction-detail-page__money-control {
  grid-template-columns: max-content minmax(0, 1fr);
}

.transaction-detail-page__money-control .currency-selector__button {
  min-width: 68px;
  height: 100%;
}

.transaction-detail-page__notes {
  grid-column: 1 / -1;
}

.transaction-detail-page__notes textarea {
  min-height: 96px;
  resize: vertical;
}

.transaction-detail-page__source {
  margin: 0 24px;
  padding: 14px 0;
  border-top: 1px solid var(--stroke);
  border-bottom: 1px solid var(--stroke);
}

.transaction-detail-page__source summary {
  color: var(--accent);
  font-size: 0.82rem;
  font-weight: 800;
  cursor: pointer;
}

.transaction-detail-page__source dl {
  display: grid;
  gap: 9px;
  margin: 14px 0 0;
}

.transaction-detail-page__source dl div {
  display: grid;
  grid-template-columns: 120px minmax(0, 1fr);
  gap: 12px;
}

.transaction-detail-page__source dt {
  color: var(--muted);
  font-size: 0.78rem;
}

.transaction-detail-page__source dd {
  margin: 0;
  overflow-wrap: anywhere;
  font-size: 0.84rem;
}

.transaction-detail-page__message {
  margin: 16px 24px 0;
  color: var(--accent);
  font-size: 0.82rem;
  font-weight: 700;
}

.transaction-detail-page__actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  padding: 18px 24px 22px;
}

.transaction-detail-page__delete-confirm {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-right: auto;
  color: var(--danger);
  font-size: 0.8rem;
  font-weight: 700;
}

@media (max-width: 767px) {
  .transaction-detail-page {
    width: min(100%, calc(100% - 20px));
    padding-top: 8px;
    padding-bottom: calc(104px + env(safe-area-inset-bottom));
  }

  .transaction-detail-page__header {
    gap: 10px;
    margin-bottom: 10px;
    padding: 0 4px;
  }

  .transaction-detail-page__back > span:last-child,
  .transaction-detail-page__header .eyebrow {
    display: none;
  }

  .transaction-detail-page__header h1 {
    margin: 0;
    font-size: 0.9rem;
  }

  .transaction-detail-page__form,
  .transaction-detail-page__state {
    border-radius: 20px;
  }

  .transaction-detail-page__summary {
    gap: 10px;
    padding: 16px;
    border-radius: 20px 20px 0 0;
  }

  .transaction-detail-page__summary > div strong,
  .transaction-detail-page__amount {
    font-size: 0.88rem;
  }

  .transaction-detail-page__fields {
    grid-template-columns: 1fr;
    gap: 13px;
    padding: 18px 16px;
  }

  .transaction-detail-page__notes {
    grid-column: auto;
  }

  .transaction-detail-page__source {
    margin-inline: 16px;
  }

  .transaction-detail-page__source dl div {
    grid-template-columns: 1fr;
    gap: 2px;
  }

  .transaction-detail-page__actions {
    padding: 16px;
  }

  .transaction-detail-page__delete-confirm {
    flex-wrap: wrap;
  }
}

.modal-backdrop--transaction-detail {
  align-items: stretch;
  justify-content: flex-end;
  padding: 0;
  background: transparent;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

.transaction-drawer--sidepanel {
  width: min(480px, 100vw);
  height: 100dvh;
  max-height: none;
  margin-left: auto;
  border-radius: 24px 0 0 24px;
  border-right: 0;
  box-shadow: -18px 0 36px rgba(31, 41, 51, 0.16);
  overflow: auto;
}

.transaction-drawer__head {
  gap: 12px;
  align-items: flex-start;
}

.transaction-drawer__head-title {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  min-width: 0;
}

.transaction-drawer__back-button {
  flex: none;
}

.transaction-drawer__head .eyebrow {
  margin-bottom: 4px;
}

.transaction-drawer__head h4 {
  margin: 0;
}

.transaction-drawer__close-button {
  flex: none;
}

.transaction-drawer-review-status {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

.transaction-drawer-review-status__chip {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 5px 10px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 999px;
  background: rgba(248, 251, 252, 0.94);
  color: var(--muted);
  font-size: 0.74rem;
  font-weight: 800;
  letter-spacing: 0.04em;
}

.transaction-drawer-review-status__chip--clear {
