  font-weight: 700;
}

.admin-analytics-status.is-ready {
  color: #087f5b;
  border-color: rgba(16, 185, 129, 0.22);
  background: rgba(16, 185, 129, 0.08);
}

.admin-analytics-status.is-muted {
  color: var(--muted);
}

.admin-analytics-metric-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.admin-analytics-card {
  display: grid;
  gap: 6px;
  min-width: 0;
  padding: 16px;
  border: 1px solid rgba(3, 168, 192, 0.12);
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.86);
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.04);
}

.admin-analytics-card--warning {
  border-color: rgba(245, 158, 11, 0.28);
  background: rgba(255, 251, 235, 0.9);
}

.admin-analytics-card--danger {
  border-color: rgba(239, 68, 68, 0.24);
  background: rgba(254, 242, 242, 0.9);
}

.admin-analytics-card span,
.admin-analytics-card small {
  color: var(--muted);
}

.admin-analytics-card span {
  font-size: 12px;
  text-transform: capitalize;
  letter-spacing: 0.08em;
}

.admin-analytics-card strong {
  font-size: 1.55rem;
  line-height: 1.05;
  letter-spacing: -0.04em;
}

.admin-analytics-card small {
  font-size: 12px;
}

.admin-analytics-workspace__grid {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(320px, 0.85fr);
  gap: 18px;
}

.admin-funnel-list,
.admin-alert-list,
.admin-event-group__list {
  display: grid;
  gap: 10px;
}

.admin-funnel-card {
  display: grid;
  gap: 14px;
  padding: 15px;
  border: 1px solid rgba(219, 227, 232, 0.94);
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.72);
}

.admin-funnel-card__head,
.admin-event-group__head,
.admin-alert-item {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.admin-funnel-card__head div,
.admin-event-group__head {
  display: grid;
  gap: 4px;
}

.admin-funnel-card__head span,
.admin-event-group__head span,
.admin-funnel-card__step span,
.admin-alert-item span {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}

.admin-funnel-card__head > strong {
  color: var(--accent);
  white-space: nowrap;
}

.admin-funnel-card__steps {
  display: grid;
  gap: 10px;
}

.admin-funnel-card__step {
  display: grid;
  gap: 6px;
}

.admin-funnel-card__step > div:first-child {
  display: flex;
  justify-content: space-between;
  gap: 10px;
}

.admin-funnel-card__step strong {
  font-size: 13px;
}

.admin-funnel-card__bar {
  height: 7px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(3, 168, 192, 0.1);
}

.admin-funnel-card__bar span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #03a8c0, #5ed3d0);
}

.admin-alert-item {
  padding: 13px 14px;
  border: 1px solid rgba(219, 227, 232, 0.94);
  border-radius: 17px;
  background: rgba(255, 255, 255, 0.7);
}

.admin-alert-item div {
  display: grid;
  gap: 3px;
}

.admin-alert-item.is-good {
  border-color: rgba(16, 185, 129, 0.18);
  background: rgba(236, 253, 245, 0.72);
}

.admin-alert-item.is-warning {
  border-color: rgba(245, 158, 11, 0.22);
  background: rgba(255, 251, 235, 0.8);
}

.admin-alert-item.is-danger {
  border-color: rgba(239, 68, 68, 0.22);
  background: rgba(254, 242, 242, 0.82);
}

.admin-alert-item.is-neutral {
  background: rgba(245, 248, 250, 0.84);
}

.admin-event-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.admin-event-group {
  min-width: 0;
  padding: 15px;
  border: 1px solid rgba(219, 227, 232, 0.94);
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.66);
}

.admin-event-group__head {
  grid-template-columns: minmax(0, 1fr) auto;
  margin-bottom: 10px;
}

.admin-event-row {
  display: grid;
  gap: 3px;
  padding: 9px 0;
  border-top: 1px solid rgba(219, 227, 232, 0.72);
}

.admin-event-row code {
  color: var(--text);
  font-size: 12px;
  overflow-wrap: anywhere;
}

.admin-event-row span,
.admin-analytics__footnote {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}

.admin-analytics__footnote {
  margin: 0;
}

.admin-audit-logs {
  display: grid;
  gap: 18px;
}

.admin-audit-logs__table strong {
  display: block;
  word-break: break-word;
}

.admin-audit-logs__table pre {
  max-width: 300px;
  max-height: 180px;
  overflow: auto;
  margin: 10px 0 0;
  padding: 10px;
  border-radius: 12px;
  background: rgba(245, 248, 250, 0.92);
  white-space: pre-wrap;
  word-break: break-word;
  font-size: 11px;
}

.admin-analytics__trend-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.admin-error-logs {
  display: grid;
  gap: 18px;
}

.admin-error-logs__summary {
  background:
    radial-gradient(circle at top right, rgba(245, 158, 11, 0.08), transparent 24%),
    rgba(255, 255, 255, 0.9);
}

.admin-error-logs__toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: flex-end;
}

.admin-error-logs__pills {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.admin-error-logs__table-panel {
  min-width: 0;
}

.admin-error-logs__table strong {
  display: block;
  word-break: break-word;
}

.admin-error-logs__subtle {
  color: var(--muted);
  font-size: 12px;
}

.admin-error-logs__details summary {
  cursor: pointer;
  color: var(--accent);
  font-size: 13px;
  font-weight: 600;
}

.admin-error-logs__detail-body {
  display: grid;
  gap: 10px;
  min-width: 260px;
  margin-top: 10px;
}

.admin-error-logs__detail-body div {
  display: grid;
  gap: 4px;
}

.admin-error-logs__detail-body span {
  color: var(--muted);
  font-size: 11px;
  text-transform: capitalize;
  letter-spacing: 0.08em;
}

.admin-error-logs__detail-body pre {
  margin: 0;
  max-width: 420px;
  max-height: 240px;
  overflow: auto;
  padding: 12px;
  border-radius: 14px;
  border: 1px solid var(--stroke);
  background: rgba(245, 248, 250, 0.92);
  white-space: pre-wrap;
  word-break: break-word;
  font-size: 12px;
  line-height: 1.45;
  color: var(--muted);
}

.admin-error-logs__empty {
  padding: 20px 16px;
  text-align: center;
  color: var(--muted);
}

.admin-inquiries {
  display: grid;
  gap: 18px;
}

.admin-inquiries__toolbar {
  display: grid;
  gap: 14px;
}

.admin-inquiries__search {
  flex: 1 1 360px;
}

.admin-inquiries__search input {
  width: 100%;
}

.admin-inquiries__stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.admin-inquiries__stats div {
  display: grid;
  gap: 4px;
  padding: 14px 16px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.84);
  border: 1px solid rgba(3, 168, 192, 0.12);
}

.admin-inquiries__stats span {
  color: var(--muted);
  font-size: 12px;
  text-transform: capitalize;
  letter-spacing: 0.08em;
}

.admin-inquiries__stats strong {
  font-size: 1.35rem;
  line-height: 1.1;
}

@media (max-width: 1100px) {
  .admin-analytics-metric-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .admin-analytics-workspace__grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 1100px) {
  .admin-hub__nav-card,
  .admin-analytics-workspace__hero {
    align-items: stretch;
    flex-direction: column;
  }

  .admin-hub__nav-actions,
  .admin-analytics-workspace__hero-actions {
    justify-content: flex-start;
  }

  .admin-analytics-metric-grid,
  .admin-event-grid {
    grid-template-columns: 1fr;
  }

  .admin-analytics-workspace__hero h2 {
    max-width: none;
  }
}

.admin-inquiries__notice {
  padding: 14px 16px;
  border-radius: 18px;
  border: 1px solid rgba(3, 168, 192, 0.16);
  background: rgba(3, 168, 192, 0.06);
  color: var(--text);
}

.admin-inquiries__layout {
  display: grid;
  grid-template-columns: minmax(280px, 0.82fr) minmax(0, 1.18fr);
  gap: 18px;
  align-items: start;
}

.admin-inquiries__list-panel,
.admin-inquiries__detail {
  padding: 18px;
  border-radius: 26px;
}

.admin-inquiries__list-panel {
  display: grid;
  gap: 14px;
}

.admin-inquiries__list-head {
  display: grid;
  gap: 4px;
}

.admin-inquiries__list-head p {
  color: var(--muted);
}

.admin-inquiries__list {
  display: grid;
  gap: 10px;
  max-height: 72vh;
  overflow: auto;
}

.admin-inquiries__item {
  display: grid;
  gap: 8px;
  text-align: left;
  padding: 14px 15px;
  border-radius: 18px;
  border: 1px solid rgba(15, 23, 42, 0.08);
  background: rgba(255, 255, 255, 0.9);
  transition:
    transform 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease;
}

.admin-inquiries__item:hover,
.admin-inquiries__item:focus-visible,
.admin-inquiries__item.is-selected {
  transform: translateY(-1px);
  border-color: rgba(3, 168, 192, 0.2);
  box-shadow: 0 12px 24px rgba(15, 23, 42, 0.08);
}

.admin-inquiries__item-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
}

.admin-inquiries__item-head span {
  color: var(--accent-hover);
  font-size: 12px;
  font-weight: 600;
  text-transform: capitalize;
  letter-spacing: 0.08em;
}

.admin-inquiries__item p {
  color: var(--muted);
}

.admin-inquiries__item small {
  color: var(--muted-2);
}

.admin-inquiries__preview {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  color: var(--text);
  line-height: 1.55;
}

.admin-inquiries__empty {
  padding: 18px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.72);
  color: var(--muted);
  border: 1px dashed var(--stroke);
}

.admin-inquiries__detail {
  display: grid;
  gap: 16px;
}

.admin-inquiries__detail-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  align-items: flex-start;
}

.admin-inquiries__detail-head p {
  color: var(--muted);
}

.admin-inquiries__detail-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.admin-inquiries__panel {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  padding: 16px;
  border-radius: 22px;
  background: rgba(3, 168, 192, 0.05);
  border: 1px solid rgba(3, 168, 192, 0.12);
}

.admin-inquiries__panel div {
  display: grid;
  gap: 6px;
}

.admin-inquiries__panel span {
  color: var(--muted-2);
  font-size: 12px;
  text-transform: capitalize;
  letter-spacing: 0.08em;
}

.admin-inquiries__panel strong {
  color: var(--text);
  font-size: 14px;
}

.admin-inquiries__message,
.admin-inquiries__composer {
  display: grid;
  gap: 12px;
}

.admin-inquiries__message p {
  white-space: pre-wrap;
  color: var(--muted);
  line-height: 1.7;
}

.admin-inquiries__field {
  display: grid;
  gap: 8px;
}

.admin-inquiries__field textarea {
  min-height: 180px;
  resize: vertical;
}

.admin-inquiries__footer {
  display: flex;
  justify-content: flex-end;
}

.admin-inquiries__attachment {
  display: grid;
  gap: 12px;
}

.admin-inquiries__attachment-link {
  display: grid;
  gap: 10px;
  padding: 14px;
  border-radius: 18px;
  border: 1px solid rgba(3, 168, 192, 0.12);
  background: rgba(3, 168, 192, 0.05);
}

.admin-inquiries__attachment-image {
  width: 100%;
  max-width: 280px;
  border-radius: 14px;
  display: block;
  object-fit: contain;
  background: rgba(255, 255, 255, 0.94);
}

.admin-users__table-panel {
  min-width: 0;
}

.admin-users__table-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.admin-users__loading {
  padding: 18px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.72);
  border: 1px dashed var(--stroke);
  color: var(--muted);
}

.admin-users__table-wrap {
  overflow: auto;
  border-radius: 20px;
  border: 1px solid var(--stroke);
  background: rgba(255, 255, 255, 0.8);
}

.admin-users__directory-wrap {
  max-height: 68vh;
}

.admin-users__table {
  width: max-content;
  min-width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.admin-users__table thead th {
  position: sticky;
  top: 0;
  background: rgba(245, 248, 250, 0.96);
  border-bottom: 1px solid var(--stroke);
  color: var(--muted);
  text-align: left;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: capitalize;
  padding: 14px 16px;
  white-space: nowrap;
}

.admin-users__directory-table thead th:nth-child(1),
.admin-users__directory-table tbody td:nth-child(1) {
  width: 235px;
}

.admin-users__directory-table thead th:nth-child(2),
.admin-users__directory-table tbody td:nth-child(2) {
  width: 150px;
}

.admin-users__directory-table thead th:nth-child(3),
.admin-users__directory-table tbody td:nth-child(3) {
  width: 170px;
}

.admin-users__directory-table thead th:nth-child(4),
.admin-users__directory-table tbody td:nth-child(4) {
  width: 160px;
}

.admin-users__directory-table thead th:nth-child(5),
.admin-users__directory-table tbody td:nth-child(5) {
  width: 130px;
}

.admin-users__directory-table thead th:nth-child(6),
.admin-users__directory-table tbody td:nth-child(6) {
  width: 210px;
}

.admin-users__directory-table thead th:nth-child(7),
.admin-users__directory-table tbody td:nth-child(7) {
  width: 235px;
  min-width: 235px;
}

.admin-users__table tbody tr {
  border-bottom: 1px solid rgba(219, 227, 232, 0.8);
}

.admin-users__table tbody tr.is-dirty {
  background: rgba(3, 168, 192, 0.04);
}

.admin-users__table tbody td {
  padding: 14px 16px;
  vertical-align: top;
  overflow: hidden;
}

.admin-users__directory-table tbody td {
  padding: 10px 12px;
}

.admin-users__inline-input,
.admin-users__inline-select {
  width: 100%;
  min-width: 0;
  height: 40px;
  min-height: 40px;
  padding: 0 12px;
  border-radius: 12px;
  border-color: rgba(219, 227, 232, 0.94);
  background: rgba(255, 255, 255, 0.96);
  font-size: 14px;
}

.admin-users__inline-input::placeholder {
  color: var(--muted-2);
}

.admin-users__inline-input:focus-visible,
.admin-users__inline-select:focus-visible {
  box-shadow: 0 0 0 4px rgba(3, 168, 192, 0.14);
}

.admin-users__directory-table .admin-users__inline-input,
.admin-users__directory-table .admin-users__inline-select {
  height: 34px;
  min-height: 34px;
  padding: 0 10px;
  border-radius: 10px;
  font-size: 13px;
}

.admin-users__cell-note {
  display: block;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.35;
}

.admin-users__user-cell > * + *,
.admin-users__plan-cell > * + *,
.admin-users__usage-cell > * + *,
.admin-users__activity-cell > * + *,
.admin-users__status-cell > * + * {
  margin-top: 4px;
}

.admin-users__limits-cell {
  white-space: nowrap;
}

.admin-users__limits-cell > .admin-users__inline-input {
  display: inline-block;
  width: calc((100% - 12px) / 3);
  vertical-align: top;
}

.admin-users__limits-cell > .admin-users__inline-input + .admin-users__inline-input {
  margin-left: 6px;
}

.admin-users__status-cell > .admin-users__pill {
  margin-right: 6px;
}

.admin-users__user-cell strong,
.admin-users__usage-cell strong,
.admin-users__activity-cell strong {
  font-size: 14px;
  line-height: 1.25;
}

.admin-users__mono {
  display: inline-block;
  max-width: 100%;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  font-size: 12px;
  color: var(--muted);
  word-break: break-all;
}

.admin-users__pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  width: fit-content;
  padding: 5px 9px;
  border-radius: 999px;
  background: rgba(3, 168, 192, 0.08);
  color: var(--accent);
  font-size: 11px;
  font-weight: 600;
  text-transform: capitalize;
}

.admin-users__pill--pro {
  background: rgba(94, 211, 208, 0.16);
  color: #0f766e;
}

.admin-users__pill--free {
  background: rgba(59, 130, 246, 0.08);
  color: #1d4ed8;
}

.admin-users__pill--success {
  background: rgba(34, 197, 94, 0.12);
  color: #15803d;
}

.admin-users__pill--warn {
  background: rgba(245, 158, 11, 0.12);
  color: #b45309;
}

.admin-users__pill--locked {
  background: rgba(239, 68, 68, 0.12);
  color: #b91c1c;
}

.admin-users__pill--sync {
  background: rgba(59, 130, 246, 0.12);
  color: #1d4ed8;
}

.admin-users__row-actions {
  display: grid;
  grid-auto-flow: column;
  justify-content: start;
  align-items: center;
  gap: 6px;
}

.admin-users__row-actions .button {
  min-width: 0;
}

.admin-users__row-actions .button-small {
  line-height: 1;
}

.admin-users__data-actions {
  position: relative;
}

.admin-users__data-actions > summary {
  list-style: none;
  cursor: pointer;
}

.admin-users__data-actions > summary::-webkit-details-marker {
  display: none;
}

.admin-users__data-actions-menu {
  position: absolute;
  z-index: 20;
  top: calc(100% + 6px);
  right: 0;
  display: grid;
  width: 190px;
  padding: 6px;
  border: 1px solid var(--stroke);
  border-radius: 12px;
  background: #fff;
  box-shadow: 0 16px 36px rgba(15, 23, 42, 0.14);
}

.admin-users__data-actions-menu button {
  border: 0;
  border-radius: 8px;
  background: transparent;
  padding: 9px 10px;
  color: var(--ink);
  text-align: left;
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}

.admin-users__data-actions-menu button:hover,
.admin-users__data-actions-menu button:focus-visible {
  background: rgba(3, 168, 192, 0.08);
}

.admin-users__data-actions-menu button.is-danger {
  color: #b91c1c;
}

.admin-users__pager {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  color: var(--muted);
}

.admin-users__errors-panel {
  display: grid;
  gap: 16px;
  margin-top: 18px;
}

.admin-users__error-details {
  max-width: 260px;
}

.admin-users__error-details summary {
  cursor: pointer;
  color: var(--accent);
  font-size: 13px;
}

.admin-users__error-details pre {
  margin-top: 10px;
  max-width: 320px;
  max-height: 220px;
  overflow: auto;
  padding: 12px;
  border-radius: 14px;
  background: rgba(245, 248, 250, 0.92);
  border: 1px solid var(--stroke);
  white-space: pre-wrap;
  word-break: break-word;
  font-size: 12px;
  line-height: 1.45;
  color: var(--muted);
}

.empty-state {
  padding: 16px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid var(--stroke);
  color: var(--muted);
}

.empty-state--review {
  display: grid;
  gap: 10px;
  padding: 22px;
  border-radius: 20px;
  background:
    radial-gradient(circle at top left, rgba(3, 168, 192, 0.06), transparent 42%),
    rgba(255, 255, 255, 0.9);
  border-color: rgba(3, 168, 192, 0.16);
  color: var(--text);
}

.empty-state--review p {
  color: var(--muted);
  max-width: 60ch;
}

.empty-state--illustrated {
  display: grid;
  justify-items: center;
  align-content: start;
