.landing-page::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 12% 10%, rgba(3, 168, 192, 0.1), transparent 24%),
    radial-gradient(circle at 88% 12%, rgba(110, 231, 183, 0.08), transparent 22%),
    radial-gradient(circle at 50% 110%, rgba(9, 30, 42, 0.06), transparent 22%);
  z-index: -1;
}

.landing-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  position: sticky;
  top: 0;
  z-index: 30;
  overflow: visible;
  width: 100vw;
  margin-left: calc(50% - 50vw);
  padding: 8px clamp(12px, 2.5vw, 20px);
  transition:
    background-color 180ms ease,
    backdrop-filter 180ms ease,
    -webkit-backdrop-filter 180ms ease,
    border-color 180ms ease,
    box-shadow 180ms ease;
}

.landing-nav--sticky {
  position: sticky !important;
  top: 0 !important;
  z-index: 1000 !important;
  background: transparent;
  border-bottom: 1px solid transparent;
}

.landing-nav--scrolled {
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  background: rgba(255, 255, 255, 0.9);
  border-bottom: 1px solid rgba(15, 23, 42, 0.06);
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.04);
}

.landing-brand {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 700;
  font-size: 14px;
  letter-spacing: -0.03em;
}

.landing-brand__mark {
  width: 34px;
  height: auto;
  border-radius: 0;
  box-shadow: none;
  background: transparent;
}

.landing-brand__wordmark {
  width: min(98px, 100%);
  height: auto;
  border-radius: 0;
  box-shadow: none;
  background: transparent;
}

.landing-nav__links {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.landing-nav__desktop {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: 18px;
  width: 100%;
}

.landing-nav__menus {
  display: inline-flex;
  align-items: center;
  justify-self: center;
  justify-content: center;
  gap: 8px;
}

.landing-nav__desktop-actions {
  display: inline-flex;
  align-items: center;
  justify-self: end;
  gap: 12px;
}

.landing-account-link {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--text);
  font-weight: 600;
  letter-spacing: -0.02em;
  white-space: nowrap;
}

.landing-account-link--desktop {
  justify-self: end;
}

.landing-account-link:hover,
.landing-account-link:focus-visible {
  color: var(--text);
}

.landing-account-link__avatar {
  width: 34px;
  height: 34px;
  border-radius: 999px;
  overflow: hidden;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.1);
}

.landing-account-link__avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.landing-account-link--mobile {
  min-height: 32px;
  padding: 0 10px 0 0;
  font-size: 13px;
  justify-self: end;
  position: relative;
  z-index: 2;
}

.landing-nav__mobile,
.landing-nav__mobile-backdrop,
.landing-nav__mobile-menu,
.landing-nav__mobile-toggle,
.landing-brand--mobile,
.landing-carousel {
  display: none;
}

.landing-nav__menu {
  position: relative;
  display: inline-flex;
  align-items: center;
}

.landing-nav__menu-trigger,
.landing-nav__link {
  display: inline-flex;
  align-items: center;
  min-height: 36px;
  padding: 0 10px;
  border-radius: 999px;
  font-size: 15px;
  line-height: 1.2;
  color: var(--muted);
  font-weight: 400;
}

.landing-nav__menu-trigger {
  gap: 5px;
  border: 0;
  background: transparent;
  cursor: pointer;
  font: inherit;
  transition:
    color 160ms ease,
    background 160ms ease;
}

.landing-nav__menu-trigger.is-active,
.landing-nav__menu-trigger[aria-expanded="true"] {
  color: var(--text);
}

.landing-nav__chevron {
  font-size: 0.8em;
  line-height: 1;
  color: var(--muted-2);
}

.landing-nav__menu-trigger[aria-expanded="true"] .landing-nav__chevron {
  transform: rotate(180deg);
}

.landing-nav__submenu {
  position: absolute;
  top: calc(100% + 10px);
  left: 0;
  display: grid;
  gap: 3px;
  min-width: 196px;
  padding: 10px;
  border-radius: 20px;
  border: 1px solid rgba(224, 232, 238, 0.92);
  background: #ffffff !important;
  background-color: #ffffff !important;
  opacity: 1;
  isolation: isolate;
  box-shadow: 0 18px 36px rgba(15, 23, 42, 0.1);
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  z-index: 40;
}

.landing-nav__submenu a {
  min-height: 36px;
  display: flex;
  align-items: center;
  padding: 0 11px;
  border-radius: 12px;
  color: var(--muted);
  font-size: 14px;
  font-weight: 400;
  transition:
    background 140ms ease,
    color 140ms ease,
    transform 140ms ease;
}

.landing-nav__submenu a strong {
  font-weight: 400;
}

.landing-nav__submenu-link--featured,
.landing-nav__submenu-link--featured strong {
  color: var(--accent);
  font-weight: 700 !important;
}

.landing-nav__submenu a:hover,
.landing-nav__submenu a:focus-visible {
  color: var(--text);
  background: rgba(3, 168, 192, 0.08);
  transform: translateX(1px);
}

.landing-nav__link {
  transition:
    color 160ms ease,
    background 160ms ease;
}

.landing-nav__link:hover,
.landing-nav__link:focus-visible {
  color: var(--text);
}

.landing-nav__link[aria-current="page"] {
  color: var(--text);
  font-weight: 600;
}

.landing-nav__button {
  min-height: 36px;
  padding-inline: 12px;
}

.landing-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(320px, 0.95fr);
  gap: 24px;
  align-items: center;
  padding: 40px 0 26px;
}

.landing-hero__copy {
  display: grid;
  gap: 18px;
