.clover-loading-screen {
  --splash-logo-mark-size: clamp(118px, 16vw, 152px);
  position: relative;
  min-height: 100dvh;
  display: grid;
  place-items: center;
  padding: 32px 20px;
  overflow: hidden;
  isolation: isolate;
  background: transparent;
}

.clover-loading-screen__card {
  position: relative;
  z-index: 1;
  width: min(100%, 560px);
  display: grid;
  justify-items: center;
  gap: 18px;
  padding: 0;
  overflow: visible;
  text-align: center;
  background: transparent;
}

body[data-clover-shell-ready="true"] .clover-loading-screen::before {
  content: "";
  position: fixed;
  z-index: 2;
  top: 0;
  left: 0;
  width: 100%;
  height: 2px;
  opacity: 0;
  background: linear-gradient(90deg, transparent, var(--accent), var(--mint), transparent);
  background-size: 220% 100%;
  animation: route-loading-reveal 0.01s 0.25s forwards, route-loading-progress 1s linear 0.25s infinite;
}

body[data-clover-shell-ready="true"] .clover-loading-screen__card {
  opacity: 0;
  animation: clover-loading-card-reveal 0.01s 4s forwards;
}

body[data-clover-shell-ready="true"] .clover-loading-screen--prompt::before {
  animation-delay: 0.08s;
}

body[data-clover-shell-ready="true"] .clover-loading-screen--prompt .clover-loading-screen__card {
  animation-delay: 0.7s;
}

@keyframes clover-loading-card-reveal {
  to { opacity: 1; }
}

.clover-loading-screen__logo {
  position: relative;
  width: var(--splash-logo-mark-size);
  height: var(--splash-logo-mark-size);
  display: grid;
  place-items: center;
  overflow: visible;
  background: transparent;
}

.clover-loading-screen__mark {
  position: relative;
  z-index: 1;
  display: block;
  width: 100%;
  height: 100%;
  aspect-ratio: 1 / 1;
  align-items: center;
  justify-items: center;
  overflow: visible;
  pointer-events: none;
}

.clover-loading-screen__copy {
  display: grid;
  justify-items: center;
  width: min(100%, 520px);
  min-height: 1.6rem;
  overflow: visible;
}

.clover-loading-screen__copy .eyebrow {
  margin: 0;
}

.clover-loading-screen__copy h2 {
  position: relative;
  margin: 0;
  width: 100%;
  max-width: 34ch;
  min-height: 1.6rem;
  color: rgba(31, 41, 51, 0.72);
  font-size: clamp(0.98rem, 1.8vw, 1.2rem);
  font-weight: 400;
  line-height: 1.35;
  letter-spacing: -0.012em;
}

@keyframes clover-loading-screen-pulse {
  0%,
  32%,
  100% {
    opacity: 0.84;
    transform: scale(0.965);
    filter: saturate(0.95);
  }

  16% {
    opacity: 1;
    transform: scale(1.055);
    filter: saturate(1.08);
  }
}

.clover-loading-screen__leaf {
  transform-box: fill-box;
  object-fit: contain;
  transform-origin: center;
  animation: clover-loading-screen-pulse 2s cubic-bezier(0.45, 0.05, 0.55, 0.95) infinite;
  will-change: transform, opacity, filter;
}

.clover-loading-screen__leaf--1 {
  animation-delay: 0s;
}

.clover-loading-screen__leaf--2 {
  animation-delay: 0.25s;
}

.clover-loading-screen__leaf--3 {
  animation-delay: 0.5s;
}

.clover-loading-screen__leaf--4 {
  animation-delay: 0.75s;
}

