.split-bill-home,
.split-bill-editor,
.split-bill-detail {
  display: grid;
  gap: 20px;
}

.split-bill-mobile-home {
  display: none;
}

.split-bill-subtle-empty {
  color: var(--muted);
  font-size: 0.84rem;
}

.split-bill-table__more-link {
  align-self: start;
  width: fit-content;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--accent);
  font: inherit;
  font-size: 0.84rem;
  font-weight: 600;
}

.split-bill-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 20px;
  padding: 24px;
  border: 1px solid rgba(3, 168, 192, 0.16);
  background:
    radial-gradient(circle at top left, rgba(94, 211, 208, 0.18), transparent 36%),
    linear-gradient(135deg, rgba(3, 168, 192, 0.08), rgba(15, 23, 42, 0.02));
}

.split-bill-hero__copy {
  display: grid;
  gap: 12px;
  align-content: start;
}

.split-bill-hero__copy h1,
.split-bill-editor__section h1,
.split-bill-detail__hero h1 {
  margin: 0;
  font-size: clamp(2rem, 4vw, 3.4rem);
  line-height: 1.02;
  letter-spacing: -0.04em;
}

.split-bill-hero__copy p,
.split-bill-editor__section p,
.split-bill-detail__hero p {
  margin: 0;
  max-width: 62ch;
  color: var(--text-secondary);
}

.split-bill-hero__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 6px;
}

.split-bill-page-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.split-bill-action-button {
  gap: 7px;
}

.split-bill-action-button--add {
  background: rgba(255, 255, 255, 0.92);
  border-color: rgba(3, 168, 192, 0.22);
  color: var(--accent);
  box-shadow: none;
  font-weight: 600;
}

.split-bill-action-button--add:hover,
.split-bill-action-button--add:focus-visible {
  background: rgba(245, 252, 253, 0.98);
  border-color: rgba(3, 168, 192, 0.38);
  color: var(--accent);
  box-shadow: none;
}

.split-bill-currency-selector .currency-selector__trigger-all {
  min-width: 76px;
}

.split-bill-currency-menu {
  position: relative;
}

.split-bill-currency-menu > summary {
  list-style: none;
  cursor: pointer;
}

.split-bill-currency-menu > summary::-webkit-details-marker {
  display: none;
}

.split-bill-hero__stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.split-bill-stat {
  display: grid;
  gap: 6px;
  padding: 16px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.68);
  border: 1px solid rgba(15, 23, 42, 0.08);
}

.split-bill-stat span,
.split-bill-card__summary span,
.split-bill-group-card p,
.split-bill-detail__meta-grid span,
.split-bill-detail__balance-card span,
.split-bill-detail__payment p,
.split-bill-editor__totals span {
  font-size: 0.84rem;
  color: var(--text-secondary);
}

.split-bill-stat strong {
  font-size: 1.45rem;
  letter-spacing: -0.03em;
}

.split-bill-grid,
.split-bill-detail__grid,
.split-bill-editor__layout {
  display: grid;
  gap: 20px;
  grid-template-columns: minmax(0, 1.5fr) minmax(320px, 0.9fr);
  align-items: start;
}

.split-bill-panel,
.split-bill-editor__section,
.split-bill-detail__panel {
  display: grid;
  gap: 16px;
}

.split-bill-panel__head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: flex-start;
}

.split-bill-panel__head h2,
.split-bill-panel__head h3 {
  margin: 0;
  font-size: 1.2rem;
}

.split-bill-table {
  display: grid;
  gap: 8px;
}

.split-bill-pulse {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  position: sticky;
  top: 0;
  z-index: 8;
  padding: 8px 0;
  background: var(--page-bg, #f8fbfc);
}

.split-bill-pulse__metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.split-bill-pulse__metrics article {
  display: grid;
  gap: 4px;
  min-height: 84px;
  padding: 14px;
  border-radius: 18px;
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.92), rgba(248, 251, 252, 0.74)),
    rgba(3, 168, 192, 0.05);
  border: 1px solid rgba(15, 23, 42, 0.07);
}

.split-bill-pulse__metrics span {
  color: var(--text-secondary);
  font-size: 0.78rem;
  font-weight: 700;
}

.split-bill-pulse__metrics strong {
  align-self: end;
  font-size: 1.18rem;
}

.split-bill-table__footer {
  display: flex;
  justify-content: flex-end;
}

.split-bill-table__header,
.split-bill-table__row {
  display: grid;
  gap: 12px;
  align-items: center;
}

.split-bill-table--bills .split-bill-table__header,
.split-bill-table--bills .split-bill-table__row {
  grid-template-columns: minmax(0, 2.4fr) minmax(120px, 0.72fr) minmax(160px, 0.9fr) minmax(140px, 0.72fr) minmax(90px, 0.55fr) minmax(36px, 44px);
}

.split-bill-table--groups .split-bill-table__header,
.split-bill-table--groups .split-bill-table__row {
  grid-template-columns: minmax(0, 2fr) minmax(160px, 0.95fr) minmax(150px, 0.72fr) minmax(110px, 0.55fr);
}

.split-bill-table__header {
  padding: 0 12px;
  color: var(--text-secondary);
  font-size: 0.82rem;
  font-weight: 400;
  letter-spacing: 0.01em;
  text-transform: none;
}

.split-bill-table__header span {
  font-weight: 400;
  color: var(--text);
}

.split-bill-table__row {
  padding: 14px 12px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid rgba(15, 23, 42, 0.08);
}

.split-bill-table__bill {
  display: grid;
  gap: 4px;
}

.split-bill-table__bill span {
  color: var(--text-secondary);
  font-size: 0.84rem;
}

.split-bill-table__hint {
  margin-top: 6px;
  color: var(--text-secondary);
  font-size: 0.88rem;
}

.split-bill-table__inline-link {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
}

.split-bill-table__row--interactive {
  transition:
    border-color 0.18s ease,
    background-color 0.18s ease,
    box-shadow 0.18s ease;
}

.split-bill-table__row--interactive:hover {
  border-color: rgba(3, 168, 192, 0.18);
  background: rgba(255, 255, 255, 0.88);
  box-shadow: 0 8px 20px rgba(15, 23, 42, 0.06);
}

.split-bill-table__row-action {
  display: flex;
  justify-content: flex-end;
}

.split-bill-table__chevron {
  appearance: none;
  border: 0;
  background: transparent;
  color: var(--accent);
  font-size: 28px;
  line-height: 1;
  padding: 0 4px;
  cursor: pointer;
}

.split-bill-table__chips {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  min-width: 0;
  padding-left: 6px;
}

.split-bill-table__avatar {
  flex: 0 0 auto;
  margin-left: -6px;
  border: 2px solid rgba(255, 255, 255, 0.96);
  box-shadow: 0 2px 6px rgba(15, 23, 42, 0.12);
}

.split-bill-table__avatar:first-child {
  margin-left: 0;
}

.split-bill-table__avatar-more {
  display: inline-grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 999px;
  background: #25324a;
  color: #fff;
  font-size: 0.68rem;
  font-weight: 800;
}

.split-bill-table__chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 32px;
  height: 32px;
  padding: 0 10px;
  border-radius: 999px;
  background: rgba(3, 168, 192, 0.12);
  border: 1px solid rgba(3, 168, 192, 0.18);
  color: var(--text-primary);
  font-size: 0.8rem;
  font-weight: 600;
}

.split-bill-table__chip--editable {
  position: relative;
  justify-content: flex-start;
  padding-right: 24px;
}

.split-bill-table__chip-remove {
  position: absolute;
  top: 2px;
  right: 4px;
  display: inline-grid;
  place-items: center;
