.split-bill-qr-card {
  --qr-start: #009fb6;
  --qr-end: #55d0c8;
  --qr-accent: #e4fffb;
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 108px;
  gap: 14px;
  min-height: 190px;
  padding: 18px;
  overflow: hidden;
  border: 0;
  border-radius: 24px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.16), transparent 48%),
    linear-gradient(135deg, var(--qr-start), var(--qr-end));
  box-shadow: 0 16px 34px color-mix(in srgb, var(--qr-start) 24%, transparent);
  color: #fff;
  transition: transform 180ms ease, box-shadow 180ms ease;
}

.split-bill-qr-card::after {
  content: "";
  position: absolute;
  width: 190px;
  height: 190px;
  right: -72px;
  bottom: -100px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.1);
  pointer-events: none;
}

.split-bill-qr-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 20px 38px color-mix(in srgb, var(--qr-start) 30%, transparent);
}

.split-bill-qr-card__copy {
  display: grid;
  align-content: start;
  min-width: 0;
}

.split-bill-qr-card__provider {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}

