  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  flex: 0 0 30px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.16);
  color: var(--qr-accent);
  font-size: 1.05rem;
}

