  flex-direction: column;
}

.landing-page--snap {
  min-height: 100dvh;
  height: auto;
  overflow: visible;
  overscroll-behavior-y: contain;
  scroll-padding-top: 0;
}

.landing-page::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 12% 10%, rgba(3, 168, 192, 0.09), transparent 24%),
    radial-gradient(circle at 88% 12%, rgba(110, 231, 183, 0.08), transparent 22%),
    radial-gradient(circle at 50% 110%, rgba(9, 30, 42, 0.05), transparent 22%);
