  background: linear-gradient(100deg, rgba(3, 168, 192, 0.1), rgba(110, 231, 183, 0.26), rgba(3, 168, 192, 0.1));
  background-size: 220% 100%;
  animation: landing-auth-loading 1.1s ease-in-out infinite;
}

.landing-account-actions--loading {
  display: inline-block;
  border-radius: 999px;
  background: linear-gradient(100deg, rgba(3, 168, 192, 0.08), rgba(110, 231, 183, 0.2), rgba(3, 168, 192, 0.08));
  background-size: 220% 100%;
  animation: landing-auth-loading 1.1s ease-in-out infinite;
}

.landing-account-actions--loading-desktop {
  width: 136px;
  height: 36px;
}

.landing-account-actions--loading-mobile {
  width: 72px;
  height: 36px;
}

@keyframes landing-auth-loading {
  from { background-position: 100% 0; }
  to { background-position: -100% 0; }
}

.landing-account-cta__avatar {
  width: 24px;
  height: 24px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  flex: 0 0 auto;
  color: white;
  font-size: 10px;
  font-weight: 700;
}

.landing-account-cta__avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.landing-signup-modal {
  position: fixed;
  inset: 0;
  z-index: 2000;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(15, 35, 46, 0.46);
