  -webkit-backdrop-filter: blur(8px);
  overflow-y: auto;
  overscroll-behavior: contain;
}

.landing-signup-modal__panel {
  position: relative;
  width: min(100%, 560px);
  max-height: min(920px, calc(100dvh - 48px));
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  padding: 28px;
  border: 1px solid rgba(255, 255, 255, 0.72);
  border-radius: 28px;
  background: #ffffff;
  box-shadow: 0 28px 90px rgba(9, 30, 42, 0.24);
}

.landing-signup-modal__close {
  position: absolute;
  top: 14px;
  right: 16px;
  z-index: 1;
  width: 36px;
  height: 36px;
