  border-radius: 999px;
  background: rgba(255, 255, 255, 0.88);
  color: var(--muted);
  font-size: 24px;
  line-height: 1;
}

.landing-signup-modal__close:hover,
.landing-signup-modal__close:focus-visible {
  color: var(--text);
  border-color: rgba(3, 168, 192, 0.45);
