  gap: 6px;
  margin: 0 auto 12px;
  padding-right: 36px;
}

.landing-signup-modal__intro .eyebrow {
  margin: 0;
}

.landing-signup-modal__intro h2 {
  font-size: clamp(1.55rem, 4vw, 2rem);
  line-height: 1.08;
  letter-spacing: -0.04em;
}

.landing-signup-modal__intro > p:last-child {
  color: var(--muted);
