  margin: 0;
  padding: 8px 0 0;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  background: transparent;
  overflow: visible;
}

.landing-signup-modal .clover-auth-card__brand,
.landing-signup-modal .clover-auth-card__header,
.landing-signup-modal .clover-auth-card__footer {
  display: none;
}

.landing-signup-modal .clover-auth-card__socials {
  margin-top: 2px;
}

@media (max-width: 1100px) {
  .landing-cta-actions__loading {
    width: min(236px, 100%);
  }

  .landing-signup-modal {
    align-items: end;
    padding: max(12px, env(safe-area-inset-top)) 12px max(12px, env(safe-area-inset-bottom));
  }

  .landing-signup-modal__panel {
    max-height: calc(100dvh - 24px - env(safe-area-inset-top) - env(safe-area-inset-bottom));
