}

.landing-page .landing-hero__copy {
  display: grid;
  gap: 16px;
  max-width: 520px;
  min-width: 0;
}

.landing-page .landing-hero__title {
  color: var(--text);
  display: grid;
  gap: 0.18em;
  font-size: clamp(1.55rem, 2.65vw, 3.15rem);
  line-height: 1.04;
  letter-spacing: 0;
  max-width: 20ch;
}

.landing-page .landing-hero__title span {
  display: block;
}

.landing-page .landing-hero__lede {
