}

.landing-feature--pro .landing-feature__body {
  color: rgba(255, 255, 255, 0.78);
}

.landing-feature--pro .landing-highlight,
.landing-feature--pro .landing-feature__body strong {
  color: var(--mint);
}

.landing-bridge {
  padding: clamp(52px, 7vw, 76px) 0 clamp(100px, 13vw, 170px);
  border-top: 1px solid rgba(15, 23, 42, 0.06);
  border-bottom: 1px solid rgba(15, 23, 42, 0.06);
}

.landing-bridge__inner {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(250px, 0.85fr);
  gap: clamp(34px, 6vw, 76px);
  align-items: center;
  width: min(940px, 100%);
  margin: 0 auto;
}

.landing-bridge__table-wrap {
  grid-column: 1;
  grid-row: 1;
  margin-top: 0;
  overflow: visible;
  padding: 0 2px 6px;
}

.landing-bridge__copy {
  grid-column: 2;
  grid-row: 1;
}

.landing-bridge__title {
  max-width: 18ch;
  color: var(--text);
  font-size: clamp(1.65rem, 2.4vw, 2.35rem);
  line-height: 1.14;
  letter-spacing: 0;
  text-align: left;
}

.landing-bridge__subtitle {
  width: min(620px, 100%);
  margin: 18px 0 0;
