}

.landing-bridge__table {
  width: 100%;
  min-width: 0;
  table-layout: fixed;
  border-collapse: separate;
  border-spacing: 0 7px;
  color: var(--muted);
  font-size: clamp(13px, 1.15vw, 15px);
  line-height: 1.35;
  text-align: left;
}

.landing-bridge__table th {
  padding: 0 18px 6px;
  color: #71808d;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: capitalize;
}

.landing-bridge__table th,
.landing-bridge__table td {
  width: 50%;
}

.landing-bridge__table td {
  padding: 14px 18px;
  border-top: 1px solid rgba(15, 23, 42, 0.08);
  border-bottom: 1px solid rgba(15, 23, 42, 0.08);
  background: rgba(255, 255, 255, 0.72);
}

.landing-bridge__table td:first-child {
  border-left: 1px solid rgba(15, 23, 42, 0.08);
  border-radius: 18px 0 0 18px;
  color: #788692;
}

.landing-bridge__clover-heading {
  color: var(--accent) !important;
}

.landing-bridge__clover-cell {
  border-right: 1px solid rgba(3, 168, 192, 0.22) !important;
  border-left: 3px solid var(--accent) !important;
  border-color: rgba(3, 168, 192, 0.22);
  border-radius: 0 18px 18px 0;
  background: linear-gradient(100deg, rgba(3, 168, 192, 0.12), rgba(110, 231, 183, 0.14)) !important;
  color: var(--text);
  box-shadow: 0 14px 34px rgba(3, 168, 192, 0.08);
}

.landing-bridge__clover-cell strong {
  color: var(--accent);
  font-weight: 700;
}

.landing-bridge.is-visible .landing-bridge__table tbody tr {
  animation: landing-bridge-row-enter 560ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.landing-bridge.is-visible .landing-bridge__table tbody tr:nth-child(2) { animation-delay: 80ms; }
.landing-bridge.is-visible .landing-bridge__table tbody tr:nth-child(3) { animation-delay: 160ms; }
.landing-bridge.is-visible .landing-bridge__table tbody tr:nth-child(4) { animation-delay: 240ms; }

@keyframes landing-bridge-row-enter {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}

.landing-highlight {
  color: var(--accent);
  font-weight: 600;
}

.landing-story-reveal {
  opacity: 0;
  transform: translateY(34px) scale(0.988);
  transition:
    opacity 480ms cubic-bezier(0.22, 1, 0.36, 1) var(--story-delay, 0ms),
    transform 560ms cubic-bezier(0.22, 1, 0.36, 1) var(--story-delay, 0ms);
  will-change: opacity, transform;
}

.landing-story-reveal.is-visible {
  opacity: 1;
  transform: translateY(0) scale(1);
}

.landing-hero__outcomes {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 4px;
}

.landing-hero__outcomes span {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 10px;
  border: 1px solid rgba(3, 168, 192, 0.14);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.7);
  color: #53616f;
  font-size: 11px;
  letter-spacing: 0.02em;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.04);
}

.clarity-engine {
  position: relative;
  width: min(640px, 52vw);
  margin-left: -28px;
  isolation: isolate;
}

.clarity-engine__glow {
  position: absolute;
  inset: 12% 4% 6%;
  border-radius: 50%;
  background:
    radial-gradient(circle at 35% 50%, rgba(3, 168, 192, 0.18), transparent 42%),
    radial-gradient(circle at 72% 46%, rgba(110, 231, 183, 0.16), transparent 44%);
  filter: blur(34px);
  opacity: 0.74;
  z-index: -1;
}

.clarity-engine__canvas {
  position: relative;
  width: 100%;
  aspect-ratio: 3 / 2;
  overflow: visible;
  animation: clarity-hero-enter 700ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.clarity-engine__layer {
  position: absolute;
  inset: 0;
  transform-origin: center;
}

.clarity-engine__layer--sources {
  clip-path: inset(0 57% 0 0);
  animation: clarity-sources 10s cubic-bezier(0.22, 1, 0.36, 1) infinite;
}

.clarity-engine__layer--workspace {
  clip-path: inset(0 0 0 35%);
  animation: clarity-workspace 10s cubic-bezier(0.22, 1, 0.36, 1) infinite;
}

.clarity-engine__image {
  object-fit: contain;
  filter: drop-shadow(0 24px 34px rgba(15, 23, 42, 0.11));
  animation: clarity-image-drift 7s ease-in-out infinite 800ms;
}

.clarity-engine__scan {
  position: absolute;
  left: 36.5%;
  top: 43%;
  width: 58px;
  height: 58px;
  display: grid;
  place-items: center;
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.94);
  border: 1px solid rgba(3, 168, 192, 0.15);
  box-shadow:
    0 18px 46px rgba(3, 168, 192, 0.18),
    0 0 0 10px rgba(255, 255, 255, 0.45);
  animation: clarity-scan 10s cubic-bezier(0.22, 1, 0.36, 1) infinite;
  z-index: 4;
}

.clarity-engine__scan::after {
  content: "";
  position: absolute;
  left: 50%;
  top: -220%;
  width: 2px;
  height: 340%;
  background: linear-gradient(180deg, transparent, rgba(3, 168, 192, 0.58), transparent);
  box-shadow: 0 0 18px rgba(3, 168, 192, 0.42);
}

.clarity-engine__scan img {
  width: 32px;
  height: 32px;
}

.clarity-engine__pulse {
  position: absolute;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 8px rgba(3, 168, 192, 0.09);
  animation: clarity-pulse 2.8s ease-in-out infinite;
  z-index: 3;
}

.clarity-engine__pulse--a {
  left: 31%;
  top: 34%;
}

.clarity-engine__pulse--b {
  right: 17%;
  bottom: 25%;
  background: var(--mint);
  animation-delay: 1.1s;
}

.clarity-engine__result-card {
  position: absolute;
  right: 2%;
  bottom: 8%;
  display: grid;
  gap: 2px;
  width: min(190px, 34%);
  padding: 12px 14px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid rgba(3, 168, 192, 0.14);
  box-shadow: 0 20px 54px rgba(15, 23, 42, 0.14);
  backdrop-filter: blur(16px);
  animation: clarity-result 10s cubic-bezier(0.22, 1, 0.36, 1) infinite;
  z-index: 5;
}

.clarity-engine__result-card strong {
  color: var(--text);
  font-size: 12px;
}

.clarity-engine__result-card span {
  color: var(--muted);
  font-size: 9px;
}

.clarity-engine__result-card .clarity-engine__result-kicker {
  color: var(--accent);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: capitalize;
}

.clarity-engine__status {
  position: relative;
  z-index: 6;
  display: grid;
  grid-template-columns: 8px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  width: min(430px, 78%);
  min-height: 44px;
  margin: -10px auto 0;
  padding: 0 16px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid rgba(3, 168, 192, 0.13);
  box-shadow: 0 18px 48px rgba(15, 23, 42, 0.09);
  backdrop-filter: blur(18px);
}

@keyframes clarity-hero-enter {
  from {
    opacity: 0;
    transform: translateY(18px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes clarity-image-drift {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px); }
}

.clarity-engine__status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--mint);
  box-shadow: 0 0 0 5px rgba(110, 231, 183, 0.14);
}

.clarity-engine__status-copy {
  position: relative;
  height: 18px;
  overflow: hidden;
  color: var(--text);
  font-size: 11px;
  font-weight: 600;
}

.clarity-engine__status-copy span {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  opacity: 0;
  transform: translateY(10px);
  animation: clarity-status 10s ease-in-out infinite;
  animation-delay: calc(var(--engine-stage) * 2.5s);
}

.clarity-engine__status-time {
  color: var(--accent);
  font-size: 10px;
  white-space: nowrap;
}

.landing-feature__chapter {
  margin: 0;
  color: #71808d;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: capitalize;
}

.landing-feature__visual {
  position: relative;
  isolation: isolate;
}

.landing-feature__visual::before {
  content: "";
  position: absolute;
  inset: 14% 8%;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(3, 168, 192, 0.1), rgba(110, 231, 183, 0.045) 45%, transparent 72%);
  filter: blur(22px);
  z-index: -1;
}

@keyframes clarity-sources {
  0%, 12%, 100% { opacity: 0.84; transform: translateX(-1.5%) scale(0.98); filter: blur(0); }
  28% { opacity: 1; transform: translateX(0) scale(1); filter: blur(0); }
  48% { opacity: 0.62; transform: translateX(5%) scale(0.96); filter: blur(0.6px); }
  62%, 78% { opacity: 0.26; transform: translateX(9%) scale(0.93); filter: blur(2px); }
  90% { opacity: 0.72; transform: translateX(0) scale(0.98); filter: blur(0); }
}

@keyframes clarity-workspace {
  0%, 14%, 100% { opacity: 0.4; transform: translateX(3%) scale(0.97); }
  34% { opacity: 0.62; transform: translateX(1%) scale(0.985); }
  54%, 82% { opacity: 1; transform: translateX(0) scale(1); }
  92% { opacity: 0.58; transform: translateX(2%) scale(0.98); }
}

@keyframes clarity-scan {
  0%, 14%, 100% { opacity: 0; transform: translateX(-36px) scale(0.82); }
  24% { opacity: 1; transform: translateX(-12px) scale(1); }
  48% { opacity: 1; transform: translateX(72px) scale(1); }
  62%, 92% { opacity: 0; transform: translateX(110px) scale(0.82); }
}

@keyframes clarity-result {
  0%, 48%, 100% { opacity: 0; transform: translateY(16px) scale(0.94); }
  60%, 84% { opacity: 1; transform: translateY(0) scale(1); }
  94% { opacity: 0; transform: translateY(-8px) scale(0.98); }
}

@keyframes clarity-status {
  0% { opacity: 1; transform: translateY(0); }
  23% { opacity: 1; transform: translateY(0); }
  25%, 100% { opacity: 0; transform: translateY(-8px); }
}

@keyframes clarity-pulse {
  0%, 100% { transform: scale(0.8); opacity: 0.5; }
  50% { transform: scale(1.15); opacity: 1; }
}

