.circles-add-person { display: flex; align-items: center; gap: 8px; width: 100%; min-height: 44px; padding: 10px 13px; border: 1px dashed var(--stroke-strong); border-radius: 14px; background: transparent; color: var(--accent-hover); font: inherit; font-size: 13px; cursor: pointer; }
