/* Original landing design with livelier, non-parallax motion. */
html:has(.landing-page),
body:has(.landing-page) {
  overflow-x: clip;
}

.landing-page .landing-hero__copy > * {
  opacity: 0;
  transform: translateY(18px);
  animation: landing-hero-rise 620ms cubic-bezier(.22, 1, .36, 1) forwards;
}

.landing-page .landing-hero__copy > :nth-child(1) { animation-delay: 80ms; }
.landing-page .landing-hero__copy > :nth-child(2) { animation-delay: 170ms; }
.landing-page .landing-hero__copy > :nth-child(3) { animation-delay: 260ms; }
.landing-page .landing-hero__copy > :nth-child(4) { animation-delay: 350ms; }

.landing-feature .landing-feature__copy,
.landing-feature .landing-feature__visual {
  opacity: 0;
  transition:
    opacity 420ms ease-out,
    transform 620ms cubic-bezier(.22, 1, .36, 1);
}

.landing-feature .landing-feature__copy {
  transform: translateX(-30px);
}

.landing-feature .landing-feature__visual {
  transform: translateX(32px) scale(.96);
}

.landing-feature--reverse .landing-feature__copy {
  transform: translateX(30px);
}

.landing-feature--reverse .landing-feature__visual {
  transform: translateX(-32px) scale(.96);
}

.landing-feature.is-visible .landing-feature__copy,
.landing-feature.is-visible .landing-feature__visual {
  opacity: 1;
  transform: translateX(0) scale(1);
}

.landing-feature.is-visible .landing-feature__visual {
  transition-delay: 80ms;
}

.landing-feature.is-visible .landing-asset__image {
  animation: landing-art-float 6.8s ease-in-out infinite;
}

.landing-feature:nth-of-type(even).is-visible .landing-asset__image {
  animation-delay: -2.1s;
}

.landing-feature:nth-of-type(3n).is-visible .landing-asset__image {
  animation-delay: -4.2s;
}

.landing-asset {
  position: relative;
  isolation: isolate;
}

.landing-asset::after {
  content: "";
  position: absolute;
  left: 18%;
  right: 18%;
  bottom: 4%;
  z-index: -1;
  height: 12%;
  border-radius: 50%;
  background: radial-gradient(ellipse, rgba(15, 35, 46, .16), transparent 70%);
  filter: blur(16px);
  opacity: 0;
  transform: scale(.82);
  transition: opacity 500ms ease 160ms, transform 700ms cubic-bezier(.22, 1, .36, 1) 160ms;
}

.landing-feature.is-visible .landing-asset::after {
  opacity: .72;
  transform: scale(1);
  animation: landing-shadow-breathe 6.8s ease-in-out infinite;
}

.landing-feature__title .landing-highlight,
.landing-hero__title .landing-highlight {
  position: relative;
  display: inline-block;
}

/* Let highlighted feature headings wrap at natural word boundaries. */
.landing-feature__title .landing-highlight {
  display: inline;
  text-decoration: underline;
  text-decoration-color: var(--mint);
  text-decoration-thickness: 0.08em;
  text-underline-offset: 0.08em;
}

.landing-feature__title .landing-highlight::after {
  display: none;
}

.landing-feature__title .landing-highlight::after,
.landing-hero__title .landing-highlight::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -.08em;
  height: .08em;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--accent), var(--mint));
  transform: scaleX(0);
  transform-origin: left;
}

.landing-feature.is-visible .landing-highlight::after,
.landing-hero.is-visible .landing-highlight::after {
  animation: landing-highlight-draw 680ms cubic-bezier(.22, 1, .36, 1) 260ms forwards;
}

.landing-hero__outcomes span {
  opacity: 0;
  transform: translateY(8px) scale(.94);
  animation: landing-chip-enter 420ms cubic-bezier(.22, 1, .36, 1) forwards;
}

.landing-hero__outcomes span:nth-child(1) { animation-delay: 410ms; }
.landing-hero__outcomes span:nth-child(2) { animation-delay: 470ms; }
.landing-hero__outcomes span:nth-child(3) { animation-delay: 530ms; }
.landing-hero__outcomes span:nth-child(4) { animation-delay: 590ms; }
.landing-hero__outcomes span:nth-child(5) { animation-delay: 650ms; }

.landing-page .button-primary {
  overflow: hidden;
  position: relative;
}

.landing-page .button-primary::after {
  content: "";
  position: absolute;
  top: -80%;
  bottom: -80%;
  left: -45%;
  width: 30%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,.5), transparent);
  transform: rotate(18deg);
  animation: landing-button-sheen 4.6s ease-in-out infinite 1.4s;
}

.landing-cta.is-visible .landing-cta__copy,
.landing-cta.is-visible .landing-cta__actions {
  animation: landing-cta-settle 560ms cubic-bezier(.22, 1, .36, 1) both;
}

.landing-cta.is-visible .landing-cta__actions {
  animation-delay: 90ms;
}

@keyframes landing-hero-rise {
  to { opacity: 1; transform: translateY(0); }
}

@keyframes landing-art-float {
