/* Keep these Settings rules last so legacy responsive declarations cannot re-expand them. */
.settings-category-table--plain {
  overflow: visible;
  border: 0;
  border-radius: 0;
  background: transparent;
}

.settings-category-table--plain.settings-category-table--compact .settings-category-table__row {
  grid-template-columns: minmax(0, 1fr) auto;
  padding-inline: 0;
}

.settings-plan-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.settings-plan-usage {
  grid-template-columns: 1fr;
  gap: 0;
}

@media (max-width: 1100px) {
  .settings-hub--mobile-panel .settings-section__intro {
    display: none;
  }

  .settings-hub--mobile-panel .settings-hub__panel {
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
