  .mobile-swipe-delete {
    position: relative;
    display: block;
    min-width: 0;
    overflow: hidden;
  }

  .mobile-swipe-delete__action {
    position: absolute;
    z-index: 0;
    inset: 0 0 0 auto;
    display: grid;
    width: 82px;
    min-height: 100%;
    place-content: center;
    justify-items: center;
    gap: 3px;
    padding: 6px;
    border: 0;
    border-radius: 0;
    background: #e6464f;
    color: #fff;
    font: inherit;
    font-size: 0.7rem;
    font-weight: 700;
    cursor: pointer;
  }

  .mobile-swipe-delete__action svg {
    width: 18px;
    height: 18px;
  }

  .mobile-swipe-delete__action:focus-visible {
    outline: 3px solid color-mix(in srgb, #e6464f 35%, white);
    outline-offset: -3px;
  }

  .mobile-swipe-delete__content {
    position: relative;
    z-index: 1;
    display: block;
    min-width: 0;
    background: var(--surface);
    transform: translate3d(var(--mobile-swipe-offset, 0), 0, 0);
    transition: transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1);
    touch-action: pan-y;
    will-change: transform;
  }

  .mobile-swipe-delete.is-dragging .mobile-swipe-delete__content {
    transition: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .mobile-swipe-delete__content {
    transition: none;
  }
}

/* Shared manual-entry affordances keep Dashboard and Transactions behavior aligned. */
.transaction-name-autocomplete,
.transaction-category-picker {
  position: relative;
  min-width: 0;
  width: 100%;
}

.transaction-name-autocomplete__menu,
.transaction-category-picker__menu {
  position: absolute;
  z-index: 80;
  top: calc(100% + 7px);
  left: 0;
  width: 100%;
  overflow: hidden;
  border: 1px solid rgba(3, 168, 192, 0.18);
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.99);
  box-shadow: 0 18px 48px rgba(20, 48, 62, 0.16);
}

.transaction-name-autocomplete__option {
  width: 100%;
  min-height: 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 12px;
  border: 0;
  border-bottom: 1px solid rgba(29, 56, 70, 0.08);
  background: transparent;
  color: var(--text);
  text-align: left;
  font: inherit;
  cursor: pointer;
}

.transaction-name-autocomplete__option:last-child { border-bottom: 0; }
.transaction-name-autocomplete__option:hover,
.transaction-name-autocomplete__option:focus-visible { background: rgba(3, 168, 192, 0.08); outline: none; }
.transaction-name-autocomplete__option > span { min-width: 0; display: grid; gap: 2px; }
.transaction-name-autocomplete__option strong { overflow: hidden; font-size: 0.86rem; text-overflow: ellipsis; white-space: nowrap; }
.transaction-name-autocomplete__option small { overflow: hidden; color: var(--muted); font-size: 0.74rem; text-overflow: ellipsis; white-space: nowrap; }
.transaction-name-autocomplete__option em { flex: 0 0 auto; color: var(--accent); font-size: 0.7rem; font-style: normal; font-weight: 700; }

.transaction-category-picker__head {
  display: none;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 14px 6px;
}

.transaction-category-picker__head button {
  width: 36px;
  height: 36px;
  border: 0;
  background: transparent;
  color: var(--text);
  font-size: 1.35rem;
  cursor: pointer;
}

.transaction-category-picker__search {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 7px;
  padding: 0 10px;
  border: 1px solid var(--stroke);
  border-radius: 12px;
  background: var(--surface);
}

.transaction-category-picker__search input {
  min-height: 40px;
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
  font-size: 0.84rem;
}

.transaction-category-picker__list {
  max-height: 300px;
  overflow-y: auto;
  padding: 0 7px 7px;
}

.transaction-category-picker__type-group { display: grid; }
.transaction-category-picker__type-group + .transaction-category-picker__type-group { margin-top: 5px; padding-top: 5px; border-top: 1px solid rgba(29, 56, 70, 0.08); }
.transaction-category-picker__type-group > p { margin: 0; padding: 5px 9px 3px; color: var(--muted); font-size: 0.68rem; font-weight: 750; letter-spacing: 0.09em; }
.transaction-category-picker__group { display: grid; }
.transaction-category-picker__children { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 3px; padding: 0 0 5px 26px; }
.transaction-category-picker__option {
  min-width: 0;
  min-height: 44px;
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr) auto;
  align-items: center;
  gap: 9px;
  padding: 6px 9px;
  border: 0;
  border-radius: 12px;
  background: transparent;
  color: var(--text);
  text-align: left;
  font: inherit;
  font-size: 0.82rem;
  cursor: pointer;
}
.transaction-category-picker__option.is-child { grid-template-columns: 26px minmax(0, 1fr) auto; min-height: 40px; color: var(--muted); font-size: 0.76rem; }
.transaction-category-picker__option > .transaction-category-icon { width: 30px; height: 30px; }
.transaction-category-picker__option.is-child > .transaction-category-icon { width: 25px; height: 25px; }
.transaction-category-picker__option:hover,
.transaction-category-picker__option:focus-visible,
.transaction-category-picker__option.is-selected { background: rgba(3, 168, 192, 0.08); outline: none; }
.transaction-category-picker__check { color: var(--accent); font-weight: 800; }

.transactions-manual-type-toggle__button.is-active:nth-of-type(3) {
  box-shadow: 2px 5px 12px rgba(3, 168, 192, 0.09), 0 0 0 2px rgba(3, 168, 192, 0.06);
}

@media (max-width: 1100px) {
  .transaction-category-picker__menu {
    position: fixed;
    z-index: 10020;
    top: auto;
    right: 8px;
    bottom: max(8px, env(safe-area-inset-bottom));
    left: 8px;
    width: auto;
    max-height: min(72dvh, 620px);
    border-radius: 24px;
    animation: clover-category-sheet-in 180ms cubic-bezier(0.2, 0.8, 0.2, 1);
  }

  .transaction-category-picker__head { display: flex; }
  .transaction-category-picker__list { max-height: calc(min(72dvh, 620px) - 112px); }
  .transaction-category-picker__option { min-height: 48px; font-size: 0.9rem; }

  .dashboard-home__report-card .eyebrow { font-size: 13px; letter-spacing: 0.1em; }
  .dashboard-home__report-card .dashboard-home__report-note { font-size: 14px; line-height: 1.45; }
  .dashboard-home__report-metrics small { font-size: 11px; letter-spacing: 0.05em; }
  .dashboard-home__report-metrics strong { font-size: 14px; }
  .dashboard-home__report-flow-label,
  .dashboard-home__report-flow-timeline span,
  .dashboard-home__report-flow-legend span { font-size: 11px; }
  .dashboard-home__report-link { font-size: 14px; }
  .dashboard-home__insight-strip-label span:not(.dashboard-home__insight-strip-emoji) { font-size: 12px; }
  .dashboard-home__insight-strip-copy { font-size: 14px; line-height: 1.45; }
  .dashboard-home__insight-strip-action { font-size: 14px; }
}

@keyframes clover-category-sheet-in {
  from { opacity: 0; transform: translateY(18px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .transaction-category-picker__menu { animation: none; }
}

.settings-category-table--plain .settings-category-table__row--compact.settings-category-table__row--custom {
  grid-template-columns: minmax(0, 1fr) minmax(130px, 0.42fr) auto;
}

.settings-category-table__group select {
  min-height: 38px;
  border-radius: 12px;
  font-size: 0.8rem;
}

/* Mobile navigation has one stable full state and one compact scrolling state. */
.shell-mobile-more-link {
  display: none;
}

@media (max-width: 1100px) {
  .shell-topbar-leading {
    display: flex !important;
    grid-column: 1 !important;
    grid-row: 1 !important;
    align-items: center;
    gap: 6px;
    min-width: 44px;
  }

  .shell-mobile-more-link {
    display: inline-flex;
    width: 44px;
    height: 44px;
    flex: 0 0 44px;
    align-items: center;
    justify-content: center;
    border: 1px solid var(--stroke);
    border-radius: 50%;
    background: var(--surface);
    color: var(--text);
    box-shadow: var(--shadow-soft);
    text-decoration: none;
    transition: background-color 160ms ease, border-color 160ms ease, transform 160ms ease;
  }

  .shell-mobile-more-link:hover,
  .shell-mobile-more-link:focus-visible,
  .shell-mobile-more-link.is-active {
    border-color: rgba(3, 168, 192, 0.24);
    background: rgba(3, 168, 192, 0.1);
    color: var(--accent);
    outline: none;
  }

  .shell-mobile-more-link:active {
    transform: scale(0.96);
  }

  .shell-mobile-more-link svg {
    width: 18px;
    height: 18px;
  }

  .shell-bottom-nav {
    min-height: 74px;
    transition:
      min-height 180ms cubic-bezier(0.2, 0.8, 0.2, 1),
      padding 180ms cubic-bezier(0.2, 0.8, 0.2, 1),
      border-radius 180ms ease,
      box-shadow 180ms ease,
      transform 180ms ease;
  }

  .shell-bottom-nav__item,
  .shell-bottom-nav__add,
  .shell-bottom-nav__icon,
  .shell-bottom-nav__icon .menu-icon-3d,
  .shell-bottom-nav__label {
    transition:
      width 180ms cubic-bezier(0.2, 0.8, 0.2, 1),
      height 180ms cubic-bezier(0.2, 0.8, 0.2, 1),
      min-height 180ms cubic-bezier(0.2, 0.8, 0.2, 1),
      padding 180ms cubic-bezier(0.2, 0.8, 0.2, 1),
      opacity 120ms ease,
      transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1);
  }

  .shell-bottom-nav__profile-photo {
    width: 38px;
    height: 38px;
    border: 2px solid rgba(3, 168, 192, 0.2);
    border-radius: 50%;
    object-fit: cover;
  }

  .shell-bottom-nav.is-compact {
    min-height: 52px;
    padding: 3px 7px !important;
    border-radius: 20px;
    box-shadow:
      0 10px 22px rgba(15, 23, 42, 0.14),
      inset 0 1px 0 rgba(255, 255, 255, 0.62);
  }

  .shell-bottom-nav.is-compact .shell-bottom-nav__item {
    min-height: 44px;
    padding: 0 2px;
  }

  .shell-bottom-nav.is-compact .shell-bottom-nav__icon {
    width: 30px;
    height: 30px;
  }

  .shell-bottom-nav.is-compact .shell-bottom-nav__icon .menu-icon-3d,
  .shell-bottom-nav.is-compact .shell-bottom-nav__icon .menu-icon-3d--home,
  .shell-bottom-nav.is-compact .shell-bottom-nav__icon .menu-icon-3d--adviser {
    width: 30px;
    height: 30px;
  }

  .shell-bottom-nav.is-compact .shell-bottom-nav__profile-photo {
    width: 28px;
    height: 28px;
  }

  .shell-bottom-nav.is-compact .shell-bottom-nav__label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    opacity: 0;
  }

  .shell-bottom-nav.is-compact .shell-bottom-nav__add {
    width: 44px;
    height: 44px;
    min-height: 44px;
    box-shadow: 0 10px 22px rgba(3, 168, 192, 0.2);
  }
}

@media (prefers-reduced-motion: reduce) {
  .shell-mobile-more-link,
  .shell-bottom-nav,
  .shell-bottom-nav__item,
  .shell-bottom-nav__add,
  .shell-bottom-nav__icon,
  .shell-bottom-nav__icon .menu-icon-3d,
  .shell-bottom-nav__label {
    transition: none !important;
  }
}

@media (max-width: 700px) {
  .settings-category-table--plain .settings-category-table__row--compact.settings-category-table__row--custom {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .settings-category-table__group {
    grid-column: 1 / -1;
    padding-left: 42px;
  }
}
